(window.GIM_TS=window.GIM_TS||{})["Bava Kamma.4"]={"from":96,"a":[["\u0003בבור\u0004 שחפרו ברשותו, ולאחר שחפרו הפקיר רשותו (ולא בורו) לרבים, שנתן לרבים ללכת \u0003ברשותו. ר' עקיבא סבר\u0004 \u0005[סבור]:\u0006 על \u0003בור\u0004 שחפרו \u0003ברשותו נמי\u0004 \u0005[גם כן]\u0006 \u0003חייב\u0004 ולא רק על בור שחפרו ברשות הרבים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בעל הבור\u0004 ישלם\u0003\"\u0004 (שמות כא, לד), כלומר, אף \u0003בבור דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003בעלים קאמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 שהוא חייב, אף שאין הבור ברשות הרבים.","\u0003ור' ישמעאל סבר\u0004 \u0005[סבור]:\u0006 \"בעל הבור\" פירושו \u0003בעל התקלה, שבשעה שחפרו היה הוא תקלה ברשות הרבים, ואולם לא מי שחפר את הבור ברשותו. ושואלים:\u0004","\u0003אלא\u0004 ולהסברו זה של רבה \u0003מאי\u0004 \u0005[מה]\u0006 פירוש ההדגשה \u0003\"זהו בור האמור בתורה\", דקאמר\u0004 \u0005[שאומר]\u0006 \u0003ר' עקיבא\u0004 ביחס לחופר בור ברשותו? שהרי לשיטתו אינו ממעט בור כלשהו, וגם בור ברשות הרבים חייב! ומשיבים, כוונתו: \u0003זהו בור שפתח בו הכתוב תחלה לתשלומין,\u0004 שלדעתו גם דין בור זה נתפרש בכתוב, במקום שהוזכר חיוב תשלומים של בור (\"בעל השור ישלם\" שמות כא, לד), ולא רק בור שחפרו ברשות הרבים. עד כאן הסברו של רבה למחלוקת ר' ישמעאל ור' עקיבא.","\u0003ורב יוסף אמר\u0004 הסבר אחר במחלוקתם: \u0003בבור\u0004 שחפרו \u0003ברשות היחיד\u0004 והפקיר את רשותו \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003מחייב, מאי טעמא\u0004 \u0005[מה הטעם]\u0006 — \u0003\"בעל הבור\" אמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 משמע כי \u0003בבור דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003בעלים עסקינן\u0004 \u0005[אנו עוסקים].\u0006","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בבור\u0004 שחפרו \u0003ברשות הרבים, ר' ישמעאל סבר\u0004 \u0005[סבור]:\u0006 \u0003בור ברשות הרבים נמי\u0004 \u0005[גם כן]\u0006 \u0003חייב, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"כי יפתח\" ו\"כי יכרה\"\u0004 (שמות כא, לג), ונשאלת השאלה: \u0003אם על פתיחה חייב, על כרייה לא כל שכן? אלא\u0004 כוונתו של הכתוב לבור כזה \u0003שעל עסקי פתיחה ועל עסקי כרייה באה לו\u0004 האחריות, אף שאין הבור שלו.","\u0003ור' עקיבא\u0004 סבור: דווקא בור שחפרו ברשותו ולאחר מכן הפקיר את רשותו הוא שחייב עליו, ואין ללמוד מייתור הכתובים, כי \u0003הנהו\u0004 \u0005[אלו]\u0006 שני הכתובים \u0003מיצרך צריכי\u0004 \u0005[נצרכים\u0006 הם\u0005]\u0006 ואינם נלמדים זה מזה; \u0003דאי כתב רחמנא\u0004 \u0005[שאילו כתבה התורה]\u0006 רק \u0003\"כי יפתח\" הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 דווקא מי ש\u0003פותח\u0004 כיסוי של בור חפור \u0003הוא דסגי ליה\u0004 \u0005[שדי לו]\u0006 \u0003בכסוי\u0004 כדי לסלק מעליו אחריות לנזקי הבור (כלשון הכתוב \"ולא יכסנו\", שמות כא, לג). אבל \u0003כורה\u0004 בור \u0003לא סגי ליה\u0004 \u0005[די לו]\u0006 \u0003בכסוי עד דטאים ליה\u0004 \u0005[שיסתום אותו]\u0006.","\u0003ו\u0004להיפך, \u0003אי כתב רחמנא\u0004 \u0005[אילו כתבה התורה]\u0006 רק \u0003\"כי יכרה\" הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003כרייה הוא דבעי\u0004 \u0005[שצריך]\u0006 \u0003כסוי, משום דעבד\u0004 \u0005[שעשה]\u0006 \u0003מעשה\u0004 ויצר בור, \u0003אבל פותח\u0004 ש\u0003לא עבד\u0004 \u0005[עשה]\u0006 \u0003מעשה, אימא\u0004 \u0005[אמור]\u0006 ש\u0003כסוי נמי לא בעי\u0004 \u0005[גם כן אינו צריך]\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב בשניהם את חיובו בנזקי הבור. ולכן יש לפרש \"בעל הבור\" כמשמעו — שהוא בעליו של הבור.","ושואלים: \u0003ואלא\u0004 לפי הסבר זה של רב יוסף \u0003מאי\u0004 \u0005[מה]\u0006 פירוש ההדגשה \u0003\"זהו בור האמור בתורה\" דקאמר\u0004 \u0005[שאומר]\u0006 \u0003ר' ישמעאל\u0004 על בור שחפרו ברשות הרבים, אף שמחייב בכל בור — כוונתו: \u0003זהו בור שפתח בו הכתוב תחלה לניזקין,\u0004 שקודם הוזכר בתורה אופן זה של בור (שמות כא, לג) ואחר כך נאמר \"בעל הבור ישלם\" שעוסק בבור שחפרו ברשותו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003החופר בור\u0004 שחללו \u0003ברשות הרבים ופתחו לרשות היחיד\u0004 — \u0003פטור, ואף על פי שאינו רשאי לעשות כן, לפי שאין עושין חלל תחת רשות הרבים. ואילו\u0004","\u0003החופר בורות, שיחין\u0004 (בורות מרובעים) \u0003ומערות\u0004 (חפירות שיש להן תקרה) \u0003ברשות היחיד ופתחו לרשות הרבים\u0004 — \u0003חייב. והחופר בורות ברשות היחיד הסמוכה לרשות הרבים\u0004 אבל לא ברשות הרבים עצמה, \u0003כגון אלו החופרים לאושין\u0004 (יסודות) של ביתם, או חומתם — \u0003פטור.\u0004 \u0003ור' יוסי בר' יהודה מחייב\u0004 אף על נזקים שגרמו בורות אלה שנעשו לאושין \u0003עד שיעשה מחיצה\u0004 בגובה של \u0003עשרה\u0004 טפחים לפני הבורות הללו, \u0003או עד שירחיק\u0004 אותם \u0003ממקום דריסת\u0004 (הליכת) \u0003רגלי אדם וממקום דריסת רגלי בהמה ארבעה טפחים.\u0004","ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 שפטור אם חפר \u0003לאושין\u0004 שדרך לעשות כן, \u0003הא לאו\u0004 \u0005[הרי\u0006 אם לא] היה חופר \u0003ל\u0004צורך \u0003אושין\u0004 — \u0003חייב,\u0004 למרות שחפר ופתח את הבור ברשותו, הואיל ואנשים הולכים שם.","ויש לשאול: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו כ\u0006שיטת \u0005מי היא]?\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבה\u0004 אפשר לומר כי \u0003רישא\u0004 \u0005[ראשה]\u0006 שפטור אם פתח את הבור לרשותו, ומשמע: אף אם הפקיר אחר כך את רשותו — כדברי \u0003ר' ישמעאל, וסיפא\u0004 \u0005[וסופה]\u0006 — כדברי \u0003ר' עקיבא\u0004 שהוא סבור שבור שנחפר ברשותו אם רבים מהלכים שם — חייב.","\u0003אלא לרב יוסף, בשלמא סיפא\u0004 \u0005[נניח סופה]\u0006 \u0003דברי הכל, אלא רישא\u0004 \u0005[ראשה]\u0006 שפטור על בור ברשותו, \u0003מני\u0004 [כשיטת \u0005מי היא]?\u0006 \u0003לא\u0004 כשיטת \u0003ר' ישמעאל ולא כ\u0004שיטת \u0003ר' עקיבא,\u0004 שהרי רב יוסף סבור שלדעת שניהם מתחייב אדם בבור שחפר שברשותו, אף אם הפקיר רשותו!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב יוסף:\u0004 אפשר לומר כי \u0003כולה דברי הכל היא, ורישא\u0004 \u0005[ותחילתה]\u0006 שחפר בור תחת ברשות הרבים ופתחו לרשותו, מדובר במקרה \u0003שלא הפקיר לא רשותו ולא בורו,\u0004 שזה ודאי אינו בתורת בור לענין חיוב נזיקין, ולכן פטור בו.","\u0003אמר רב אשי: השתא דאוקימתא\u0004 \u0005[עכשיו שהעמדת]\u0006 והסברת את הברייתא \u0003ל\u0004שיטת \u0003רב יוסף לדברי הכל, ל\u0004שיטת \u0003רבה נמי לא תוקמה כתנאי\u0004 \u0005[גם כן אל תעמיד,\u0006 תסביר \u0005אותה כמחלוקת\u0006 \u0005תנאים],\u0006 ואמור כך:","\u0003מדרישא\u0004 \u0005[מכיון שתחילתה]\u0006 כשיטת \u0003ר' ישמעאל\u0004 שפוטר אם הפקיר רשותו ולא הפקיר בורו — \u0003סיפא נמי\u0004 \u0005[סופה גם כן]\u0006 כשיטת \u0003ר' ישמעאל.\u0004 ומה שדייקנו: \u0003וטעמא\u0004 \u0005[\u0006והטעם דווקא] משום שחפר ברשות היחיד הסמוכה לרשות הרבים \u0003לאושין\u0004 פטור, \u0003הא לאו\u0004 \u0005[אבל לא]\u0006 \u0003לאושין חייב\u0004 — יש להסביר: \u0003כגון דארווח ארווחי\u0004 \u0005[שהרוויח,\u0006 עשה רווח יתר] \u0003ל\u0004צד \u0003רשות הרבים\u0004 ונמצא חופר בור ברשות הרבים ממש.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003החופר בור ברשות היחיד ופתחו לרשות הרבים\u0004 — \u0003חייב,\u0004 חפר \u0003ברשות היחיד הסמוכה לרשות הרבים\u0004 — \u0003פטור.\u0004 ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבה\u0004 אפשר לומר כי המשנה הזו \u0003כולה\u0004 כשיטת \u0003ר' ישמעאל היא\u0004 שאינו מחייב על בור שחפר ברשותו. \u0003אלא לרב יוסף, בשלמא רישא\u0004 \u0005[נניח תחילתה]\u0006 לדעתו כשיטת \u0003ר' ישמעאל\u0004 שמחייב אף אם חפר ברשות הרבים, \u0003אלא סיפא מני\u0004 \u0005[סופה\u0006 כשיטת \u0005מי היא]?\u0006 \u0003לא\u0004 כשיטת \u0003ר' ישמעאל ולא\u0004 כשיטת \u0003ר' עקיבא!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 רב יוסף: פה מדובר \u0003בחופר לאושין ו\u0004כ\u0003דברי הכל\u0004 היא.","ועוד בענין דומה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מי ש\u0003חפר\u0004 בור וכן אם \u0003פתח\u0004 בור \u0003ומסר\u0004 אותו \u0003לרבים\u0004 להשתמש בו — \u0003פטור\u0004 על כל הנזקים שגרם בורו, \u0003חפר ופתח ולא מסר לרבים\u0004 — \u0003חייב; וכן\u0004 היה \u0003מנהגו של נחוניא חופר בורות שיחין ומערות, שהיה חופר ופותח\u0004 בורות \u0003ומוסר\u0004 אותם \u0003לרבים,\u0004 כדי שיהיו בורות מים לצורכי הרבים. \u0003וכששמעו חכמים בדבר, אמרו: קיים זה הלכה זו.\u0004 ותוהים: \u0003הלכה זו ותו לא\u0004 \u0005[ולא עוד]?\u0006 והלא יודעים אנו שנחוניא אדם גדול היה! \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003אף הלכה זו\u0004 קיים, ולא שכח מלמסור הבורות לרבים.","כיון שהזכרנו את מעשיו של נחוניא חופר שיחין מספרים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בבתו של נחוניא חופר שיחין שנפלה לבור גדול\u0004 ונעלמה ולא יכלו להוציאה, \u0003באו והודיעו את ר' חנינא בן דוסא\u0004 שיתפלל עליה. \u0003שעה ראשונה\u0004 משנפלה \u0003אמר להם: שלום,\u0004 כלומר, ודאי שלום לה. שעה \u0003שניה אמר להם: שלום. שלישית אמר להם:\u0004 בוודאי כבר \u0003עלתה.\u0004 ואכן כך היה.","\u0003אמרו לה: מי העלך\u0004 מן הבור? \u0003אמרה להם: זכר של רחלים\u0004 (=איל) \u0003נזדמן לי וזקן אחד\u0004 (הוא אברהם אבינו) \u0003מנהיגו ועל ידו ניצלתי\u0004. \u0003אמרו לו\u0004 לר' חנינא: \u0003נביא אתה\u0004 שידעת שתצא? \u0003אמר להם: \"לא נביא אנכי, ולא בן נביא אנכי\"\u0004 (ראה עמוס ז, יד), \u0003אלא כך אמרתי\u0004 בליבי: וכי \u0003דבר שאותו צדיק\u0004 נחוניא \u0003מצטער\u0004 (טורח ועמל) \u0003בו\u0004 (בחפירת בורות) \u0003יכשל בו זרעו?\u0004","\u0003אמר ר' אחא: אף על פי כן\u0004 אירע ש\u0003מת בנו\u0004 של נחוניא \u0003בצמא\u0004 אף שנחוניא היה דואג לכל שיהיו להם מים. ושכך הוא מנהגו של הקדוש ברוך הוא עם הצדיקים למדנו ממה \u0003שנאמר: \"וסביביו נשערה מאד\"\u0004 (תהלים נ, ג), \u0003מלמד שהקדוש ברוך הוא מדקדק עם סביביו,\u0004 כלומר, עם אלה הסובבים אותו והקרובים אליו שהם הצדיקים \u0003אפילו כחוט השערה,\u0004 שאם חטאו אף חטא קל מענישם עונש קשה יותר משאר בני אדם. \u0003ר' נחוניא אמר: מהכא\u0004 \u0005[מכאן],\u0006 מפסוק זה אפשר ללמוד אותו רעיון: \u0003\"אל נערץ בסוד קדשים רבה ונורא על כל סביביו\"\u0004 (תהלים פט, ח).","\u0003אמר ר' חנינא: כל האומר הקדוש ברוך הוא ותרן הוא\u0004 ומוחל על החטאים שעושים כנגדו — \u0003יותרו\u0004 (יופקרו) \u0003חייו, שנאמר: \"הצור תמים פעלו כי כל דרכיו משפט\"\u0004 (דברים לב, ד), לומר: יש חוק ומשפט בידי שמים, ואין ה' מוותר. \u0003אמר ר' חנא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' שמואל בר נחמני: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 בשלוש עשרה מידות הרחמים"],["\u0003\"ארך אפים\"\u0004 (שמות לד, ו) \u0003ולא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ארך אף\"?\u0004 ללמד מצורת הרבים של הלשון \"\u0003אפיים\u0004\" שמאריך אפו הן \u0003לצדיקים ו\u0004הן \u0003לרשעים\u0004 מלהיפרע מהם מיד על מעשיהם הרעים.","ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לא יסקל אדם\u0004 אבנים \u0003מרשותו לרשות הרבים.\u0004 ומסופר \u0003מעשה באדם אחד שהיה מסקל\u0004 אבנים \u0003מרשותו לרשות הרבים, ומצאו חסיד אחד, אמר לו\u0004 החסיד: \u0003ריקה\u0004 (פוחז, אדם שפל), \u0003מפני מה אתה מסקל מרשות שאינה שלך לרשות שלך? לגלג עליו\u0004 אותו האיש, שלא הבין מה אומר לו.","\u0003לימים נצרך למכור\u0004 את \u0003שדהו\u0004 זה שסקלו, \u0003והיה מהלך באותו רשות הרבים\u0004 שהשליך אליה אבנים \u0003ונכשל באותן אבנים, אמר: יפה אמר לי אותו חסיד מפני מה אתה מסקל מרשות שאינה שלך,\u0004 שהרי הרשות שהיתה שלו בסוף היתה של אחרים, \u0003לרשות שלך\u0004 רשות הרבים, שלעולם יש לו חלק בה.","\u0003החופר בור ברשות הרבים ונפל לתוכו שור או חמור\u0004 — \u0003חייב\u0004 החופר את הבור. דין \u0003אחד\u0004 לזה \u0003החופר בור\u0004 או \u0003שיח\u0004 (שהוא צר וארוך) \u0003ו\u0004כן \u0003מערה\u0004 (שהיא מרובעת ובעלת תקרה), או \u0003חריצין ונעיצין\u0004 (תעלות) — \u0003חייב\u0004 בכל אלה. \u0003אם כן למה נאמר\u0004 בתורה דווקא \u0003\"בור\"\u0004 — ללמדנו: \u0003מה בור\u0004 שסתמו \u0003שיש בו כדי להמית\u0004 בנפילה לתוכו, עומקו לפחות \u0003עשרה טפחים, אף כל\u0004 צורת חפירה אחרת אין חייב על נזקים שאירעו בגללה, אלא רק באופן \u0003שיש בו כדי להמית\u0004 — שעומקו \u0003עשרה טפחים\u0004 ולא פחות. \u0003היו\u0004 הבור או החפירות האחרות שמנינו \u0003פחותין מעשרה טפחים, ונפל לתוכו שור או חמור ומת\u0004 — \u0003פטור, ו\u0004אולם \u0003אם הוזק בו\u0004 ולא מת — \u0003חייב\u0004 לשלם את הנזק.","\u0003אמר רב: בור שחייבה עליו\u0004 ה\u0003תורה\u0004 לשלם על נזקיו — הרי זה דווקא לנזק שנגרם על ידי \u0003הבלו\u0004 של הבור מחמת מחנק באווירו של הבור, \u0003ולא לחבטו,\u0004 לנזק שנגרם מחמת החבטה בקרקעיתו של הבור, שעליו אינו משלם. ומסבירים: \u0003אלמא קסבר\u0004 \u0005[מכאן שסבור]\u0006 רב כי בענין \u0003חבטה קרקע עולם הוא דמזקא ליה\u0004 \u0005[שמזיקה אותו]\u0006 ועל כך אין חופר הבור אחראי.","\u0003ושמואל אמר: להבלו\u0004 חייבה תורה על נזקי בור \u0003וכל שכן לחבטו.\u0004 ומוסיף: \u0003ואם תאמר\u0004 כי דווקא \u0003לחבטו אמרה תורה\u0004 שחייב \u0003ולא להבלו\u0004 כלל. על כך יש להשיב: הרי \u0003התורה העידה\u0004 בסתם \u0003על הבור\u0004 שחייב עליו והכוונה לכל בור \u0003ואפילו\u0004 זה שהוא \u0003מלא\u0004 בתחתיתו \u0003ספוגין של צמר\u0004 שאין אפשרות להיחבל מחמת החבטה בקרקע.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל המעשי \u0005ביניהם\u0006 בין רב ושמואל] לגבי חיוב בנזקי הבור? והרי בכל בור יש גם הבל וגם חבטה! ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 במקרה \u0003דעבד\u0004 \u0005[שעשה]\u0006 \u0003גובה\u0004 (מקום מוגבה) \u0003ברשות הרבים\u0004 בלא חפירה, שגובהו עשרה טפחים, ונפלה בהמה ממקום מוגבה זה ומתה. \u0003ל\u0004דעת \u0003רב\u0004 — על \u0003גובה לא מיחייב\u0004 \u0005[מתחייב]\u0006 בחיוב בור שהרי לא היה כאן נזק של הבל, \u0003ל\u0004דעת \u0003שמואל\u0004 — על \u0003גובה נמי מיחייב\u0004 \u0005[גם כן מתחייב]\u0006 משום בור, שהרי אף כאן היתה חבטה.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הוכחתו] של \u0003רב\u0004 שאין לחייב באופן זה? — ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ונפל\"\u0004 — ללמדנו שאין חייב בנזקי בור אלא \u0003עד שיפול דרך נפילה\u0004 ולא באופן אחר כגון זה, שעלה לגובה ומשם נפל. \u0003ול\u0004דעת \u0003שמואל\u0004 מה שנאמר \u0003\"ונפל\"\u0004 — \u0003כל דהו\u0004 \u0005[שהוא]\u0006 \u0003משמע,\u0004 כלומר, כל אופן שנפל, בלי להבדיל אם נפל למקום עמוק, או ממקום גבוה.","ומקשים על רב ממה ששנינו במשנתנו, \u0003תנן\u0004 \u0005[שנינו]\u0006 במשנה: \u0003אם כן למה נאמר\u0004 בתורה דווקא \u0003\"בור\"?\u0004 — \u0003מה בור שיש בו כדי להמית\u0004 — \u0003עשרה טפחים, אף כל שיש בו כדי להמית\u0004 — \u0003עשרה טפחים.\u0004 ומעתה נאמר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003שמואל \"אף כל\"\u0004 שאמרו בא \u0003לאתויי\u0004 \u0005[להביא,\u0006 להוסיף] מקרה זה שנפל מ\u0003גובה\u0004 עשרה טפחים, שאף הוא חייב. \u0003אלא ל\u0004שיטת \u0003רב\u0004 שפוטר במקרה זה, \u0003\"אף כל\"\u0004 שאמרו \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף, את מה]?","ומשיבים: לדעתו \"אף כל\" בא \u0003לאתויי\u0004 \u0005[להביא,\u0006 להוסיף\u0005]\u0006 \u0003חריצין ונעיצין.\u0004 ותוהים: הלא \u0003חריצין ונעיצין בהדיא קתני להו\u0004 \u0005[במפורש שנה אותם\u0006 במשנה] קודם, ואם כן מה טעם לחזור ולרמוז עליהם שוב? ומשיבים: \u0003תני והדר מפרש\u0004 \u0005[שנה וחזר ופירש],\u0006 שקודם שנה את ההלכה ואחר כך חזר ופירש את מקורה בתורה.","וכיון שהוזכרו כל אלה הפרטים, שואלים: \u0003והני כולהו דקתני\u0004 \u0005[ואלה\u0006 הפרטים \u0005כולם ששנה\u0006 במשנה\u0005]\u0006 \u0003למה לי?\u0004 ומסבירים: \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו כולם, \u0003דאי תנא\u0004 \u0005[שאילו\u0006 היה \u0005שונה]\u0006 רק \u0003בור, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 דווקא \u0003בור\u0004 שעומקו \u0003עשרה\u0004 טפחים \u0003הוא דאית ביה הבלא\u0004 \u0005[שיש בו הבל]\u0006 \u0003משום דקטין וכריכא\u0004 \u0005[ש\u0006הוא צר ועגול], \u0003אבל שיח דאריך\u0004 \u0005[ש\u0006הוא ארוך] \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003בעשרה\u0004 טפחים \u0003לית ביה הבלא\u0004 \u0005[אין בו הבל]\u0006 הממית, ולא יהיה חייב עליו, על כן היה צריך לשנות גם חיוב בור בשיח.","\u0003ואי תנא\u0004 \u0005[ואילו היה שונה]\u0006 בנוסף לבור רק \u0003שיח, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 דווקא \u0003שיח\u0004 שיש בו \u0003עשרה\u0004 טפחים \u0003הוא דאית ביה הבלא\u0004 \u0005[שיש בו הבל]\u0006 \u0003משום דקטין\u0004 \u0005[ש\u0006הוא צר], \u0003אבל מערה דמרבעא\u0004 \u0005[ש\u0006היא מרובעת] ואינה צרה, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003בעשרה\u0004 טפחים בלבד עדיין \u0003לית\u0004 \u0005[אין]\u0006 \u0003בה הבלא\u0004 \u0005[הבל],\u0006 על כן שנה גם מערה.","\u0003ואי תני\u0004 \u0005[ואילו\u0006 היה שונה] \u0003מערה הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 דווקא \u0003מערה בעשרה\u0004 טפחים \u0003הוא דאית\u0004 \u0005[שיש]\u0006 \u0003בה הבלא\u0004 \u0005[הבל]\u0006 \u0003משום דמטללא\u0004 \u0005[ש\u0006היא מכוסה], \u0003אבל חריצין\u0004 ש\u0003לא מטללי\u0004 \u0005[מכוסים]\u0006 — \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003בעשרה\u0004 טפחים \u0003לית בהו הבלא\u0004 \u0005[אין בהם הבל],\u0006 על כן שנה גם חריצין.","\u0003ואי תנא\u0004 \u0005[ואילו\u0006 היה שונה] \u0003חריצין הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 דווקא \u0003חריצין\u0004 בני \u0003עשרה\u0004 טפחים \u0003הוא דאית בהו הבלא\u0004 \u0005[שיש בהם הבל],\u0006 \u0003משום דלית בהו רויחא מלעיל טפי מתתאי\u0004 \u0005[שאין בהם רווח מלמעלה יותר מאשר מלמטה],\u0006 \u0003אבל נעיצין דרויחי מלעיל טפי מתתאי\u0004 \u0005[שמרווחים מלמעלה יותר מאשר מלמטה]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 כי \u0003בעשרה\u0004 טפחים בלבד \u0003לית בהו הבלא\u0004 \u0005[אין בהם הבל],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף נעיצין בכלל בור. ואם כן יש חידוש בכל אחד מן הפרטים שנמנו.","ומקשים עוד ממשנתנו, \u0003תנן\u0004 \u0005[שנינו]\u0006 במשנה: \u0003היו\u0004 הבורות למיניהם \u0003פחותין מעשרה טפחים\u0004 בעומק \u0003ונפל לתוכו שור או חמור ומת\u0004 — \u0003פטור, ואם הוזק בו\u0004 — \u0003חייב.\u0004 ונדייק: \u0003נפל לתוכו שור או חמור ומת\u0004 — \u0003פטור, מאי טעמא\u0004 \u0005[מה הטעם],\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דלית ביה\u0004 \u0005[שאין בו]\u0006 בגובה כזה \u0003חבטה\u0004 אף שיש בו הבל?","ודוחים: \u0003לא,\u0004 הריהו פטור \u0003משום דלית ביה הבלא\u0004 \u0005[שאין בו הבל].\u0006 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה אומר, שאין בבור זה הבל, מדוע \u0003אם הוזק בו חייב? הא לית ביה הבלא\u0004 \u0005[הרי אין בו הבל]!\u0006 \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003אין\u0004 בו \u0003הבלא\u0004 \u0005[הבל]\u0006 \u0003למיתה, ו\u0004אולם \u0003יש\u0004 בו \u0003הבלא\u0004 \u0005[הבל]\u0006 מספיק כדי לגרום \u0003לנזקין.\u0004","מסופר: \u0003ההוא תורא דנפל לאריתא דדלאי\u0004 \u0005[שור אחד נפל לאמת מים]\u0006 שעומקה אמה (שהיא ששה טפחים), \u0003שחטיה מריה\u0004 \u0005[שחטו בעליו]\u0006 משום שהשור נחבט, וחשש שימות, וקדם ושחטו על מנת שאפשר יהיה לאכול את בשרו. \u0003טרפיה\u0004 \u0005[הטריפו]\u0006 \u0003רב נחמן\u0004 שכן חוששים במקרה של נפילה לריסוק אברים, שאז הבהמה נחשבת טריפה ואסורה באכילה.","\u0003אמר רב נחמן: אי שקיל מריה דהאי תורא קבא דקמחא ואזל תנא בי מדרשא\u0004 \u0005[אילו היה בעליו של שור זה לוקח קב קמח והולך ושונה בבית המדרש]\u0006 שאף ששור שנפל ונחבט ושחטוהו מיד דינו כדין טריפה, מכל מקום \u0003אם\u0004 לאחר הנפילה \u0003שהתה\u0004 הבהמה \u0003מעת לעת\u0004 (יממה) ונשארה בחיים ונשחטה — \u0003כשירה,\u0004 הרי \u0003לא אפסדיה לתורא\u0004 \u0005[היה מפסיד את השור]\u0006 שהוא \u0003שוה כמה קבי\u0004 \u0005[קבים\u0006 של קמח\u0005],\u0006 שאם היה ממתין מלשוחטו ייתכן שהיה יכול לאכול שור זה. ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן שסבור]\u0006 \u0003רב נחמן\u0004 ש\u0003יש חבטה\u0004 אפילו \u0003בפחות מעשרה,\u0004 שהרי בור זה פחות מעשרה טפחים היה, ובכל זאת חשש רב נחמן מחבטה שיש בה ריסוק אברים.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממשנתנו: \u0003היו פחותין מעשרה טפחים ונפל לתוכו שור או חמור ומת\u0004 — \u0003פטור, מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר, \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דלית ביה\u0004 \u0005[שאין בו]\u0006 \u0003חבטה\u0004 הגורמת למיתה? ומדוע יש להטריף בהמה זו?"],["ודחה רב נחמן: \u0003לא,\u0004 טעם הדבר שפטור בבור פחות מעשרה הוא \u0003משום דלית ביה הבלא\u0004 \u0005[שאין בו הבל]\u0006 כדי להרוג, ולכן פטור מנזק בור כדעת רב. אבל חבטה יש בו, ומשום כך יש לחשוש ששור זה שנפל לאמת המים — טריפה הוא. הקשה לו רבא: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 מה ששנינו \"אם \u0003הוזק בו חייב\"\u0004 — מדוע חייב? \u0003הא לית ביה הבלא\u0004 \u0005[הרי אין בו הבל]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003אין\u0004 בו \u0003הבל\u0004 מספיק \u0003למיתה\u0004 \u0003ו\u0004אולם \u0003יש הבל\u0004 כדי לגרום \u0003לנזקין.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 עוד רבא לרב נחמן ממה ששנינו: \u0003בית הסקילה\u0004 שמשם היו משליכים את הנידון למוות בסקילה שיפול וימות, \u0003היה גבוה שתי קומות\u0004 אדם, \u0003ותני עלה\u0004 \u0005[ושנויה עליה\u0006 ברייתא\u0005]:\u0006 שתי הקומות של גובה בית הסקילה \u0003וקומה שלו,\u0004 כלומר, גובה קומתו של הנסקל, נמצא ש\u0003הרי כאן שלש\u0004 קומות. ולפי זה שאל רבא: \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003יש חבטה\u0004 הגורמת למוות \u0003בפחות מעשרה\u0004 טפחים, \u0003למה לי\u0004 אם כן \u0003כולי האי\u0004 \u0005[כל זה]?\u0006 מפני מה צריך שיהא גבוה כל כך?","ענה לו: \u0003ולטעמיך\u0004 \u0005[ו\u0006אף \u0005לטעמך,\u0006 לשיטתך\u0005]\u0006 \u0003נעביד\u0004 \u0005[נעשה]\u0006 את בית הסקילה רק בגובה של \u0003עשרה\u0004 טפחים ולא יותר, ומדוע עושים אותו שתי קומות? \u0003אלא\u0004 מכאן אין ראיה, שטעם הדבר הוא \u0003כ\u0004דברי \u0003רב נחמן\u0004 בענין זה, ש\u0003אמר רב נחמן אמר רבה בר אבוה: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ואהבת לרעך כמוך\"\u0004 (ויקרא יט, יח), ללמד שגם אם הוא חייב מיתה \u0003ברור לו מיתה יפה\u0004 (הגונה), ולכן מגביהים את בית הסקילה כדי שימות בלא יסורים יתירים.","ומקשים: \u0003אי הכי נגבה טפי\u0004 \u0005[אם כך שיגביהו יותר]\u0006 את בית הסקילה, כדי שתהא מיתתו עוד יותר קלה! ומשיבים: \u0003משום דמינוול\u0004 \u0005[שמתנוול]\u0006 בנפילתו, שאם יפול מגובה גדול כל כך יתרסקו אבריו, ואין זו מיתה יפה כיון שמתבזה בה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רבא עוד: נאמר בתורה שצריך אדם לעשות מעקה לגג ביתו, כדי שלא ייגרם מוות לאדם הנופל ממנו (\"ולא תשים דמים בביתך\". דברים כב, ח), ובהגדרת הלכה זו אמרו שמהדגשת הכתוב \u0003\"כי יפל הנפל ממנו\"\u0004 יש ללמוד: \u0003\"ממנו\"\u0004 מגג הבית — \u0003ולא בתוכו.\u0004","\u0003כיצד?\u0004 אם \u0003היתה רשות הרבים גבוה ממנו,\u0004 מן הבית, \u0003עשרה טפחים\u0004 ולא עשה בעל הבית מעקה בין רשות הרבים לביתו \u0003ונפל מתוכה לתוכו,\u0004 מרשות הרבים אל הבית — \u0003פטור,\u0004 היתה רשות הרבים \u0003עמוקה ממנו עשרה טפחים\u0004 ולא עשה בעל הבית מעקה לגגו \u0003ונפל מתוכו לתוכה\u0004 — \u0003חייב.\u0004","ולענייננו \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003יש חבטה\u0004 הגורמת למוות \u0003בפחות מעשרה\u0004 טפחים, \u0003למה לי\u0004 אם כן \u0003עשרה\u0004? הרי תיתכן מיתה אפילו בפחות מזה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003שאני\u0004 \u0005[שונה]\u0006 דין מעקה, שדווקא ב\u0003בית\u0004 חייבה בו התורה, ו\u0003כל\u0004 בית שהוא \u0003פחות מעשרה לאו\u0004 \u0005[לא]\u0006 \u0003בית הוא.\u0004","הקשה לו רבא: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שדין מעקה תלוי בבית, והגדרתו של בית הוא שיהיו בו עשרה טפחים, \u0003השתא נמי\u0004 \u0005[עכשיו גם כן]\u0006 מה ששנינו כשהבית גבוה מרשות הרבים עשרה טפחים — חייב, והרי בית זה \u0003דהוי מאבראי\u0004 \u0005[שהוא מבחוץ]\u0006 \u0003עשרה\u0004 טפחים, \u0003דל מיניה\u0004 \u0005[הורד ממנו]\u0006 מחשבון גובהו \u0003תקרה ומעזיבה\u0004 (שכבה נוספת שעל גב התקרה) ואם כן \u0003מגואי לא הוי\u0004 \u0005[מבפנים אינו]\u0006 גבוה \u0003עשרה,\u0004 ולפי מה שאמרת בפחות מעשרה אינו קרוי בית! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: צריך לומר \u0003כגון דחק מגואי\u0004 \u0005[שחקק,\u0006 העמיק, \u0005מבפנים]\u0006 בקרקע הבית שיהיו בו עשרה טפחים.","והקשה רבא על כך: \u0003אי הכי, כי לא הוי נמי מאבראי\u0004 \u0005[אם כך, גם כאשר אין\u0006 הבית \u0005מבחוץ]\u0006 \u0003עשרה, משכחת לה דהוי מגואי\u0004 \u0005[מוצא אתה אותה\u0006 אפשרות \u0005שיהא מבפנים]\u0006 \u0003עשרה כגון דחק בה טפי\u0004 \u0005[שחקק\u0006 בקרקעיתו \u0005יותר]\u0006 שיכול הוא להיות בית גבוה עשרה מבפנים, למרות שמבחוץ הוא נמוך יותר, ולמה פטור בבית שכזה!","\u0003אלא\u0004 יש לדחות כל מה שאמרנו, ולהסביר כי מה שפסק רב נחמן בשור שנפל לתעלה שיש לחשוש בו לריסוק איברים \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003רב נחמן,\u0004 שהוא \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003מכריסא דתורא לארעא\u0004 \u0005[מכריסו של השור עד הקרקע]\u0006 \u0003כמה הוי\u0004 \u0005[הוא]\u0006 הגובה — \u0003ארבעה\u0004 טפחים, \u0003אריתא דדלאי\u0004 \u0005[תעלת ההשקאה]\u0006 \u0003כמה הוי\u0004 \u0005[הוא]\u0006 עומקה — \u0003שיתא\u0004 \u0005[ששה\u0006 טפחים\u0005],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 ביחד \u0003עשרה\u0004 טפחים, \u0003אישתכח דכי קא מחבט\u0004 \u0005[נמצא שכאשר השור נחבט]\u0006 — \u0003מעשרה\u0004 טפחים \u0003הוא דקא מחבט\u0004 \u0005[שנחבט]\u0006 שהרי שור זה לא נפל על רגליו, אלא נחבט על כריסו.","ושואלים: אם כן, \u0003אלא מתניתין דקתני\u0004 \u0005[משנתנו ששנה\u0006 בה\u0005]:\u0006 \u0003מה בור שהוא כדי להמית\u0004 — \u0003עשרה טפחים, אף כל שיש בו כדי להמית\u0004 — \u0003עשרה טפחים,\u0004 הרי \u0003בשיתא נמי סגיא\u0004 \u0005[בששה\u0006 טפחים \u0005גם כן מספיק]\u0006 כפי שביארנו!","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003מתניתין דאיגנדר\u0004 \u0005[משנתנו\u0006 מדברת באופן \u0005שהתגלגל]\u0006 \u0003לבור\u0004 ובמקרה כזה צריך שיהיה העומק עשרה. מה שאין כן כאשר נופל בדרך הליכה, שיש עוד גובה נוסף מבטנו לקרקע.","\u0003בור של שני שותפין\u0004 שהיה פתוח, \u0003עבר עליו\u0004 תחילה השותף \u0003הראשון ולא כסהו, ו\u0004אחריו עבר \u0003השני ולא כסהו\u0004 — \u0003השני חייב\u0004 בנזקים הבאים מחמת הבור.","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003בור של שני שותפין היכי משכחת לה\u0004 \u0005[כיצד מוצא אתה אותה]\u0006 אפשרות של דבר כזה? \u0003הניחא אי סבירא לן\u0004 \u0005[זה נוח אם סבורים אנו]\u0006 \u0003כ\u0004שיטת \u0003ר' עקיבא\u0004 ש\u0003אמר: בור\u0004 גם \u0003ברשותו\u0004 הפרטית של אדם — \u0003חייב\u0004 עליו, \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 אפשרות של בור של שותפים, \u0003ב\u0004מקרה שהיתה זו \u0003חצר של שניהם ובור של שניהם, והפקירו\u0004 את \u0003רשותן ולא הפקירו\u0004 את \u0003בורן,\u0004 שבמקרה זה הרי הוא בור של שניהם שגורם לנזקים.","\u0003אלא אי סבירא לן\u0004 \u0005[אם סבורים אנו]\u0006 כי \u0003בור ברשותו פטור, היכי משכחת לה\u0004 \u0005[כיצד מוצא אתה אותה\u0006\u0005]\u0006 אפשרות לבור ש\u0003חייב עליה\u0004 \u0005[עליו]\u0006 — רק \u0003ברשות הרבים, וברשות הרבים בור של שני שותפין היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותה]?\u0006","\u0003אי דשוו\u0004 \u0005[אם שמינו]\u0006 \u0003שליח תרוייהו\u0004 \u0005[שניהם\u0006 יחד\u0005]\u0006 \u0003ואמרי ליה\u0004 \u0005[ואמרו לו]:\u0006 \u0003זיל כרי לן, ואזל כרה להו\u0004 \u0005[לך\u0006 וחפור לנו, והלך וחפר להם] ונעשתה השליחות בשביל שניהם בשותפות, ואולם בכל זאת לא יתחייבו שניהם על כך, שכן כלל הוא: \u0003אין שליח לדבר עבירה,\u0004 וכיוון שכך, האחריות מוטלת על החופר עצמו. \u0003ואי\u0004 \u0005[ואם]\u0006 ש\u0003כרה האי\u0004 \u0005[זה]\u0006 אחד השותפים \u0003חמשה\u0004 טפחים \u0003והאי\u0004 \u0005[וזה]\u0006 השותף השני \u0003חמשה\u0004 טפחים — הרי במעשה השני \u0003נסתלקו להו\u0004 \u0005[להם]\u0006 \u0003מעשה ראשון,\u0004 שחפר רק חמשה, וכל האחריות מוטלת רק על השני שחפר והשלים לעשרה, שהוא שעשה את הבור שחייבים עליו, ואין זה נקרא בור השותפים!","ומעירים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003רבי ולנזקין,\u0004 שבמקרה כזה רבי מחייב את שניהם בתשלום נזקים, \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה\u0006\u0005]\u0006 אפשרות שיהא בור של שניים. \u0003אלא ל\u0004שיטת \u0003רבי ול\u0004ענין \u0003מיתה\u0004 כשמת בעל חיים בבור, \u0003ול\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003בין למיתה בין לנזקין,\u0004 שבמקרים אלה אין מחייבים את הראשון כלל, \u0003היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותה]\u0006 שיהא זה נקרא בור של שותפים?","\u0003אמר ר' יוחנן:\u0004 כאן מדובר \u0003כגון שעקרו שניהן חוליא\u0004 (חתיכת אדמה) מקרקע הבור \u0003בבת אחת והשלימו\u0004 אותו בכך \u0003לעשרה\u0004 טפחים, ונמצא הבור של שניהם.","כיון שהזכרנו את מחלוקת רבי ורבנן, שואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 הדבר שאמר \u0003רבי ומאי\u0004 \u0005[ומהו]\u0006 הדבר שאמרו \u0003רבנן\u0004 \u0005[חכמים]\u0006 החלוקים עליו? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחד החופר בור תשעה\u0004 טפחים \u0003ובא אחר והשלימה לעשרה\u0004 טפחים — \u0003האחרון\u0004 בלבד \u0003חייב\u0004 בכל האחריות, בין למיתה בין לנזקים. \u0003רבי אומר: אחר אחרון\u0004 הולכים לענין \u0003מיתה,\u0004 שכיוון שבבור פחות מעשרה אין חייבים על בהמה שמתה, נמצא שאחריות לגבי מיתה חלה רק עליו, \u0003ו\u0004אולם \u0003אחר שניהם לנזקין\u0004 שאם ניזקו בהמות בבור — מחייבים את שניהם.","ומבררים: \u0003מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים]\u0006 ומניין להם כן? — ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"ו\u0003כי יפתח\u0004 איש בור\" (שמות כא, לג) \u0003ו\u0004שוב נאמר \u0003\"כי יכרה\u0004 איש בור\u0003\"\u0004 (שמות כא, לג), והרי השאלה ברורה: \u0003אם על פתיחה\u0004 של בור מכוסה \u0003חייב, על כרייה\u0004 ויצירה של הבור \u0003לא כל שכן,\u0004 ומה בא הכתוב להשמיענו? \u0003אלא\u0004 כתוב זה בא \u0003להביא\u0004 (לרבות) \u0003כורה אחר כורה, ללמדנו\u0004 שאם התחיל אחד לכרות בור, ובא השני והמשיך, \u0003שסילק\u0004 השני \u0003מעשה\u0004 \u0003ראשון\u0004 וחלה כל האחריות עליו. והוא שנאמר \"כי יכרה איש בור\", לומר שהרי זה כבור חדש שנחפר.","\u0003ורבי אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך: הנהו\u0004 \u0005[כתובים אלה]\u0006 \"וכי יפתח\" ו\"כי יכרה\" \u0003מיצרך צריכי כדאמרינן\u0004 \u0005[נצרכים הם כפי שאמרנו]\u0006 לעיל (בבא קמא נ,א), הן לדעת ר' ישמעאל והן לדעת ר' עקיבא. ושואלים: \u0003ורבנן נמי מיצרך צריכי\u0004 \u0005[ו\u0006לשיטת \u0005חכמים גם כן,\u0006 הלא \u0005נצרכים\u0006 הם\u0005]\u0006 לענין אחר, ואם כן מניין להם שהאחריות רק על השני!","\u0003אלא\u0004 יש לדחות את מה שהסברנו, ולומר בדרך אחרת: \u0003היינו טעמא\u0004 \u0003דרבנן\u0004 \u0005[זהו הטעם של חכמים],\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"כי יכרה איש בור\"\u0004 משמע: איש \u0003אחד\u0004 מתחייב בדבר זה \u0003ולא שנים,\u0004 שאם שניים עשו בור לא יהא חייב הראשון אלא האחרון.","ושואלים: \u0003ורבי\u0004 כיצד מבין הוא את ההדגשה \"כי יכרה איש בור\"? ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[\u0006הדגשה \u0005זו נחוצה לו]\u0006 ללמד הלכה אחרת: \u0003\"כי יכרה איש בור\"\u0004 — איש דווקא, \u0003ולא שור\u0004 שכרה ויצר \u0003בור,\u0004 שאין בעליו חייב על נזק זה.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מהיכן למדים הם הלכה זו? ומשיבים: \u0003תרי\u0004 \u0005[שתי]\u0006 פעמים \u0003\"איש בור\" כתיבי\u0004 \u0005[כתובים]:\u0006 \"וכי יפתח איש בור\" \"או כי יכרה איש בור\", ומאחד למדים שמתחייב בבור רק אם עשאו אדם ולא בהמה, ומהשני למדים שמתחייב בבור אחד ולא שניים.","ושואלים: \u0003ורבי\u0004 מה לומד הוא מכפילות זו? ומשיבים: הוא סבור כי \u0003איידי\u0004 \u0005[כיון]\u0006 ש\u0003כתב האי\u0004 \u0005[\u0006את זה] \u0003כתב\u0004 גם \u0003האי\u0004 \u0005[\u0006את זה] והוא ליופי הלשון, ולא ללמוד ממנו.","ושואלים עוד על שיטת חכמים: גם אם למדו מן הכתוב שעל נזקי הבור חייב רק אדם אחד, \u0003וממאי דלחיובי בתרא\u0004 \u0005[וממה\u0006 מנין שבא הפסוק \u0005לחייב\u0006 את האחרון]? \u0003דלמא לחיובי קמא\u0004 \u0005[שמא לחייב\u0006 את הראשון] שהחל בחפירה!","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יכול לעלות על דעתך]\u0006 לומר כן, שהרי \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"והמת יהיה לו\"\u0004 (שמות כג, לד), לומר: \u0003ההוא דקא עביד\u0004 \u0005[זה שעושה,\u0006 גורם\u0005]\u0006 \u0003מיתה\u0004 הוא שמחוייב, וברור שמי שגרם את המיתה הוא השני שהעמיק כל כך, ולא הראשון.","ושואלים: \u0003והאי\u0004 \u0005[וזה]\u0006 \u0003\"והמת יהיה לו\"\u0004 הלא \u0003מבעי ליה לכדרבא\u0004 \u0005[נצרך הוא לכמו שאמר\u0006 \u0005רבא]:\u0006 ש\u0003אמר רבא: שור פסולי המוקדשין,\u0004 שהוא שור שהוקדש לקרבן ונפל בו מום, שלמרות שאינו ראוי עוד להקרבה, מכל מקום אינו נעשה לגמרי כחולין, ואפילו לאחר שפודים אותו אסור להשתמש בו לדברים מסויימים, \u0003שנפל לבור\u0004 — \u0003פטור\u0004 בעל הבור, משום \u0003שנאמר: \"והמת יהיה לו\",\u0004 לומר: דין זה הוא \u0003במי שהמת שלו\u0004 ובמקרה זה אין השור יכול להיות שייך לגמרי לאיש, כיון שיש הגבלות על שימוש בו. ואם כן למדים מביטוי זה לימוד אחר!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 על כך בתשובה: \u0003ולאו ממילא שמעת מינה\u0004 \u0005[ו\u0006כי \u0005לא מן הדבר עצמו שומע אתה ממנו]\u0006 \u0003דבההוא דעבד\u0004 \u0005[שבאותו\u0006 אדם \u0005שעשה]\u0006 \u0003מיתה עסקינן\u0004 \u0005[אנו עוסקים]?\u0006 שגם אם למדים מן הכתוב כפי שאמר רבא, לשון הכתוב והדגשתו יכולים ללמד הלכה נוספת.","ובענין דומה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אחד החופר בור עשרה\u0004 טפחים \u0003ובא אחר והשלימה לעשרים, ובא אחר והשלימה לשלשים\u0004 — \u0003כולן חייבין\u0004 על הנזקים שגרם בור זה. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003אחד החופר בור עשרה\u0004 טפחים, \u0003ובא אחר וסייד\u0004 את הבור מבפנים \u0003וכייד\u0004 (טייח אותו בטיט) — \u0003האחרון חייב\u0004 על נזקיו, ולא מי שקדם לו."],["\u0003לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 כי \u0003הא\u0004 \u0005[זו]\u0006 הברייתא הראשונה היא כשיטת \u0003רבי\u0004 שמחייב כל אחד מן החופרים, \u0003והא\u0004 \u0005[וזו]\u0006 האחרונה היא כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 שמחייבים רק את האחרון?","\u0003אמר רב זביד: הא והא\u0004 \u0005[זו וזו]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 אלא \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן\u0004 \u0005[אמרו חכמים]\u0006 שה\u0003אחרון\u0004 הוא ש\u0003חייב\u0004 — \u0003אלא היכא\u0004 \u0005[היכן]\u0006 ש\u0003לא עבד קמא\u0004 \u0005[עשה הראשון]\u0006 \u0003שיעור\u0004 בור הגורם ל\u0003מיתה,\u0004 שעשה בור פחות מעשרה טפחים, \u0003אבל היכא דעבד קמא\u0004 \u0005[היכן שעשה הראשון]\u0006 בור שיש בו \u0003שיעור מיתה\u0004 (שהרי הראשון חפר עשרה והבאים אחריו רק העמיקו יותר את הבור), \u0003אפילו רבנן מודו\u0004 \u0005[חכמים מודים]\u0006 ש\u0003כולן חייבין.\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 בברייתא השניה של \u0003סייד וכייד\u0004 \u0003דקא עבד קמא\u0004 \u0005[שעשה הראשון]\u0006 \u0003שיעור מיתה, ו\u0004בכל זאת \u0003קתני\u0004 \u0005[שנה]:\u0006 \u0003אחרון חייב!\u0004 \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003שלא היה בו\u0004 בבור \u0003הבל למיתה\u0004 לפי שהיה רחב מאד, \u0003ובא אחר והוסיף בה הבל למיתה,\u0004 שהצר אותו בסיוד וכיוד.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת, שכך \u0003אמר רב זביד: הא והא\u0004 \u0005[זו וזו],\u0006 שתי הברייתות הן כשיטת \u0003רבי, הך דקתני\u0004 \u0005[זו ששנה]\u0006 בה: \u0003כולן חייבין\u0004 — \u0003שפיר\u0004 \u0005[יפה],\u0006 שהוא ודאי כשיטתו, \u0003הא דקתני\u0004 \u0005[\u0006ו\u0005זו ששנה]\u0006 בה: \u0003אחרון\u0004 בלבד \u0003חייב\u0004 — מדובר בה במקרה \u0003כגון שלא היה בו\u0004 בבור \u0003הבל\u0004 כשיעור המסוכן \u0003לא למיתה ולא לנזקין, ובא אחר והוסיף בו הבל בין למיתה בין לנזקין.\u0004","ועוד בענין זה \u0003אמר רבא:\u0004 מי ש\u0003הניח אבן על פי הבור\u0004 שאין בו עומק עשרה טפחים \u0003ו\u0004בכך \u0003השלימה,\u0004 את הבור, \u0003ל\u0004עומק \u0003עשרה, באנו למחלוקת רבי ורבנן\u0004 מי האחראי עבור נזקי בור זה: האם שניהם, או רק האחרון.","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שבכך הם חולקים, ומה השמיענו רבא במקרה מסויים זה! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 ותחלק כך: \u0003למטה,\u0004 כאשר בא אדם נוסף והעמיק את הבור בתחתיתו \u0003הוא דהבלא דידיה קא קטיל ליה\u0004 \u0005[שההבל שלו\u0006 שהוסיף לבור הוא \u0005ההורג אותו],\u0006 \u0003אבל\u0004 אם מוסיף \u0003למעלה,\u0004 ש\u0003לא הבלא דידיה קא קטיל\u0004 \u0005[ההבל שלו\u0006 הוא ש\u0005הורג]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהיה חייב, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהאחרון חייב, ואף בזה נחלקו רבי וחכמים אם האחרון בלבד חייב או שניהם.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 שאלה זו: מי שמצא בור בעומק תשעה וחפר בו טפח והשלימו לעשרה טפחים, ולאחר מכן \u0003טם\u0004 \u0005[סתם]\u0006 אותו \u0003טפח\u0004 בתוך הבור, \u0003ו\u0004כן אם \u0003סילק אבניו\u0004 של הבור, \u0003מהו? מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003מאי דעבד שקליה\u0004 \u0005[מה שעשה לקחו]\u0006 והחזיר את המצב לכמות שהיה לפני שחפר את הטפח האחרון, והאחריות לנזקים מוטלת על חופר הבור הראשון.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר כי על ידי הסתימה \u0003נסתלקו מעשה\u0004 ה\u0003ראשון,\u0004 שהרי כאשר סתמו שוב אין זה בור שחייבים עליו מיתה, \u0003וקמה ליה כוליה ברשותיה\u0004 \u0005[ועומד\u0006 עתה הבור \u0005כולו ברשותו]\u0006 של השני, ועליו כל האחריות לבור זה של תשעה טפחים? לשאלה זו לא נמצאה תשובה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003אמר רבה בר בר חנה אמר שמואל בר מרתא: בור\u0004 שעומקו \u0003שמונה\u0004 טפחים \u0003ומהן שני טפחים מים\u0004 — \u0003חייב\u0004 עליו. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003כל טפח דמיא\u0004 \u0005[של מים]\u0006 \u0003כתרי\u0004 \u0005[כשני]\u0006 טפחים של עומק \u0003יבשה דמי\u0004 \u0005[נחשבים]\u0006 ולכן נחשב זה כבור עשרה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים \u0005]\u0006 שאלה זו: \u0003בור תשעה\u0004 טפחים \u0003ומהן טפח אחד מים, מהו\u0004 הדין? האם תהא ההלכה במקרה זה דומה? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי \u0003כיון\u0004 ש\u0003לא נפישי מיא\u0004 \u0005[מרובים\u0006 בו \u0005המים]\u0006 כמו בדינו של רבה בר בר חנה — \u0003לית ביה הבלא\u0004 \u0005[אין בו הבל]\u0006 בבור, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דעמיק טפי\u0004 \u0005[ש\u0006הוא \u0005עמוק ביותר]\u0006 — \u0003אית ביה הבלא\u0004 \u0005[יש בו הבל]\u0006 אף על פי שכמות המים קטנה יותר?","וכן יש לשאול: \u0003בור שבעה\u0004 טפחים \u0003ומהן שלשה טפחים מים, מהו?\u0004 וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003כיון דנפישי\u0004 \u0005[שמרובים]\u0006 ה\u0003מים טפי\u0004 \u0005[ביותר]\u0006 — \u0003אית ביה הבלא\u0004 \u0005[יש בו הבל]\u0006 כדי עשרה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003לא עמקא\u0004 \u0005[עמוק]\u0006 — \u0003לית ביה הבלא\u0004 \u0005[אין בו הבל]?\u0006 לשאלות הללו לא נמצא פתרון, ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב שיזבי מרבה:\u0004 המוצא בור עמוק עשרה טפחים, אם \u0003הרחיבה\u0004 את פי הבור \u0003מהו\u0004 הדין? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003הרי\u0004 בכך הוא \u0003מיעט הבלא\u0004 \u0005[הבל],\u0006 ולא עשה דבר של נזק ולמה יהיה חייב. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב שיזבי: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003הרי\u0004 על ידי הרחבת פתח הבור \u0003קירב הזיקא\u0004 \u0005[\u0006את \u0005הנזק]\u0006 יותר לזה שנפל בו!","\u0003אלא אמר רב אשי\u0004 בפתרון בעיה זו: \u0003ניחזי אנן\u0004 \u0005[נראה אנו],\u0006 \u0003אי בהבלא מיית\u0004 \u0005[אם בהבל מת]\u0006 — \u0003הרי מיעט הבלא\u0004 \u0005[\u0006את \u0005ההבל]\u0006 ונמצא שאינו חייב זה שהרחיב, \u0003אי\u0004 \u0005[אם]\u0006 \u0003בחבטה מיית\u0004 \u0005[מת]\u0006 — \u0003הרי קירב הזיקא\u0004 \u0005[\u0006את \u0005הנזק]\u0006 וחייב. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך \u0003אמר רב אשי:\u0004 \u0003ניחזי אנן\u0004 \u0005[נראה אנו]\u0006 באופן זה: \u0003אי מההיא גיסא\u0004 \u0005[אם מהצד ההוא]\u0006 שהרחיב \u0003נפל\u0004 — \u0003הרי\u0004 במעשהו הוא \u0003קירב הזיקא\u0004 \u0005[\u0006את \u0005הנזק]\u0006 ויהיה חייב, \u0003ואי מאידך גיסא\u0004 \u0005[ואם מהצד האחר]\u0006 שלא הרחיבו \u0003נפל\u0004 — \u0003הרי\u0004 במעשהו הוא \u0003מיעט הבלא\u0004 \u0005[\u0006את \u0005ההבל]\u0006 ואם כן אין עליו אחריות כלל.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003בור שעומקה כרחבה\u0004 — \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבה בר בר חנה\u0004 ש\u0003אמר משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' מני, חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: לעולם יש בה\u0004 בכל בור \u0003הבל\u0004 — \u0003עד שיהא רחבה יתר על עומקה\u0004 שאז אין בו הבל. אבל בבור שאין רוחבו יתר על עומקו ואף אם שווים הם — יש בו הבל. \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: לעולם אין בה הבל עד שיהא עומקה יתר על רחבה.\u0004 אבל בבור שעומקו שווה לרוחבו — אין בו הבל.","עוד שנינו במשנה שאם \u0003עבר עליו הראשון ולא כסהו\u0004 ועבר השני ולא כיסהו — השני חייב. ושואלים: \u0003וראשון מאימת מיפטר\u0004 \u0005[ממתי\u0006 הוא \u0005נפטר]\u0006 מן האחריות על הבור? ואף בהלכה זו, \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבה בר בר חנה\u0004 ש\u0003אמר משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' מני, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: משמניחו משתמש,\u0004 שעזב את הבור כשחבירו משתמש בו, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 לא די בכך כדי לפטור את הראשון, אלא רק \u0003משימסור לו דליו\u0004 שבו ידלה מים מאותו בור.","ומעירים: מחלוקת זו היא \u0003כתנאי\u0004 \u0005[כתנאים]\u0006 שנחלקו בשאלה זו, שכך שנינו: \u0003המדלה מים מן הבור, ובא חבירו\u0004 שותפו לבור \u0003ואמר לו: הנח לי ואני אדלה מים, כיון שהניחו משתמש\u0004 — הרי הראשון \u0003פטור\u0004 אם לא כיסהו. \u0003ר' אליעזר בן יעקב אומר:\u0004 אינו פטור אלא \u0003משימסור לו דליו.\u0004","ומבררים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005נחלקו]?\u0006 \u0003ר' אליעזר בן יעקב סבר\u0004 \u0005[סבור]:\u0006 \u0003יש ברירה,\u0004 שאנו אומרים שלאחר מעשה מתברר מצב שלא היה מוגדר מתחילה, כאילו היה מוגדר כבר מראשיתו.","ואף בענייננו, לכל אחד מן השותפים חלק מוגדר במים שבבור (אף שאיננו יכולים עתה להצביע עליו) באופן ש\u0003האי מדידיה קא\u0004 \u0005[זה משלו הוא]\u0006 \u0003ממלא והאי מדידיה קא\u0004 \u0005[וזה משלו הוא]\u0006 \u0003ממלא,\u0004 ולכן כל עוד לא מסר הראשון את דליו לשני, אינו מסיר מעליו את האחריות שיש לו כבעל חלק מוגדר מן המים שיש בבור, ואף הוא שותף בדבר. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003אין ברירה,\u0004 ומשעה שהשני משתמש בבור לבדו מוטלת עליו האחריות לבור ולכל המים שיש בו, ללא צורך למעשה מיוחד של העברת אחריות בדרך של מסירת הדלי.","\u0003אמר רבינא: ואזדו לטעמייהו\u0004 \u0005[והולכים הם\u0006 בעקרון זה \u0005לשיטתם]\u0006 שכן יש ביניהם מחלוקת מקבילה לכך, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003השותפין שנדרו הנאה זה מזה,\u0004 שנדרו שלא יהנו זה משל חבירו — \u0003אסורין ליכנס לחצר\u0004 המשותפת להם, שהרי היא שייכת לשניהם ועוברים הם על נדרם בכניסתם לחצר. \u0003ר' אליעזר בן יעקב אומר:\u0004 מותרים ליכנס לחצר, משום ש\u0003זה נכנס לתוך\u0004 החלק \u0003שלו וזה נכנס לתוך שלו.\u0004","ואף שם הסבירו: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005נחלקו]?\u0006 \u0003ר' אליעזר בן יעקב סבר: יש ברירה,\u0004 שאומרים שבכניסתו של כל אחד מהם לחצר מתברר למפרע איזה חלק בחצר שייך לו, ולכן אומרים כי \u0003האי לדנפשיה עייל והאי לדנפשיה עייל\u0004 \u0005[זה לשלו נכנס וזה לשלו נכנס].\u0006 \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003אין ברירה,\u0004 וכל חלק מן החצר שייך לשניהם יחד.","אגב הזכרת דין זה של מסירת דלי בבור, מביאים מה ש\u0003אמר ר' אלעזר: המוכר בור לחבירו, כיון שמסר לו דליו\u0004 של הבור הרי זה \u0003קנה\u0004 במסירה זו את הבור. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 לשם מה יש צורך במסירת הדלי כדי לקנות את הבור? \u0003אי בכספא\u0004 \u0005[אם בכסף]\u0006 קנה, ששילם לו כסף עבור הבור — \u0003ליקני בכספא\u0004 \u0005[שיקנה אותו בכסף]\u0006 ששילם! \u0003אי\u0004 \u0005[אם]\u0006 \u0003בחזקה\u0004 קנה את הבור — \u0003ליקני\u0004 \u0005[שיקנה\u0006 אותו\u0005]\u0006 \u0003בחזקה\u0004 של שימוש בו!","ומשיבים: \u0003לעולם\u0004 יש לפרש שמסר לו את הבור שיקנה אותו \u0003בחזקה, ו\u0004במקרה כזה \u0003בעי למימר ליה\u0004 \u0005[וצריך\u0006 המוכר \u0005לומר לו]:\u0006 \u0003לך חזק וקני\u0004 \u0005[החזק וקנה]\u0006 את הבור שיהא שלך. \u0003ו\u0004אולם \u0003כיון שמסר לו דליו,\u0004 הרי זה \u0003כמאן\u0004 \u0005[כמי]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 בכך: \u0003לך חזק וקני\u0004 \u0005[החזק וקנה]\u0006 \u0003דמי\u0004 \u0005[נחשב]\u0006 הדבר, ומשהשתמש בו — קנאו בחזקה.","ואגב דין זה של קנין בחזקה על ידי דבר אחר, \u0003אמר ר' יהושע בן לוי: המוכר בית לחבירו,\u0004"],["\u0003כיון שמסר לו,\u0004 לקונה, את \u0003מפתח\u0004 הבית — \u0003קנה\u0004 הקונה את הבית.","ושואלים אף כאן: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר],\u0006 כיצד היה אופן המכירה? \u0003אי בכספא\u0004 \u0005[אם\u0006 קנה \u0005ב\u0006קנין \u0005כסף]\u0006 — \u0003ליקני בכספא\u0004 \u0005[שיקנה ב\u0006נתינת ה\u0005כסף]!\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בחזקה\u0004 קנה — \u0003ליקני\u0004 \u0005[שיקנה]\u0006 \u0003בחזקה\u0004 ומה עניינה של מסירת המפתח? ומפרשים: \u0003לעולם\u0004 יש לומר שקנה \u0003בחזקה, ובעי למימר ליה\u0004 \u0005[וצריך היה\u0006 המוכר \u0005לומר לו\u0006 לקונה\u0005]\u0006 \u0003\"לך חזק וקני\"\u0004 \u0005[החזק וקנה],\u0006 \u0003וכיון שמסר לו מפתח, כמאן\u0004 \u0005[כמי]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"לך חזק וקני\" דמי\u0004 \u0005[נחשב].\u0006","ועוד בענין זה, \u0003אמר ריש לקיש משום\u0004 \u0005[בשם]\u0006 \u0003ר' ינאי: המוכר עדר\u0004 צאן \u0003לחבירו, כיון שמסר לו\u0004 המוכר לקונה את ה\u0003משכוכית\u0004 — \u0003קנה.\u0004","ושאלו אף שם: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]\u0006 דרך הקנין? \u0003אי\u0004 \u0005[אם]\u0006 \u0003במשיכה\u0004 קנה — \u0003ליקני\u0004 \u0005[שיקנה]\u0006 \u0003במשיכה, אי\u0004 \u0005[אם]\u0006 \u0003ב\u0004דרך \u0003מסירה\u0004 קנה — \u0003ליקני\u0004 \u0005[שיקנה]\u0006 \u0003במסירה!\u0004 ומשיבים: \u0003לעולם\u0004 מדובר שהקנה לו \u0003במשיכה, ובעי למימר ליה\u0004 \u0005[וצריך היה\u0006 המוכר \u0005לומר לו\u0006 לקונה\u0005]:\u0006 \u0003\"לך משוך וקני\"\u0004 \u0005[וקנה],\u0006 \u0003וכיון\u0004 ש\u0003מסר לו משכוכית, כמאן\u0004 \u0005[כמי]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"לך משוך וקני\" דמי\u0004 \u0005[נחשב].\u0006","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003משכוכית\u0004 זו? ומשיבים: \u0003הכא\u0004 \u0005[כאן,\u0006 בבבל\u0005]\u0006 \u0003תרגמו: קרקשתא\u0004 \u0005[פעמון]\u0006 שהרועה מקשקש בו והעדר הולך אחריו. \u0003ר' יעקב אומר: עיזא דאזלא בריש עדרא\u0004 \u0005[העז שהולכת בראש העדר]\u0006 והעדר רגיל ללכת אחריה. ומעירים, שפירושו זה של ר' יעקב הוא \u0003כדדרש ההוא גלילאה עליה\u0004 \u0005[כפי שדרש גלילי אחד לפני]\u0006 \u0003רב חסדא: כד רגיז רעיא על ענא, עביד לנגדא סמותא\u0004 \u0005[כאשר כועס הרועה על הצאן,\u0006 הוא \u0005עושה את\u0006 העז \u0005המנהיגה,\u0006 המשכוכית \u0005עיוורת]\u0006 וכך כאשר כועס הקדוש ברוך הוא על ישראל הרי הוא ממנה להם מנהיגים שאינם ראויים.","ומונה המשנה כמה מהלכות בור: בור ש\u0003כסהו הראשון\u0004 לאחר שהשתמש בו, \u0003ובא השני\u0004 להשתמש בו \u0003ומצאו\u0004 שהוא \u0003מגולה\u0004 שנפל או התקלקל הכיסוי, \u0003ולא כסהו\u0004 השני — הרי \u0003השני חייב\u0004 בנזקי אותו הבור. בעל הבור ש\u0003כסהו כראוי, ונפל לתוכו שור או חמור ומת\u0004 — \u0003פטור. לא כסהו כראוי, ונפל לתוכו שור או חמור ומת\u0004 — \u0003חייב.\u0004","היה אדם כורה או מרחיב בור, ועבר שם שור ונבהל ונפל, אם \u0003נפל\u0004 \u0003לפניו מ\u0004פני \u0003קול הכרייה\u0004 — הרי הוא \u0003חייב,\u0004 אם נרתע \u0003לאחריו\u0004 ונפל לתוך הבור \u0003מ\u0004פני \u0003קול הכרייה\u0004 — \u0003פטור.\u0004","ועוד הלכה: \u0003נפל לתוכו שור וכליו\u0004 (הכלים שהוא נושא עליו), כגון עול וכיוצא בהן \u0003ונשתברו\u0004 הכלים, או נפלו ה\u0003חמור וכליו\u0004 שעליו \u0003ונתקרעו\u0004 הכלים — הרי זה \u0003חייב על הבהמה ופטור על הכלים,\u0004 שכן הוא דין הבור מן התורה.","\u0003נפל לתוכו שור\u0004 שהוא \u0003חרש\u0004 או \u0003שוטה ו\u0004כן שור \u0003קטן\u0004 — \u0003חייב.\u0004 נפלו לתוך הבור \u0003בן או בת\u0004 (ילדים קטנים) או \u0003עבד או אמה\u0004 — \u0003פטור\u0004 שגזירת הכתוב היא שאין חייב אלא על נזקי בהמה.","שנינו במשנה שבור שכיסהו הראשון ובא שני ומצאו שהוא מגולה ולא כיסהו — חייב השני. ושואלים: \u0003וראשון עד אימת מיפטר\u0004 \u0005[מתי\u0006 הוא \u0005פטור]\u0006 כאשר נתגלה בור שכיסהו? \u0003אמר רב: ב\u0004שיעור זמן כזה \u0003כדי\u0004 \u0003שידע,\u0004 שיכול לדעת ולראות שהוא מגולה, ואז מוטלת עליו אחריות לכסותו, ואם לא עשה כן — יתחייב. \u0003ושמואל אמר: בכדי\u0004 הזמן \u0003ש\u0004יראו אנשים את הבור מגולה וילכו ו\u0003יודיעוהו. ור' יוחנן אמר: בכדי שיודיעוהו\u0004 שנפל הכיסוי, \u0003וישכור פועלים, ויכרות ארזים\u0004 לעשות כיסוי יפה \u0003ויכסנו.\u0004 ואם חלף שיעור זמן כזה — חייב הראשון.","שנינו במשנה שאם \u0003כסהו\u0004 את הבור \u0003כראוי ונפל לתוכו שור או חמור ומת\u0004 — \u0003פטור.\u0004 ושואלים: ו\u0003כיון\u0004 ש\u0003כסהו כראוי היכי\u0004 \u0005[כיצד]\u0006 \u0003נפל? אמר ר' יצחק בר בר חנה: שהתליע\u0004 הכיסוי \u0003מתוכו,\u0004 ולא יכול היה לדעת שהכיסוי הזה נפגם, שבמקרה זה אנוס הוא, ואין אחריות הנזקים מוטלת עליו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003כסהו\u0004 את הבור \u0003כסוי שיכול לעמוד לפני שוורים,\u0004 שהוא חזק למדי כדי שיעברו עליו שוורים ולא יפול, \u0003ו\u0004אולם \u0003אין\u0004 הוא \u0003יכול לעמוד בפני גמלים\u0004 שהם כבדים יותר, \u0003ואתו\u0004 \u0005[ובאו]\u0006 \u0003גמלים\u0004 והלכו על הבור \u0003וארעוה\u0004 \u0005[וערערוהו]\u0006 את כיסויו, \u0003ו\u0004אחר כך \u0003אתו\u0004 \u0005[באו]\u0006 \u0003שוורים\u0004 ושברו בהליכתם את המכסה הרעוע \u0003ונפלי ביה\u0004 \u0005[ונפלו בו],\u0006 \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דשכיחי\u0004 \u0005[אם שמצויים]\u0006 \u0003גמלים\u0004 באותו מקום — אם כן \u0003פושע\u0004 (רשלן) \u0003הוא,\u0004 שהרי היה צריך לעשות כיסוי שראוי גם לגמלים, שהרי גם גמל יכול ליפול שם. \u0003ואי דלא שכיחי\u0004 \u0005[ואם שאין מצויים]\u0006 \u0003גמלים\u0004 באותו מקום, הרי אם הגיעו ועברו שם במקרה — \u0003אנוס הוא!\u0004","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לכגון \u0003דאתו\u0004 \u0005[שבאים]\u0006 גמלים שם \u0003לפרקים\u0004 מפעם לפעם, ובמקרה זה עולה השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 \u0003כיון דאתיין\u0004 \u0005[שבאים]\u0006 \u0003לפרקים\u0004 — \u0003פושע הוא,\u0004 כיון \u0003דאיבעי ליה אסוקי אדעתיה\u0004 \u0005[שהיה צריך לו להעלות על דעתו]\u0006 שיעברו גמלים, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דהשתא מיהת ליכא\u0004 \u0005[שעכשיו על כל פנים אין]\u0006 גמלים — \u0003אנוס הוא?\u0004","ומנסים להביא ראייה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנתנו: \u0003כסהו כראוי, ונפל לתוכו שור או חמור ומת\u0004 — \u0003פטור.\u0004 ויש לשאול: \u0003היכי דמי\u0004 \u0005[כיצד היה הדבר בדיוק]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שכיסהו \u0003כראוי לשוורים וכראוי לגמלים\u0004 — אם כן \u0003היכי נפול\u0004 \u0005[כיצד נפלו]\u0006 לתוכו? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן שכיסהו כיסוי \u0003כראוי לשוורים\u0004"],["\u0003ולא כראוי לגמלים,\u0004 ומעתה יש להוסיף ולברר: \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר \u0003דשכיחי\u0004 \u0005[שמצויים]\u0006 שם \u0003גמלים, אמאי\u0004 \u0005[מדוע]\u0006 \u0003פטור?\u0004 הלא \u0003פושע הוא! ואי\u0004 \u0005[ואם]\u0006 מדובר ש\u0003לא שכיחי\u0004 \u0005[מצויים]\u0006 שם \u0003גמלים\u0004 — אם כן \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שפטור, שהרי \u0003אנוס הוא! אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר שם באופן \u0003דאתיין\u0004 \u0005[שבאים]\u0006 גמלים \u0003לפרקים, ואתו\u0004 \u0005[ובאו]\u0006 \u0003גמלים וארעוה\u0004 \u0005[וקלקלו\u0006 \u0005אותו],\u0006 \u0003ואתו\u0004 \u0005[ובאו]\u0006 \u0003שוורים ונפלו ביה\u0004 \u0005[בו],\u0006 \u0003וקתני\u0004 \u0005[ושנה]\u0006 על כך שהוא \u0003פטור, אלמא\u0004 \u0005[מכאן],\u0006 \u0003כיון דהשתא ליכא\u0004 \u0005[שעכשיו אין]\u0006 הם מצויים — \u0003אנוס הוא!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 ודוחים: \u0003לא, לעולם\u0004 מדובר שכיסהו \u0003כראוי לשוורים וכראוי לגמלים, ודקא קשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 \u0003לך:\u0004 \u0003היכי נפול\u0004 \u0005[כיצד נפלו]?\u0006 על כך \u0003אמר ר' יצחק בר בר חנה:\u0004 מדובר באופן \u0003שהתליע\u0004 הכיסוי \u0003מתוכו,\u0004 ואם כן אין ללמוד מכאן דבר לענין ששאלנו.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה לדבר ממה ששנינו במשנה: \u0003לא כסהו כראוי, ונפל לתוכו שור או חמור ומת\u0004 — \u0003חייב.\u0004 ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שכיסהו \u0003לא כראוי לשוורים ולא כראוי לגמלים,\u0004 ונפלו שם — \u0003פשיטא, צריכא למימר\u0004 \u0005[פשוט,\u0006 מובן מאליו, וכי \u0005צריך לומר]\u0006 ש\u0003חייב\u0004 על כך? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר שכיסהו \u0003כראוי לשוורים ולא כראוי לגמלים,\u0004 ומעתה נברר: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה הדבר]?\u0006 \u0003אי דשכיחי\u0004 \u0005[אם שמצויים]\u0006 שם \u0003גמלים\u0004 — הלא \u0003פושע הוא, ואי\u0004 \u0005[ואם]\u0006 ש\u0003לא שכיחי\u0004 \u0005[מצויים]\u0006 שם \u0003גמלים\u0004 — הלא \u0003אנוס הוא!\u0004","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003דאתיין\u0004 \u0005[שבאים]\u0006 הגמלים \u0003לפרקים, ואתו\u0004 \u0005[ובאו]\u0006 \u0003גמלים וארעוהו\u0004 \u0005[וקלקלוהו],\u0006 \u0003ואתו\u0004 \u0005[ובאו]\u0006 \u0003שוורים ונפלו ביה\u0004 \u0005[בו],\u0006 \u0003וקתני\u0004 \u0005[ושנה]\u0006 על כך ש\u0003חייב. אלמא\u0004 \u0005[מכאן]:\u0006 \u0003כיון דאתיין\u0004 \u0005[שבאים]\u0006 \u0003לפרקים\u0004 — \u0003פושע הוא, דאיבעי ליה אסוקי אדעתיה\u0004 \u0005[ש\u0006הרי \u0005היה לו להעלות על דעתו]\u0006 שיבואו!","ודוחים: \u0003לעולם\u0004 אפשר לומר שהיה הכיסוי \u0003כראוי לשוורים ולא כראוי לגמלים, ו\u0004צריך לומר שבאותו מקום \u0003שכיחי\u0004 \u0005[מצויים]\u0006 באמת \u0003גמלים, ודקא קשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 \u0003לך:\u0004 הלא במקרה כזה \u0003פושע הוא\u0004 ופשוט שחייב, והלכה זו מיותרת במשנה! יש לומר כי \u0003איידי דנסיב רישא\u0004 \u0005[מתוך שנקט בראש]\u0006 מקרה של \u0003כסהו כראוי, נסיב סיפא נמי\u0004 \u0005[הביא גם כן בסופה]\u0006 מקרה ש\u0003לא כסהו כראוי.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 את הסוגיה הזו בגרסה אחרת: \u0003הא נמי\u0004 \u0005[זו גם כן]\u0006 \u0003ודאי לא איבעיא לן\u0004 \u0005[נסתפקה לנו],\u0006 ש\u0003כיון דאתיין\u0004 \u0005[\u0006שהם \u0005באים]\u0006 \u0003לפרקים\u0004 — \u0003פושע הוא, דאיבעי ליה אסוקי אדעתיה\u0004 \u0005[שהיה לו להעלות על דעתו]\u0006 שיבואו לשם.","\u0003כי איבעי לן\u0004 \u0005[כאשר נשאלה לנו]\u0006 השאלה — \u0003הכי\u0004 \u0005[כך]\u0006 \u0003הוא דאיבעיא לן\u0004 \u0005[שנשאלה לנו]:\u0006 \u0003כסהו כסוי שיכול לעמוד בפני שוורים ואינו יכול לעמוד בפני גמלים, ושכיחי\u0004 \u0005[ומצויים]\u0006 \u0003גמלים\u0004 במקום, ואולם הכיסוי הזה \u0003התליע מתוכו, מהו\u0004 הדין בכגון זה? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003מגו דהוי\u0004 \u0005[מתוך שהריהו]\u0006 \u0003פושע אצל גמלים, הוי\u0004 \u0005[הריהו]\u0006 נחשב \u0003פושע נמי\u0004 \u0005[גם כן]\u0006 \u0003לענין התלעה, או דלמא לא אמרינן \"מגו\"\u0004 \u0005[שמא אין אנו אומרים \"מתוך\"]\u0006 ומאחר שבפועל לא אירע הדבר באשמתו אינו חייב?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במשנתנו: \u0003כסהו כראוי, ונפל לתוכו שור או חמור ומת\u0004 — \u0003פטור, ואתמר עלה\u0004 \u0005[ונאמר עליה]\u0006 \u0003אמר ר' יצחק בר בר חנה: שהתליע מתוכו.\u0004 ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר כאן שכיסהו \u0003כראוי לשוורים וכראוי לגמלים, והתליע מתוכו\u0004 — \u0003פשיטא\u0004 \u0005[פשוט\u0006, מובן מאליו\u0005]\u0006 שהוא \u0003פטור,\u0004 שהרי \u0003מאי הוה ליה למעבד\u0004 \u0005[מה היה לו לעשות]?\u0006 הרי לא יכול היה לדעת דבר זה.","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר במקרה כאן, שכיסהו \u0003כראוי לשוורים ולא כראוי לגמלים, ושכיחי\u0004 \u0005[ומצויים]\u0006 \u0003גמלים\u0004 שם, \u0003והתליע מתוכו, וקתני\u0004 \u0005[ושנה]\u0006 במשנה: \u0003פטור, אלמא לא אמרינן\u0004 \u0005[מכאן\u0006 ש\u0005אין אנו אומרים]:\u0006 \u0003מגו דהוי\u0004 \u0005[מתוך שהריהו]\u0006 נחשב \u0003פושע לענין גמלים הוי\u0004 \u0005[הריהו]\u0006 גם כן \u0003פושע לענין התלעה!\u0004","ודוחים: \u0003לא, לעולם\u0004 תפרש שמדובר כאן שכיסהו \u0003כראוי לגמלים וכראוי לשוורים, והתליע מתוכו. ודקא קשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 \u0003לך: כי\u0004 \u0005[כאשר]\u0006 \u0003התליע\u0004 מתוכו \u0003מאי הוה ליה למעבד\u0004 \u0005[מה היה לו לעשות]\u0006 עוד על מה שעשה, ופשוט הוא שפטור? יש בכך חידוש, כי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003איבעי ליה למיזל ומנקש עליה\u0004 \u0005[היה לו ללכת ולהקיש עליו,\u0006 על הכיסוי\u0005]\u0006 כדי לברר אם איננו חלול מתוכו, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שעד כדי כך אין מחייבים אותו לבדוק.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת ממה ששנינו בהמשך המשנה: \u0003לא כסהו כראוי, ונפל לתוכו שור או חמור ומת\u0004 — \u0003חייב.\u0004 ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר ש\u0003לא\u0004 כיסה את הבור \u0003כראוי לשוורים ולא כראוי לגמלים\u0004 — האם \u0003צריכא למימר\u0004 \u0005[צריך לומר]\u0006 ש\u0003חייב\u0004 בזה?","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר במקרה שכיסהו \u0003כראוי לשוורים ולא כראוי לגמלים, ו\u0004מעתה באיזה אופן מדובר? \u0003אי דשכיחי\u0004 \u0005[אם שמצויים]\u0006 \u0003גמלים\u0004 במקום — הלא \u0003פושע הוא, ואי\u0004 \u0005[ואם]\u0006 מדובר ש\u0003לא שכיחי\u0004 \u0005[מצויים]\u0006 \u0003גמלים\u0004 שם — הלא \u0003אנוס הוא! אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר באופן \u0003דשכיחי\u0004 \u0005[שמצויים]\u0006 שם \u0003גמלים, והתליע מתוכו, וקתני\u0004 \u0005[ושנה]\u0006 במשנה ש\u0003חייב, אלמא אמרינן\u0004 \u0005[מכאן\u0006 ש\u0005אנו אומרים]:\u0006 \u0003מגו דהוי\u0004 \u0005[מתוך שהריהו]\u0006 \u0003פושע לענין גמלים הוי\u0004 \u0005[הריהו]\u0006 \u0003פושע\u0004 אף \u0003לענין התלעה\u0004 וחייב!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 ודוחים: \u0003לא, לעולם\u0004 יש לפרש שמדובר שכיסהו \u0003כראוי לשוורים ולא כראוי לגמלים, ושכיחי\u0004 \u0005[ומצויים]\u0006 שם \u0003גמלים, ואתו\u0004 \u0005[ובאו]\u0006 \u0003גמלים וארעוהו\u0004 \u0005[וקלקלו אותו],\u0006 \u0003ואתו\u0004 \u0005[ובאו]\u0006 \u0003שוורים ונפלו ביה\u0004 \u0005[בו],\u0006 \u0003ודקא קשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 \u0003לך: פשיטא\u0004 \u0005[פשוט\u0006, מובן מאליו\u0005]\u0006 שכן הוא הדין, שהרי \u0003פושע הוא\u0004 ומה חידוש יש בדבר! יש להסביר: \u0003איידי דנסיב רישא\u0004 \u0005[מתוך שנקט\u0006 ב\u0005תחילה]\u0006 מקרה של \u0003כסהו כראוי, נסיב סיפא נמי\u0004 \u0005[נקט\u0006 ב\u0005סוף גם כן]\u0006 מקרה ש\u0003לא כסהו.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת ממה ששנינו: \u0003נפל לתוכו שור\u0004 שהיה \u0003חרש\u0004 או \u0003שוטה ו\u0004כן \u0003קטן\u0004 או \u0003סומא ו\u0004כן \u0003מהלך בלילה\u0004 — \u0003חייב\u0004 בעל דהבור. היה השור \u0003פקח\u0004 (רואה) \u0003ומהלך ביום\u0004 — \u0003פטור\u0004 בעל הבור, שהיה על השור להסתכל. \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יהיה פטור? \u0003נימא:\u0004 \u0005[נאמר]:\u0006 \u0003מדהוי\u0004 \u0005[מכיון שהריהו]\u0006 \u0003פושע לענין\u0004 שור \u0003חרש, הוי נמי\u0004 \u0005[הריהו גם כן]\u0006 \u0003פושע לענין\u0004 שור \u0003פקח! אלא לאו שמע מיניה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 בכגון זה \u0003מגו\u0004 \u0005[מתוך]\u0006 שפושע לענין אחד הרי זה נחשב פשיעה לדבר אחר, אלא מחייבים אותו רק על אותו נזק שגרמה אותה רשלנות. ומסכמים: אכן \u0003שמע מיניה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","שנינו במשנה: \u0003נפל לפניו\u0004 מקול הכרייה — חייב, לאחריו מקול הכרייה — פטור. \u0003אמר רב: \"לפניו\"\u0004 ששנינו פירושו \u0003לפניו ממש,\u0004 שנפל השור על פניו, ו\u0003\"לאחריו\"\u0004 משמעו \u0003אחריו ממש,\u0004 שנפל אחורנית,"],["\u0003וזה וזה\u0004 שנפל \u0003ב\u0004תוך \u0003בור\u0004 עצמו. ובכל זאת, אם נפל לאחוריו — פטור.","ומעירים, \u0003רב לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רב: בור שחייבה עליו\u0004 ה\u0003תורה\u0004 — \u0003להבלו\u0004 חייבה \u0003ולא לחבטו.\u0004 וכיון שנפל השור לאחוריו, על גבו — לא מן ההבל ניזוק, אלא מן החבטה.","\u0003ושמואל אמר:\u0004 אם נפל השור \u0003ב\u0004תוך \u0003בור, בין מלפניו בין מלאחריו\u0004 — \u0003חייב.\u0004","ומעירים, \u0003שמואל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר\u0004 שחיוב בור הוא \u0003להבלו וכל שכן לחבטו.\u0004 ושואלים: \u0003אלא\u0004 לשמואל \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הוא],\u0006 באיזה אופן אמרה המשנה שאם נפל \u0003לאחריו מקול הכרייה\u0004 ש\u0003פטור?\u0004 ומסבירים: \u0003כגון\u0004 ש\u0003נתקל\u0004 השור \u0003בבור, ונפל לאחורי הבור\u0004 ונחבל \u0003חוץ לבור.\u0004","\u0003איתיביה\u0004 \u0005[הקשו]\u0006 לרב ממה ששנינו בברייתא: \u0003בבור, בין לפניו בין לאחריו\u0004 — \u0003חייב,\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 ל\u0003רב!\u0004","\u0003אמר רב חסדא: מודה רב בבור\u0004 שהוא \u0003ברשותו\u0004 של אדם שהוא \u0003חייב\u0004 אף אם נפל לאחוריו, \u0003משום דאמר ליה\u0004 \u0005[שאומר לו]\u0006 הניזוק לבעל הבור: \u0003ממה נפשך\u0004 \u0005[ממה,\u0006 מאיזה צד \u0005רצונך]\u0006 לטעון? \u0003אי בהבלא מית\u0004 \u0005[אם\u0006 משום \u0005ההבל מת]\u0006 — הרי \u0003הבלא דידך\u0004 \u0005[ההבל שלך]\u0006 \u0003הוא,\u0004 \u0003אי בחבטא מית\u0004 \u0005[אם בחבטה מת]\u0006 — \u0003חבטא דידך\u0004 \u0005[חבטה\u0006 של הקרקע \u0005שלך]\u0006 \u0003הוא\u0004 ולא קרקע עולם, כפי שהוא במקרה רגיל של בור.","\u0003רבה אמר,\u0004 כך יש להסביר את הברייתא לדברי רב: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — \u0003במתהפך,\u0004 כיצד ש\u0003נפל\u0004 בתחילה \u0003אאפיה\u0004 \u0005[על פניו]\u0006 \u0003ו\u0004אחר כך \u0003אתהפיך\u0004 \u0005[\u0006\u0005התהפך]\u0006 \u0003ונפל אגביה\u0004 \u0005[על גבו],\u0006 \u0003דהבלא דאהני ביה אהני ביה\u0004 \u0005[שההבל שהועיל\u0006 \u0005בו,\u0006 שגרם לו נזק, \u0005הועיל בו]\u0006 להמיתו.","\u0003רב יוסף אמר: הכא\u0004 \u0005[כאן]\u0006 בברייתא זו \u0003בנזקי בור בשור עסקינן\u0004 \u0005[אנו עוסקים]\u0006 בנזקים שהשור הזיק את הבור, \u0003מאי ניהו\u0004 \u0005[מה הם]?\u0006 \u0003שהבאיש את מימיו\u0004 של הבור, ובזה אמרה הברייתא כי \u0003לא שנא\u0004 \u0005[שונה]\u0006 אם נפל \u0003לפניו, ולא שנא\u0004 \u0005[שונה]\u0006 אם נפל \u0003לאחריו\u0004 — \u0003מיחייב\u0004 \u0005[חייב].\u0006","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב חנניה\u0004 ברייתא \u0003לסיועי\u0004 \u0005[לסייע]\u0006 \u0003ל\u0004שיטת \u0003רב,\u0004 שעל הכתוב האמור בנזקי בור \u0003\"ונפל\"\u0004 (שמות כא, לג) פירשו: \u0003עד שיפול דרך נפילה. מכאן אמרו: נפל לפניו מקול הכרייה\u0004 — \u0003חייב, לאחריו מקול הכרייה\u0004 — \u0003פטור, וזה וזה בבור.\u0004","\u0003אמר מר\u0004 \u0005[החכם]\u0006 במשנה: \u0003נפל\u0004 השור \u0003לפניו מקול הכרייה\u0004 — \u0003חייב.\u0004 ויש לשאול: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003נימא\u0004 \u0005[נאמר]\u0006 כי קולו של \u0003כורה\u0004 הוא ש\u0003גרם ליה\u0004 \u0005[לו]\u0006 את הנפילה, ולא הבור עצמו! \u0003אמר רב שימי בר אשי: הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' נתן היא,\u0004 ש\u0003אמר: בעל הבור הזיקא קא עביד\u0004 \u0005[היזק הוא שעושה]\u0006 בחפירתו, \u0003וכל היכא\u0004 \u0005[מקום]\u0006 ש\u0003לא אפשר לאשתלומי מהאי\u0004 \u0005[לקבל תשלום מזה]\u0006 שגרם לנפילה \u0003משתלם מהאי\u0004 \u0005[מקבל תשלום מזה]\u0006 שעל כל פנים הוא חייב באחריות על הנזק שיצר.","ומהיכן למדנו שיטתו זו של ר' נתן? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שור שדחף את חבירו לבור\u0004 — \u0003בעל השור חייב,\u0004 ו\u0003בעל הבור פטור. ר' נתן אומר: בעל השור משלם מחצה ובעל הבור משלם מחצה.\u0004","ומבררים את שיטת ר' נתן: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת ש\u0003ר' נתן אומר:\u0004 במקרה זה של שור שדחף שור אחר לבורו של אחר — \u0003בעל הבור משלם שלשה חלקים\u0004 (רבעים), \u0003ובעל השור רביע\u0004 (רבע)! ואין זה כשיטתו בברייתא הקודמת. ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא\u0004 \u0005[\u0006בברייתא \u0005זו\u0006 השניה\u0005]\u0006 מדובר \u0003ב\u0004מקרה שהשור הדוחף היה \u0003תם\u0004 ואז בעל השור משלם רק רבע נזק (שהוא מחצית ממה שחייב, שהוא חצי הנזק), \u0003הא\u0004 \u0005[\u0006בברייתא \u0005זו\u0006 הקודמת\u0005]\u0006 מדובר \u0003ב\u0004שור \u0003מועד\u0004 שדחף ולכן משלם את כל חלקו שהוא חצי נזק.","ושואלים: \u0003וב\u0004שור \u0003תם מאי קסבר\u0004 \u0005[מה סבור]\u0006 ר' נתן, מדוע משלם זה רבע וזה שלושה רבעים? \u0003אי קסבר האי כוליה הזיקא עבד והאי כוליה הזיקא עבד\u0004 \u0005[אם הוא סבור\u0006 ש\u0005זה,\u0006 השור, את \u0005כל הנזק עשה, וזה,\u0006 הבור, את \u0005כל הנזק עשה],\u0006 אם כן צריך היה לפסוק כי \u0003האי\u0004 \u0005[זה]\u0006 \u0003משלם פלגא\u0004 \u0005[חצי]\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 \u0003משלם פלגא\u0004 \u0005[חצי],\u0006 שהרי לשניהם יש אחריות שלימה, ואף אם היה זה שור תם, משלם חצי נזק שהוא מחצית ממה שגרם.","\u0003ואי קסבר\u0004 \u0005[ואם\u0006 הוא \u0005סבור]\u0006 כי \u0003האי פלגא הזיקא עבד והאי פלגא הזיקא עבד\u0004 \u0005[זה,\u0006 השור, \u0005חצי נזק עשה, וזה,\u0006 הבור, \u0005חצי נזק עשה],\u0006 אם כן צריך היה לפסוק ש\u0003בעל הבור משלם פלגא\u0004 \u0005[חצי]\u0006 שהוא מלוא הסכום על המחצית שהיא באחריותו, \u0003ובעל השור\u0004 שהוא תם משלם רק \u0003רביע,\u0004 שהרי הוא משלם רק חצי הסכום שהזיק, \u0003ואידך ריבעא\u0004 \u0005[ו\u0006את \u0005הרבע האחר]\u0006 \u0003מפסיד\u0004 בעל השור. ואם כן מה טעמו של ר' נתן?","\u0003אמר רבא: ר' נתן דיינא\u0004 \u0005[דיין]\u0006 \u0003הוא ונחית לעומקא דדינא\u0004 \u0005[ויורד לעומק הדין],\u0006 \u0003לעולם קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 כי \u0003האי כוליה הזיקא עבד והאי כוליה הזיקא עבד\u0004 \u0005[זה\u0006 את \u0005כל הנזק עשה וזה\u0006 את \u0005כל הנזק עשה],\u0006 \u0003ודקא קשיא\u0004 \u0005[\u0006ומה \u0005ש\u0006היה \u0005קשה]\u0006 \u0003לך\u0004 \u0003:\u0004 אם כן \u0003לשלם האי פלגא והאי פלגא\u0004 \u0005[שישלם זה חצי וזה חצי]\u0006 ומדוע משלם בעל השור רק רבע ובעל הבור שלושה רבעים? הרי זה \u0003משום דאמר ליה\u0004 \u0005[שאומר לו]\u0006 \u0003בעל השור לבעל הבור: שותפותאי מאי אהניא\u0004 \u0005[שותפותי\u0006 אתך באחריות \u0005מה הועילה]\u0006 \u0003לי,\u0004 שהרי גם אם היה שורי גורם את כל הנזק בלי הבור לא הייתי משלם יותר מחצי. ומעתה, שאנו שותפים בנזק, עליך לשלם מחצית מכלל הנזק שהייתי משלם (הואיל וממילא צריך היית לשלם נזק שלם).","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 והסבר באופן אחר: \u0003לעולם קסבר\u0004 \u0005[סבור]\u0006 ר' נתן כי \u0003האי פלגא הזיקא עבד והאי פלגא הזיקא עבד\u0004 \u0005[זה חצי נזק עשה וזה חצי נזק עשה].\u0006 \u0003ודקא קשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 \u0003לך:\u0004 מדוע אין \u0003בעל הבור משלם פלגא\u0004 \u0005[חצי]\u0006 \u0003ובעל השור משלם רביע, ואידך ריבעא נפסיד\u0004 \u0005[ו\u0006את \u0005הרבע האחר שיפסיד]\u0006 בעל השור שניזוק? — אין הדין כן \u0003משום דאמר ליה\u0004 \u0005[שאומר לו]\u0006 \u0003בעל השור\u0004 הניזוק \u0003לבעל הבור:\u0004 \u0003אנא תוראי בבירך אשכחיתיה, את קטלתיה\u0004 \u0005[אני\u0006 את \u0005שורי בבורך מצאתיו, אתה\u0006 הוא ש\u0005הרגת אותו],\u0006 שהרי רואים אותו הרוג שם, ולכן \u0003מאי דאית\u0004 \u0005[מה שיש]\u0006 \u0003לי לאשתלומי מהיאך\u0004 \u0005[לקבל תשלום מן האחר],\u0006 מבעל השור המזיק — \u0003משתלמנא\u0004 \u0005[מקבל אני],\u0006 \u0003מאי דלית\u0004 \u0005[מה שאין]\u0006 \u0003לי\u0004 אפשרות \u0003לאשתלומי מהיאך\u0004 \u0005[לקבל תשלום ממנו]\u0006 — \u0003משתלמנא ממך\u0004 \u0005[מקבל אני ממך].\u0006","ובאותו ענין \u0003אמר רבא: הניח\u0004 אדם \u0003אבן על פי הבור\u0004 של אדם אחר, \u0003ובא שור ונתקל בה ונפל בבור, באנו למחלוקת ר' נתן ורבנן,\u0004 ביחס לחלוקת האחריות ביניהם. ותוהים: מה חידש בדבר? \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו הוא\u0005],\u0006 שהרי מה ההבדל אם נפל השור לבור בגלל שור אחר, או בגלל האבן?","ומשיבים: יש צורך לומר דבר זה במפורש, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא דאמר\u0004 \u0005[שאומר]\u0006 \u0003בעל הבור לבעל השור: אי לאו בירא דידי, תורא דידך הוה קטיל ליה\u0004 \u0005[אם לא הבור שלי, השור שלך היה הורג אותו]\u0006 ולמעשה בורי לא היה הגורם לנזק אלא שורך, \u0003אבל הכא מצי אמר ליה\u0004 \u0005[כאן יכול לומר לו]\u0006 \u0003בעל\u0004 ה\u0003אבן לבעל הבור: אי לאו בירא דידך, אבנא דידי מאי הוה עבדא\u0004 \u0005[אם לא הבור שלך, האבן שלי מה היתה עושה]?\u0006 \u0003אי הוה מיתקל\u0004 \u0005[אם היה נתקל]\u0006 \u0003בה, הוה נפל וקאי\u0004 \u0005[היה נופל וקם]\u0006 ולכן יש לפוטרו לגמרי, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רבא שאין זו טענה, משום \u0003דאמר ליה\u0004 \u0005[שיכול לומר לו]\u0006 בעל הבור לבעל האבן בתשובה לכך: \u0003אי לאו\u0004 \u0005[אם לא]\u0006 ה\u0003אבן\u0004 שלך \u0003לא הוה נפיל לבירא\u0004 \u0005[היה נופל לבור].\u0006","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בבעיה הבאה:"],["\u0003שור\u0004 תם של הדיוט \u0003ושור פסולי המוקדשין שנגחו\u0004 שניהם שור אחר, ו\u0003מאי ניהו\u0004 \u0005[ומה הוא]\u0006 שור פסולי המוקדשים שמדובר בו כאן — כגון \u0003שור בכור\u0004 שנעשה בעל מום, ונפסל בכך להקרבה, ואולם נשארה בו קדושה ראשונה שהיתה בו, ש\u0003לא פריק ליה\u0004 \u0005[פודה אותו],\u0006 שהרי בכור אין לו פדיון. ושור כזה שנגח, אין הכהן המחזיק בו חייב לשלם, שאין זה \"שור רעהו\", ונשאלה השאלה: כיצד ישלם בעל שור החולין שנגח יחד איתו? \u0003אביי אמר: משלם\u0004 \u0003חצי נזק, רבינא אמר: משלם רביע\u0004 (רבע) \u0003נזק.\u0004","ומסבירים את מחלוקתם: \u0003הא והא\u0004 \u0005[זה וזה],\u0006 אביי ורבינא, מדברים \u0003ב\u0004מקרה שהיה זה שור החולין שנגח שור \u0003תם,\u0004 אלא \u0003הא\u0004 \u0005[זה]\u0006 רבינא סבור \u0003כ\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 ששני הצדדים אחראים כל אחד לחצי נזק, וכיון שהיה שור החולין שור תם — משלם מחצית מן הנזק שאחראי לו, שהוא רביע. \u0003והא\u0004 \u0005[וזה]\u0006 שאמר אביי הוא \u0003כ\u0004דעת \u0003ר' נתן\u0004 שכל אחד אחראי לכל הנזק, וכיון ששור החולין הריהו תם — ישלם מחצית.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שאינם חולקים, \u0003הא והא\u0004 \u0005[זה וזה],\u0006 אביי ורבינא, סבורים \u0003כרבנן\u0004 \u0005[כחכמים],\u0006 אלא \u0003הא\u0004 \u0005[זה,\u0006 רבינא\u0005]\u0006 מדבר \u0003ב\u0004שהיה שור החולין שור \u0003תם\u0004 ואז משלם מחצית מן המחצית, ו\u0003הא\u0004 \u0005[זה,\u0006 אביי\u0005]\u0006 מדבר \u0003ב\u0004שור חולין \u0003מועד,\u0004 ולכן משלם חצי הנזק.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בגרסה אחרת, שכך היתה המחלוקת, \u0003אביי אמר:\u0004 משלם \u0003חצי נזק, רבינא אמר: כוליה\u0004 \u0005[כל]\u0006 \u0003נזק.\u0004 ומסבירים את מחלוקתם: \u0003הא והא\u0004 \u0005[זה וזה]\u0006 מדברים \u0003ב\u0004שור \u0003מועד,\u0004 אלא, \u0003הא\u0004 \u0005[זה,\u0006 אביי\u0005]\u0006 סבור \u0003כרבנן\u0004 \u0005[כ\u0006דברי \u0005חכמים]\u0006 שעל כל אחד מהם יש חצי אחריות, ולכן משלם חצי נזק, \u0003והא\u0004 \u0005[וזה\u0006 רבינא\u0005]\u0006 \u0003כ\u0004דעת \u0003ר' נתן\u0004 שכל אחד אחראי לנזק כולו, וגובים ממזיק אחד כאשר המזיק האחד פטור מתשלום.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שאינם חולקים, וכי \u0003הא והא\u0004 \u0005[זה וזה]\u0006 סבורים \u0003כר' נתן,\u0004 אלא \u0003הא\u0004 \u0005[זה,\u0006 רבינא\u0005]\u0006 דיבר \u0003במועד\u0004 המשלם נזק שלם, \u0003והא\u0004 \u0005[וזה\u0006 אביי\u0005]\u0006 \u0003בתם\u0004 המשלם רק חצי נזק.","ועוד בענין דומה \u0003אמר רבא: שור ואדם שדחפו\u0004 דבר \u0003לבור. לענין נזקין\u0004 שגרמו — \u0003כולן\u0004 האדם הדוחף, בעל השור, ובעל הבור \u0003חייבין. לענין ארבעה דברים:\u0004 שבת, צער, ריפוי, בושת, \u0003ודמי ולדות\u0004 באשה שהפילה את עוברה — \u0003אדם חייב, ו\u0004בעל ה\u0003שור ו\u0004בעל ה\u0003בור פטור,\u0004 שהרי לא הטילה התורה עליהם חובת תשלום על נזקים אלה.","\u0003לענין\u0004 תשלום \u0003כופר\u0004 אם נהרג שם אדם, \u0003ו\u0004כן לענין \u0003שלשים\u0004 שקלים \u0003של עבד\u0004 שמת בבור מדחיפתם — \u0003שור חייב, אדם ובור פטורים.\u0004 \u0003לענין כלים\u0004 שנפלו שם, \u0003ו\u0004כן לענין \u0003שור פסולי המוקדשין\u0004 שנפל שם — \u0003אדם ושור חייבין, ובור פטור.\u0004","ומסביר רבא: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר שבשור פסולי המוקדשים בעל הבור פטור? — \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בבור: \u0003\"והמת יהיה לו\"\u0004 (שמות כא, לד) — ללמדנו שחיוב תשלומים בבור הוא רק \u0003במי שהמת שלו, יצא זה\u0004 (שור פסולי המוקדשים) \u0003שאין המת שלו,\u0004 שהרי אסור למכור נבלתו של שור פסולי המוקדשין, ואם כן אין לבעל הבור ממנו כל הנאה, והנבילה אינה שייכת עוד לאיש.","ושואלים: \u0003למימרא, דפשיטא ליה\u0004 \u0005[האם לומר שפשוט לו]\u0006 \u0003לרבא\u0004 דין זה? \u0003והא מיבעיא בעי ליה\u0004 \u0005[והרי נשאלה שאלה זו]\u0006 \u0003לרבא, דבעי\u0004 \u0005[ששאל]\u0006 \u0003רבא: שור פסולי המוקדשין שנפל לבור מהו?\u0004 האם \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"והמת יהיה לו\"\u0004 כוונתו \u0003במי שהמת שלו\u0004 וללמדנו: \u0003יצא\u0004 שור \u0003זה שאין המת שלו\u0004 ולכן אינו משלם עבורו. \u0003או דילמא\u0004 \u0005[שמא]\u0006 מה שנאמר \u0003\"והמת יהיה לו\"\u0004 ללמד הלכה זו שה\u0003בעלים מטפלין\u0004 (מתעסקים) \u0003בנבילה הוא דאתא\u0004 \u0005[שבא],\u0006 כלומר, שהנבילה שלו, והמזיק משלם לו את ההפרש?","ומשיבים: זו אינה קושיה, אמנם בתחילה היה רבא מסופק בכך, אלא \u0003בתר דבעיא הדר פשטה\u0004 \u0005[אחרי ששאל אותה, חזר\u0006 ו\u0005פתר אותה],\u0006 את בעייתו, והחליט שהכתוב בא ללמדנו שחיוב בור הוא במי שהמת שלו, ולמעט שור פסולי המוקדשים.","ושואלים: \u0003אלא\u0004 מעתה הלכה זו ש\u0003בעלים מטפלין בנבילה מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 נלמד הדבר \u0003מן\u0004 הכתוב \u0003\"והמת יהיה לו\"\u0004 שנאמר ב\u0003שור\u0004 (שמות כא, לו). ושואלים: \u0003מאי חזית\u0004 \u0005[מה ראית]\u0006 לומר שבכתוב \u0003\"והמת יהיה לו\"\u0004 הכתוב ב\u0003שור מפקת ליה\u0004 \u0005[מוציא אתה\u0006 ומפרש \u0005אותו]\u0006 שבא \u0003ל\u0004ענין \u0003בעלים מטפלין בנבילה, \"והמת יהיה לו\"\u0004 הכתוב ב\u0003בור מפקת ליה\u0004 \u0005[מוציא אתה\u0006 ומפרש \u0005אותו]\u0006 שבא \u0003ל\u0004ענין \u0003מי שהמת שלו? איפוך אנא\u0004 \u0005[אהפוך אני]\u0006 ואומר להיפך!","ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 הדבר ש\u0003פטור גבי\u0004 \u0005[אצל]\u0006 \u0003בור הואיל\u0004 והקל הכתוב בדינו \u0003ופטר בו את הכלים\u0004 שנפלו ונשברו. ומקשים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 נאמר ש\u0003פטור גבי\u0004 \u0005[אצל]\u0006 \u0003שור, שכן פטר בו חצי נזק\u0004 בשור תם! ומשיבים: \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003נזק מיהת\u0004 \u0005[על כל פנים]\u0006 \u0003לא אשכחן\u0004 \u0005[מצאנו]\u0006 שיהא בעל השור פטור לגמרי, ואילו בבור מצאנו שיש דברים שאינו חייב עליהם כלל, ומסתבר לומר שבבור מקילה התורה יותר מבנזקי שור.","שנינו במשנה: \u0003נפל לתוכו,\u0004 לבור, \u0003שור וכליו ונשתברו\u0004 — חייב על השור ולא על הכלים. ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' יהודה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יהודה מחייב על נזקי כלים בבור.\u0004","ומסבירים, \u0003מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים]:\u0006 — ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ונפל שמה שור או חמור\"\u0004 (שמות כא, לג) ומדייקים: \u0003\"שור\"\u0004 — \u0003ולא אדם\u0004 שעל מותו אין חייב בעל הבור, \u0003\"חמור\"\u0004 להדגיש — \u0003ולא כלים. ור' יהודה\u0004 דורש: \u0003\"או\"\u0004 שנאמר בכתוב \"שור או חמור\" הרי זה בא \u0003לרבות את הכלים.\u0004 ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 כיצד מפרשים הם \"או\" זה?"],["ומשיבים: \u0003\"או\"\u0004 זה \u0003מיבעי ליה\u0004 \u0005[נצרך לו,\u0006 להם\u0005]\u0006 כדי \u0003לחלק,\u0004 שלא נאמר שחייב בבור רק כשנופלים שם שור וחמור יחד. ואומרים: \u0003ור' יהודה,\u0004 ענין זה של \u0003לחלק מ\"ונפל\" נפקא\u0004 \u0005[יוצא\u0006 לו\u0005],\u0006 כלומר, מלשון יחיד שכתוב שם, שמשמעה אחד ולא שניים. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 משיבים על כך: \u0003\"ונפל\" טובא\u0004 \u0005[הרבה]\u0006 \u0003משמע,\u0004 שאין להוכיח מפועל שנאמר בצורת לשון יחיד שגם שם העצם שבא אחריו הוא יחיד.","ולשתי השיטות מקשים, \u0003אימא\u0004 \u0005[אמור]\u0006 ודרוש את הפסוק כך: \u0003\"ונפל\"\u0004 — הוא \u0003כלל, \"שור וחמור\"\u0004 — \u0003פרט,\u0004 ונדון לפי כללי מדרש ההלכה ש\u0003כלל ו\u0004אחריו \u0003פרט\u0004 —\u0003 אין בכלל אלא מה שבפרט\u0004, ולפיכך \u0003שור וחמור\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: בהמשך הכתוב בפסוק שלאחריו שנאמר \u0003\"בעל הבור ישלם\"\u0004 (שמות כא, לד) הרי \u0003חזר וכלל,\u0004 ולכן הרי זה כלל ופרט וכלל, ולפי כללי מדרש ההלכה: \u0003כלל ופרט וכלל אי\u0004 (אין) \u0003אתה דן\u0004 את הכלל \u0003אלא כעין הפרט\u0004 הנזכר שם. ולענייננו: \u0003מה הפרט מפורש\u0004 — שור וחמור, שהם \u0003בעלי חיים, אף כל\u0004 מה שנוסף בכלל הוא \u0003בעלי חיים.\u0004","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 דורשים את הכלל כעין הפרט, מדוע לא נדרוש כך: \u0003מה הפרט מפורש\u0004 — \u0003דבר\u0004 (בעל חיים) \u0003שנבלתה מטמאה במגע ובמשא\u0004 אם אדם נגע בו או נשא אותו (בלא מגע ישיר), שדין זה הוא גם בשור וגם בחמור, \u0003אף כל דבר שנבלתה מטמאה במגע ובמשא\u0004 חייב עליו בנזקי בור, \u0003אבל עופות\u0004 שאין בנבלתם טומאת מגע ומשא — \u0003לא!\u0004","ומשיבים: \u0003אם כן, נכתוב רחמנא חד פרטא\u0004 \u0005[שתכתוב התורה\u0006 רק \u0005פרט אחד]\u0006 ונלמד דבר זה ממנו. ושואלים: \u0003הי נכתוב\u0004 \u0005[איזה\u0006 פרט ש\u0005תכתוב\u0006 התורה\u0005]?\u0006 שהרי אם היה נכתב רק פרט אחד אפשר לבוא למסקנה מוטעה, \u0003אי כתב\u0004 \u0005[אם היה כותב]\u0006 רק \u0003\"שור\" הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 נלמד מכאן שדבר ה\u0003קרב לגבי מזבח\u0004 כגון שור — \u0003אין\u0004 \u0005[כן]\u0006 חייב עליו, ואילו זה \u0003שאינו קרב לגבי מזבח\u0004 — \u0003לא.\u0004 \u0003ואי כתב רחמנא\u0004 \u0005[ואילו היתה כותבת התורה]\u0006 רק \u0003\"חמור\" הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 מה ש\u0003קדוש בבכורה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 חייב עליו, דבר \u0003שאין קדוש בבכורה\u0004 — \u0003לא,\u0004 שהרי בכור חמור (\"פטר חמור\") יש בו קדושה וחייב בפדיון, ולא היינו למדים מכאן לבעלי חיים אחרים, מלבד אלה החייבים בבכורה, על כן אמר הכתוב גם \"שור\" וגם \"חמור\". וחוזרת איפוא הקושיה ראשונה: מדוע לא נלמד מכאן בדרך כלל ופרט וכלל למעט עופות?","\u0003אלא\u0004 יש לחזור מדרך לימוד זו לענין חיוב בור, וללמוד זאת מדיוק הכתובים, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"והמת יהיה לו\"\u0004 (שמות כא, לו) ונלמד מכאן: \u0003כל דבר\u0004 \u0005[ש\u0006הוא \u0005בן]\u0006 \u0003מיתה,\u0004 כל דבר שיכול למות.","ומקשים: אם זהו הכלל בחיובי בור, הרי \u0003בין לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 \u0003דקא ממעטי להו\u0004 \u0005[שממעטים]\u0006 את ה\u0003כלים\u0004 מכתוב אחר\u0003, ובין ל\u0004דעת \u0003ר' יהודה דקא מרבי להו\u0004 \u0005[שמרבה אותם]\u0006 את ה\u0003כלים,\u0004 וכי \u0003כלים בני מיתה נינהו\u0004 \u0005[הם]?\u0006 וכיוון שאינם בני מיתה — לכאורה לא היה צריך לימוד מיוחד לעניינם! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: אף כלים יכולים להיחשב כבנימיתה, שכן \u0003שבירתן זו היא מיתתן.\u0004","ומוסיפים ושואלים על הסבר זה: \u0003ול\u0004דעת \u0003רב\u0004 ש\u0003אמר: בור שחייבה עליו תורה\u0004 על \u0003הבלו\u0004 המזיק חייבה, \u0003ולא\u0004 על \u0003חבטו,\u0004 אם כן \u0003בין לרבנן\u0004 \u0005[לחכמים]\u0006 \u0003בין לר' יהודה\u0004 נשאלת השאלה: וכי \u0003כלים בני הבלא נינהו\u0004 \u0005[הבל הם]?\u0006 כלומר, האם מסוגלים הם להינזק מהבל, שהיה צורך בכתוב מיוחד למעטם מחיוב בור? \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: אכן, יש גם מקרה כזה — \u0003בחדתי דמיפקעי מהבלא\u0004 \u0005[ב\u0006כלים \u0005חדשים שפוקעים מ\u0006חמת \u0005ההבל].\u0006","ושואלים עוד: הלא \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"והמת יהיה לו\" מבעי ליה\u0004 \u0005[נצרך\u0006 הוא \u0005לו]\u0006 \u0003לכ\u0004מו שאמר \u0003רבא,\u0004 ש\u0003אמר רבא: שור פסולי המוקדשין שנפל לבור\u0004 — \u0003פטור, שנאמר: \"והמת יהיה לו\"\u0004 — \u0003במי שהמת שלו, יצא זה שאין המת שלו.\u0004 ואם כן אין אפשרות ללמוד מכאן לימוד אחר!","\u0003אלא\u0004 חיובי בור יש ללמוד ממקור אחר, ומה ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בבור: \u0003\"כסף ישיב לבעליו\"\u0004 (שמות כא, לד) הרי זה בא \u0003לרבות כל דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003בעלים\u0004 שחייב עליו בעל הבור אם נפל לתוכו. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אפילו כלים ואדם נמי\u0004 \u0005[גם כן]\u0006 וקשה לכל הדעות!","ומשיבים: משום כך \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"שור\"\u0004 — \u0003ולא אדם, \"חמור\"\u0004 — \u0003ולא כלים.\u0004 ושואלים: \u0003ולר' יהודה דקא מרבי להו\u0004 \u0005[שמרבה אותם]\u0006 את ה\u0003כלים,\u0004 וסבור שחייבים גם על נזקי כלים בבור, \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה שנאמר \u0003\"שור\"\u0004 — \u0003ממעט ביה\u0004 \u0005[בו]\u0006 \u0003אדם\u0004 שאין חייבים עליו, \u0003אלא \"חמור\" מאי\u0004 \u0005[מה]\u0006 \u0003ממעט\u0004 הוא \u0003ביה\u0004 \u0005[בו]?\u0006 שהרי אינו לומד מן המלה \"חמור\" למעט כלים, ומה הלכה מלמדנו?","\u0003אלא אמר רבא: \"חמור\"\u0004 האמור בדיני \u0003בור ל\u0004דעת \u0003ר' יהודה, ו\"שה\"\u0004 האמור בדיני \u0003אבידה\u0004 (דברים כב, א–ג) \u0003לדברי הכל קשיא\u0004 \u0005[קשה],\u0006 שאין לחכמים הסבר לשם מה נכתבו.","שנינו במשנה: \u0003נפל לתוכו,\u0004 לתוך הבור, \u0003שור חרש שוטה וקטן\u0004 — \u0003חייב.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שור חרש שוטה וקטן\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שהוא לשון סמיכות, וכוונתו \u0003שור של חרש, שור של שוטה, שור של קטן,\u0004 \u0003הא\u0004 \u0005[הרי]\u0006 אם כן נבין מכאן כי אם נפל לבור \u0003שור של פקח\u0004 יהיה בעל הבור \u0003פטור?!\u0004 מה טעם פטור זה?","\u0003אמר ר' יוחנן:\u0004 יש לפרש \u0003שור שהוא חרש, שור שהוא שוטה, שור שהוא קטן\u0004."],["ושואלים, ומכאן יש לדייק: \u0003הא\u0004 \u0005[אבל]\u0006 \u0003שור שהוא פקח\u0004 שנפל לבור — \u0003פטור?\u0004","\u0003אמר ר' ירמיה:\u0004 בלשון \"\u0003לא מבעיא\u0004\" \u0005[נצרכה]\u0006 \u0003קאמר\u0004 \u0005[אמר\u0006 במשנה], וכך יש להבין: \u0003לא מבעיא\u0004 \u0005[נצרכה]\u0006 לומר שאם נפל לשם \u0003שור שהוא פקח\u0004 ש\u0003חייב, אבל\u0004 אם נפל \u0003שור\u0004 שהוא \u0003חרש שוטה וקטן, אימא\u0004 \u0005[אמור]\u0006 שלא מפני הבור בלבד נפל, אלא \u0003חרשותו גרמה לו, קטנותו גרמה לו, וליפטר\u0004 \u0005[ושייפטר]\u0006 איפוא בעל הבור, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שחייב גם על אלה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא לרבינא, והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נפל לתוכו בר דעת\u0004 — \u0003פטור. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה ל\u0003שור בר דעת? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004 הכוונה היא ל\u0003אדם.\u0004 והקשה לו: \u0003אלא מעתה,\u0004 אם כך אתה מפרש, תדייק איפוא: \u0003אדם בן דעת הוא\u0004 ש\u0003פטור\u0004 בעל הבור על נזקיו, \u0003הא לאו\u0004 \u0005[הרי מכאן, אם לא]\u0006 \u0003בן דעת הוא\u0004 נאמר ש\u0003חייב\u0004 עליו? והרי \u0003\"שור\"\u0004 — \u0003ולא אדם כתיב\u0004 \u0005[נאמר],\u0006 שכך פירשנו את הכתוב!","אמר לו רבא: \u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בן דעת\"\u0004 — כוונתו \u0003מין בן דעת,\u0004 כלומר, כל מין האדם, שיש בו דעת — אין חייבים עליו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אחא: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא במפורש\u0005]:\u0006 \u0003נפל לתוכו שור בן דעת\u0004 — \u0003פטור!\u0004","\u0003אלא אמר רבא:\u0004 יש לדחות את הסברו של ר' ירמיה, ולפרש כפשוטו: \u0003שור והוא חרש, שור והוא שוטה, שור והוא קטן דוקא\u0004 חייב, \u0003אבל שור והוא פקח\u0004 — \u0003פטור, מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003דבעי ליה עיוני ומיזל\u0004 \u0005[שהיה צריך לו להתבונן וללכת]\u0006 ואם לא התבונן — השור גרם לעצמו. ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 בור ש\u0003נפל לתוכו שור חרש שוטה וקטן וסומא\u0004 (עיוור) \u0003ו\u0004כן שור שהיה \u0003מהלך בלילה\u0004 ואינו יכול לראות — \u0003חייב\u0004 בעל הבור. היה השור \u0003פקח ומהלך ביום\u0004 — \u0003פטור,\u0004 לפי שהיה השור צריך להסתכל.","\u0003אחד שור ואחד כל בהמה\u0004 דינם שווה \u0003ל\u0004ענין חיוב נזקים ב\u0003נפילת הבור, ול\u0004ענין \u0003הפרשת\u0004 (הרחקת) \u0003הר סיני\u0004 שאסור היה לכל בהמה לעלות בהר בזמן מתן תורה, \u0003ולתשלומי כפל\u0004 של גנב, \u0003ול\u0004חובת \u0003השבת אבידה, ול\u0004ענין \u0003פריקה\u0004 של משאו מעליו, ולענין \u0003חסימה\u0004 שאסור לחסום אותו בדישו, \u0003ל\u0004ענין איסור הרבעה וחרישה בו ב\u0003כלאים, ול\u0004ענין איסור מלאכה בו ב\u0003שבת,\u0004","\u0003וכן חיה ועוף כיוצא בהן,\u0004 שכל הדינים הללו שייכים בהם. \u0003אם כן למה נאמר\u0004 בתורה בכל אלה \u0003\"שור\" או \"חמור\"? אלא שדבר הכתוב בהווה,\u0004 בדברים המצויים, ומהם נלמד גם לגבי דברים אחרים.","ומפרשים מניין לנו כל ההלכות השנויות במשנה — דין אחד לשור ולכל בהמה \u0003ל\u0004ענין \u0003נפילת הבור\u0004 מניין לנו? — \u0003\"כסף ישיב לבעליו\"\u0004 (שמות כא, לד) \u0003כתיב\u0004 \u0005[נאמר],\u0006 ומשמעו: \u0003כל\u0004 בעל חיים \u0003דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003בעלים, כדאמרן\u0004 \u0005[כפי שאמרנו]\u0006 בעמוד הקודם. \u0003ל\u0004ענין \u0003הפרשת הר סיני\u0004 למדים מן האמור \u0003\"אם בהמה אם איש לא יחיה\"\u0004 (שמות יט, יג) \u0003ו\u0004\u0003אף חיה בכלל בהמה הויא\u0004 \u0005[היא],\u0006 כמפורש בתורה (ראה דברים יד, ד–ה), ו\u0003\"אם\"\u0004 (\"אם בהמה\") שנאמר הרי זה בא \u0003לרבות את העופות. \u0004","\u0003ל\u0004ענין \u0003תשלומי כפל\u0004 — \u0003כדאמרינן\u0004 \u0005[כפי שאמרנו]\u0006 במדרש ההלכה: \u0003\"על כל דבר פשע\"\u0004 (שמות כב, ח) הרי זה \u0003כלל כל דבר פשיעה\u0004 — כל דבר שאפשר לפשוע בו. \u0003ל\u0004ענין \u0003השבת אבידה\u0004 הרי נאמר בכתוב באופן כללי \u0003\"לכל אבדת אחיך\"\u0004 (דברים כב, ג). \u0003ל\u0004ענין \u0003פריקה\u0004 — \u0003יליף\u0004 \u0005[לומד]\u0006 בגזירה שווה \u0003\"חמור\" \"חמור\" משבת,\u0004 שכשם שבדיני שבת נזכר \"חמור\" (\"לא תעשה כל מלאכה... וחמורך\". דברים ה, יד) והכוונה לכל בהמה — אף דין פריקה (\"כי תראה חמור שונאך רובץ תחת משאו וחדלת מעזוב לו עזוב תעזוב עמו\". שמות כג, ה) בכל בהמה.","וכן \u0003ל\u0004ענין \u0003חסימה\u0004 (\"לא תחסום שור בדישו\". שמות כה, ד) — \u0003יליף\u0004 \u0005[לומד]\u0006 הוא בגזירה שווה \u0003\"שור\" \"שור\" משבת\u0004 (\"ויום השביעי שבת... ושורך\". דברים ה, יד).","\u0003ל\u0004ענין \u0003כלאים, אי\u0004 \u0005[אם]\u0006 מדובר כאן באיסור \u0003כלאים\u0004 של \u0003חרישה\u0004 (\"לא תחרוש בשור ובחמור יחדיו\". שמות כב, י) — \u0003יליף\u0004 \u0005[לומד]\u0006 בגזירה שווה \u0003\"שור\" \"שור\" משבת,\u0004","\u0003אי\u0004 \u0005[אם]\u0006 מדובר ב\u0003כלאים\u0004 שב\u0003הרבעה\u0004 (\"בהמתך לא תרביע כלאים\", ויקרא יט, יט) — \u0003יליף\u0004 \u0005[לומד]\u0006 הוא גזירה שווה של המילים \u0003\"בהמתך\" \"בהמתך\" משבת\u0004 (\"ויום השביעי שבת... ובהמתך\". שמות כ, י).","ושואלים: \u0003וגבי\u0004 \u0005[ואצל]\u0006 \u0003שבת\u0004 עצמה \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 הלכה זו ש\"שור\" ו\"חמור\" משמעם כל מיני חיה ובהמה? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' ישמעאל: בדברות הראשונות\u0004 שבספר שמות \u0003נאמר: \"עבדך ואמתך ובהמתך\"\u0004 (שמות כ, י) \u0003ובדברות האחרונות\u0004 בספר דברים \u0003נאמר: \"ושורך וחמרך וכל בהמתך\"\u0004 (דברים ה, יד), \u0003והלא שור וחמור בכלל כל בהמה היו, ולמה יצאו\u0004 לפרטם במיוחד? — \u0003לומר לך: מה שור וחמור האמור כאן\u0004 גם \u0003חיה ועוף כיוצא בהן, אף כל\u0004 מקום שנאמרו שור וחמור, \u0003חיה ועוף כיוצא בהן.\u0004","ומקשים: \u0003אימא\u0004 \u0005[אמור]\u0006 ופרש כך: לשון \u0003\"בהמה\"\u0004 שנאמר ב\u0003דברות הראשונות\u0004 — \u0003כלל\u0004 הוא, \u0003\"שורך וחמרך\"\u0004 של \u0003דברות האחרונות\u0004 — \u0003פרט,\u0004 והרי כאן \u0003כלל ופרט,\u0004 ולפי כללי מדרש ההלכה במקרה שכזה \u0003אין בכלל אלא מה שבפרט;\u0004 ובענייננו: \u0003שור וחמור\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003\"וכל בהמתך\"\u0004 שנאמר ב\u0003דברות האחרונות\u0004 לאחר \"שורך וחמורך\" הרי זה \u0003חזר וכלל,\u0004 ואם כן יש כאן \u0003כלל ופרט וכלל,\u0004 ולפי כללי מדרש ההלכה במקרה שכזה \u0003אי\u0004 (אין) \u0003אתה דן אלא כעין הפרט\u0004, ובענייננו: מה הפרט מפורש בעלי חיים — \u0003אף כל בעלי חיים.\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: \u0003מה הפרט מפורש\u0004 שור וחמור הם \u0003דבר שנבלתו מטמא במגע ובמשא, אף כל דבר שנבלתו מטמא במגע ובמשא, אבל עופות\u0004 — \u0003לא!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003אם כן, נכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003חד פרטא\u0004 \u0005[פרט אחד],\u0006 או \"שור\" או \"חמור\", ודי היה בכך. וכיון שכתבה שניים הרי זה ללמד דבר שאינו שווה לגמרי לשניהם, דהיינו עוף. ודוחים: זאת אינה תשובה, שכן \u0003הי נכתוב רחמנא\u0004 \u0005[איזה\u0006 מהם \u0005תכתוב התורה]\u0006 — אותו בלבד? \u0003אי כתב רחמנא\u0004 \u0005[אילו היתה כותבת התורה]\u0006 \u0003\"שור\"\u0004 בלבד \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 מה ש\u0003קרב לגבי מזבח\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 חייב בשביתה בשבת, ואולם זה \u0003שאינו קרב לגבי מזבח\u0004 — \u0003לא.\u0004 ולכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 גם \u0003\"חמור\",\u0004 שאף מה שאינו קרב על המזבח אסור במלאכה. \u0003ואי כתב רחמנא\u0004 \u0005[ואילו היתה כותבת התורה]\u0006 \u0003\"חמור\"\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 מה ש\u0003קדוש בבכורה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 ואולם זה \u0003שאין קדוש בבכורה\u0004 — \u0003לא,\u0004 ולכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 גם \u0003\"שור\".\u0004 ואם כן, אין ייתור בפרטים אלה, וכל אחד מלמד לעניינו. וחזרה השאלה: מדוע לא נדייק באופן שאין האיסור כולל עופות?","\u0003אלא\u0004 יש לומר כי \u0003\"וכל בהמתך\"\u0004 לשון \u0003ריבויא\u0004 \u0005[ריבוי]\u0006 \u0003הוא,\u0004 המרבה ומוסיף כל דבר הדומה בצד מסויים לפרט, אף שאינו ממש כעין הפרט.","ושואלים: \u0003וכל היכא דכתב רחמנא\u0004 \u0005[מקום שכתבה התורה]\u0006 \u0003\"כל\"\u0004 לשון \u0003ריבויא\u0004 \u0005[ריבוי]\u0006 \u0003הוא? והא גבי\u0004 \u0005[והרי אצל]\u0006 \u0003מעשר, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"כל\", ו\u0004בכל זאת \u0003קא דרשינן ליה\u0004 \u0005[ואנו דורשים אותו]\u0006 \u0003בכלל ופרט\u0004 ולא בריבוי,","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"ונתתה הכסף בכל אשר תאוה נפשך\"\u0004 (דברים יד, כו) — הרי זה \u0003כלל, \"בבקר ובצאן וביין ובשכר\"\u0004 (דברים יד, כו) — הרי זה \u0003פרט,\u0004 \u0003\"ובכל אשר תשאלך נפשך\"\u0004 (דברים יד, כו) — \u0003חזר וכלל,\u0004 נמצא שיש בכתוב","\u0003כלל ופרט וכלל,\u0004 ואז \u0003אי\u0004 (אין) \u0003אתה דן אלא כעין הפרט, מה הפרט מפורש\u0004 שכל אחד מאלה הוא \u0003פרי מפרי,\u0004 כלומר, דבר היוצא מדבר שיצא מדבר אחר, כגון יין ושיכר שעושים מן הפירות, וכן בעלי חיים, \u0003ו\u0004כולם הם \u0003גידולי קרקע,\u0004 כלומר, דבר הגדל או ניזון מן הקרקע, \u0003אף כל\u0004 דבר שהוא \u0003פרי מפרי וגידולי קרקע\u0004 בכלל זה. הרי שלמדים כאן רק בכלל ופרט, ואין למדים מ\"כל\" לריבוי!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 ועונים: יש לחלק, \u0003\"בכל\"\u0004 — לשון \u0003כללא\u0004 \u0005[כלל]\u0006 הוא, ואילו \u0003\"כל\"\u0004 (\"וכל בהמתך\") — לשון \u0003ריבויא\u0004 \u0005[ריבוי]\u0006 הוא. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 באופן אחר: לשון \u0003\"כל\" נמי כללא הוא\u0004 \u0005[גם כן\u0006 לשון \u0005כלל היא],\u0006 \u0003מיהו האי \"כל\" דהכא ריבויא הוא\u0004 \u0005[ואולם \"כל\" זה של כאן\u0006 לשון \u0005ריבוי היא],\u0006 שכן \u0003מדהוה ליה למכתב\u0004 \u0005[מ\u0006מה \u0005שהיה לו לכתוב]\u0006 \u0003\"ובהמתך\" כדכתיב\u0004 \u0005[כפי שנאמר]\u0006 \u0003בדברות הראשונות, וכתב \"וכל בהמתך\", שמע מינה ריבויא\u0004 \u0005[למד מכאן\u0006 שלשון \u0005ריבוי]\u0006 הוא, להוסיף ולרבות על הנאמר קודם.","ושואלים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003אמרת:\u0004 כי \u0003\"כל\"\u0004 לשון \u0003ריבויא\u0004 \u0005[ריבוי]\u0006 \u0003הוא,\u0004 אם כן \u0003\"בהמתך\"\u0004 שנאמר ב\u0003דברות הראשונות, ו\"שור\" ו\"חמור\"\u0004 שנאמרו ב\u0003דברות האחרונות למה לי?\u0004 שהרי \"וכל בהמתך\" כולל את כל מיני בעלי חיים!","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 יש בכך צורך, מה שנאמר \u0003\"שור\"\u0004 — הרי זה בא \u0003לאגמורי\u0004 \u0005[ללמד]\u0006 בגזירה שווה \u0003\"שור\" \"שור\" ל\u0004ענין \u0003חסימה, ו\u0004מה שנאמר","\u0003\"חמור\"\u0004 — הרי זה בא \u0003לאגמורי\u0004 \u0005[ללמד]\u0006 בגזירה שווה \u0003\"חמור\" \"חמור\" ל\u0004ענין \u0003פריקה,\u0004","\u0003\"בהמתך\"\u0004 — \u0003לאגמורי\u0004 \u0005[ללמד]\u0006 גזירה שווה \u0003\"בהמתך\" \"בהמתך\" ל\u0004ענין איסור \u0003כלאים.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמייתור זה למדים לענין כלאים, \u0003אפילו אדם ליתסר\u0004 \u0005[ייאסר]\u0006 לחרוש ביחד עם שור או בעל חיים אחר, \u0003אלמה תנן\u0004 \u0005[\u0006ו\u0005מדוע שנינו\u0006 במשנה\u0005]\u0006 במפורש: \u0003אדם מותר עם כולן לחרוש ולמשוך,\u0004 משמע שאיסור חרישה בכלאים חל רק על בהמות, ולא על בני אדם!","\u0003אמר רב פפא: פפונאי ידעי טעמא דהא מילתא\u0004 \u0005[חכמי העיר\u0006 \u0005פפוניא יודעים\u0006 את \u0005טעם דבר זה],\u0006 \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 חכמים אלה שרמזנו להם — \u0003רב אחא בר יעקב\u0004 שהיה בן פפוניא: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"\u0004לא תעשה כל מלאכה אתה ובנך ובתך ועבדך ואמתך ושורך וחמורך וכל בהמתך וגרך אשר בשעריך \u0003למען ינוח עבדך ואמתך כמוך\"\u0004 (דברים ה, יד), ללמדנו: \u0003להנחה\u0004 (למנוחה) \u0003הקשתיו\u0004 (השוויתי אותו), שלענין זה יש דין אחד גם לאדם וגם לבהמה, \u0003ולא לדבר אחר.\u0004","כיון שהוזכר קודם לכן לימוד הנובע מהשוואת הכתוב בלוחות ראשונים ואחרונים מביאים דבר אחר הנוגע לנושא זה, \u0003שאל ר' חנינא בן עגיל את ר' חייא בר אבא: מפני מה בדברות הראשונות לא נאמר בהם\u0004 המלה \u0003\"טוב\", ובדברות האחרונות\u0004"],["\u0003נאמר בהם\u0004 המלה \u0003\"טוב\",\u0004 כאמור במצוות כיבוד אב ואם (\"ולמען ייטב לך\". דברים ה, טז)? \u0003אמר לו\u0004 ר' חייא בר אבא: \u0003עד שאתה שואלני למה נאמר בהם \"טוב\", שאלני אם נאמר בהן \"טוב\" אם לאו\u0004 \u0005[לא],\u0006 \u0003שאיני יודע אם נאמר בהן \"טוב\" אם לאו,\u0004 כלומר, אינני בקי כל כך בתורה לזכור דברים אלה, \u0003כלך\u0004 (לך) \u0003אצל ר' תנחום בר חנילאי, שהיה רגיל\u0004 (מצוי) ללמוד \u0003אצל ר' יהושע בן לוי שהיה בקי באגדה,\u0004 אפשר ששמע ממנו בענין זה ויוכל להשיבך.","\u0003אזל לגביה\u0004 \u0005[הלך אצלו]\u0006 ושאלו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' תנחום: \u0003ממנו,\u0004 מר' יהושע בן לוי עצמו, \u0003לא שמעתי\u0004 דבר בענין זה, \u0003אלא כך אמר לי שמואל בר נחום אחי אמו של רב אחא בר' חנינא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003אבי אמו של רב אחי בר' חנינא,\u0004 שלא נאמר \"טוב\" בדברות הראשונות \u0003הואיל וסופן\u0004 של הלוחות הראשונים היה \u0003להשתבר\u0004 משעשו ישראל את העגל.","ושואלים: \u0003וכי\u0004 (ואם) \u0003סופן להשתבר מאי הוי\u0004 \u0005[מה בכך]\u0006 אם היה נאמר בדברות הראשונות \"טוב\"? \u0003אמר רב אשי:\u0004 אילו היה כך \u0003חס ושלום פסקה\u0004 (פוסקת היתה) \u0003טובה מישראל\u0004 לאחר שנשברו, ולכן לא נאמר בהם \"טוב\" אלא בדברות האחרונות, שנכתבו בתורה לאחר פרשת שבירת הלוחות, כדי שלעולם יהיה טוב לישראל. כיוון שדיברנו בענין זה מביאים ענין דומה. \u0003אמר ר' יהושע: הרואה\u0004 אות \u0003טי\"ת בחלומו\u0004 — \u0003סימן יפה\u0004 הוא \u0003לו.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דכתיב\u0004 \u0005[שכתוב]\u0006 בתורה \u0003\"טוב\"\u0004 ומלה זו מתחילה באות טי\"ת, \u0003אימא\u0004 \u0005[אמור]\u0006 שמה שרואה הוא רמז למה שכתוב \u0003\"וטאטאתיה במטאטא השמד\"\u0004 (ישעיהו יד, כג) שיש בו כמה טי\"תים, והוא ענין של פורענות! ומשיבים: ברואה בחלומו \u0003חד טי\"ת קאמרינן\u0004 \u0005[טי\"ת אחד אנו אומרים]\u0006 שיש בכך סימן טוב, ובפסוק זה של פורענות יש רבים.","ומקשים עוד: אף להסבר זה \u0003אימא\u0004 \u0005[אמור]\u0006 שהרואה טי\"ת אחת בחלומו הוא רמז למה שנאמר \u0003\"טמאתה בשוליה\"\u0004 (איכה א, ט)! ומשיבים: ברואה בחלום יחד עם האות \u0003טי\"ת\u0004 גם את האות \u0003בי\"ת קאמרינן\u0004 \u0005[אנו אומרים]\u0006 שהוא סימן יפה לו. ומקשים: אף בזה \u0003אימא\u0004 \u0005[אמור]\u0006 שיש בזה רמז למה שנאמר \u0003\"טבעו בארץ שעריה\"\u0004 (איכה ב, ט)!","","\u0003אלא\u0004 טעם הדבר שהרואה טי\"ת בחלום סימן יפה הוא לו, אינו מעצם העובדה שהוא פותח את המלה \"טוב\", אלא \u0003הואיל ופתח בו הכתוב לטובה תחילה\u0004 (בראשונה), \u0003שמ\"בראשית\"\u0004 (בראשית א, א) \u0003עד\u0004 לפסוק \u0003\"וירא אלהים את האור\u0004 כי טוב\u0003\"\u0004 (בראשית א, ה) \u0003לא כתיב\u0004 \u0005[נאמרה]\u0006 האות טי\"ת, ופעם ראשונה שנמצאת אות זו היא במלה \"טוב\". ובדומה לזה \u0003אמר ר' יהושע בן לוי: הרואה \"הספד\" בחלומו\u0004 הרי זה רמז ש\u0003חסו עליו מן השמים ופדאוהו,\u0004 שאינו צריך להספד זה. ומעירים: \u0003הני מילי\u0004 \u0005[דברים אלו]\u0006 אמורים דווקא כשרואה את המלה \"הספד\" \u0003בכתבא\u0004 \u0005[בכתב].\u0006","","נאמר במשנה: \u0003וכן חיה ועוף כיוצא בהן וכו'. אמר ריש לקיש: כאן שנה רבי,\u0004 כלומר, בהלכות אלו, שחיה ועוף דינם כבהמה לכל העניינים שמנינו במשנה, ובכללם כלאים, כלולה אותה הלכה הכתובה בתוספתא כי \u0003תרנגול טווס ופסיוני\u0004 נחשבים \u0003כלאים זה בזה,\u0004 שדין כלאיים חל גם על עופות.","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006, מובן מאליו\u0005]\u0006 שכן הוא, ומה החידוש באלה דווקא? \u0003אמר רב חביבא: משום דרבו בהדי הדדי\u0004 \u0005[ש\u0006הם \u0005גדלים יחד],\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מין חד\u0004 \u0005[אחד]\u0006 \u0003הוא\u0004 ואינם כלאים זה בזה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהם מינים נבדלים, וכלאים זה בזה.","ואגב הלכות אלה בכלאי עופות \u0003אמר שמואל: אווז ואווז הבר\u0004 הרי הם \u0003כלאים זה בזה\u0004 ואין הם נחשבים למין אחד. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא בר רב חנן: מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דהאי אריך קועיה והאי זוטר קועיה\u0004 \u0005[שזה ארוך צווארו וזה קטן צווארו],\u0006 \u0003אלא מעתה, גמלא פרסא וגמלא טייעא\u0004 \u0005[גמל פרסי וגמל ערבי],\u0006 \u0003דהאי אלים קועיה והאי קטין קועיה\u0004 \u0005[שזה עבה צווארו וזה דק צווארו],\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר \u0003דהוו\u0004 \u0005[שהריהם]\u0006 \u0003כלאים זה בזה?\u0004 הלא ברור לנו שהם מין אחד, שיש בו שתי צורות!","\u0003אלא אמר אביי:\u0004 לא זה הטעם, אלא יש הבדל אחר ביניהם במין הזכר שבהם: \u0003זה,\u0004 אווז הבר — \u0003ביציו\u0004 (אשכיו) \u0003מבחוץ,\u0004 שניכרות הן, \u0003וזה,\u0004 האווז — \u0003ביציו מבפנים. רב פפא אמר:\u0004 יש הבדל אחר ביניהם במין הנקיבה שבהם: \u0003הא טעונה חדא ביעתא בשיחלא\u0004 \u0005[זו,\u0006 אווזת בר \u0005טוענת\u0006 רק \u0005ביצה אחת בשחלה\u0006 של הביצים\u0005]\u0006 וחוזרת וטוענת ביצה אחרת לאחר זמן, \u0003והא\u0004 \u0005[וזו]\u0006 — \u0003טעונה כמה ביעתא בשיחלא\u0004 \u0005[ביצים בשחלה]\u0006 ולכן רואים שאינם מין אחד. ועוד בענייני כלאים \u0003אמר ר' ירמיה אמר ריש לקיש: המרביע שני מינים\u0004 של בעלי חיים \u0003שבים\u0004 — \u0003לוקה\u0004 משום איסור כלאים. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם],\u0006 כלומר, מה הרמז לדבר במקרא? \u0003אמר רב אדא בר אהבה משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה \u0003\"למינהו\" \"למינהו\" מ\u0004חיות שב\u0003יבשה\u0004 (ראה בראשית א פסוקים כא,כה), שכשם שבחיות היבשה כתוב \"למינהו\" ואסורים בהם כלאים, כן הוא גם בחיות שבים.","","\u0003בעי\u0004 \u0005[שאל]\u0006 החכם \u0003רחבה: המנהיג\u0004 (מוביל) עגלה הרתומה ביחד, \u0003בעיזא\u0004 \u0005[בעז]\u0006 ביבשה \u0003ושיבוטא\u0004 (מין דג) במים, \u0003מהו\u0004 הדין? האם יש בהם משום איסור כלאים כמו בשור וחמור, שאסור לחרוש בהם יחד, או לא? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003כיון דעיזא לא נחית\u0004 \u0005[שהעז אינה יורדת]\u0006 \u0003בים, ושיבוטא לא סליק\u0004 \u0005[עולה]\u0006 \u0003ליבשה\u0004 — \u0003לא כלום עביד\u0004 \u0005[\u0006הוא \u0005עושה]\u0006 בזה שמנהיג אותם ביחד, שהרי אינם עובדים יחד. \u0003או דלמא השתא מיהת קא מנהיג\u0004 \u0005[שמא עכשיו על כל פנים הוא נוהג]\u0006 בשניהם יחד, ובזה תלוי האיסור?","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא:\u0004 מה מקום יש לשאלה? \u0003אלא מעתה\u0004 לפי זה תאמר גם כן שאם \u0003חיבר\u0004 אדם \u0003חטה ושעורה בידו\u0004 יחד, \u0003וזרע\u0004 את ה\u0003חטה בארץ\u0004 ישראל, \u0003ו\u0004את ה\u0003שעורה בחוצה לארץ\u0004 שאינו אסור בכלאי זרעים, למרות שהם מקומות סמוכים זה לזה, \u0003הכי נמי דמחייב\u0004 \u0005[ככה גם כן יהיה חייב]?\u0006 אלא ודאי כיון שהארץ וחוץ לארץ הם שני תחומים נבדלים אין אנו אומרים שיש בכך כלאים, ואף ים ויבשה כן.","\u0003אמרי\u0004 \u0005[אומרים]\u0006 כתשובה לכך: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 לענין זריעת כלאים, \u0003ארץ\u0004 — \u0003מקום חיובא\u0004 \u0005[חיוב]\u0006 של כלאים הוא, \u0003חוצה לארץ\u0004 — \u0003לא מקום חיובא\u0004 \u0005[חיוב]\u0006 כלאים, ולכן אף שהם סמוכים זה לזה לא חל כלל האיסור. אבל \u0003הכא\u0004 \u0005[כאן]\u0006 בהנהגה בים או ביבשה \u0003אידי ואידי חיובא\u0004 \u0005[זה וזה חיוב]\u0006 \u0003הוא,\u0004",""],["\u0003הכונס צאן לדיר ונעל בפניה כראוי, ויצאה והזיקה\u0004 בשדה אחר על ידי אכילת פירות או רמיסה — הרי זה \u0003פטור,\u0004 שהרי בעל הצאן עשה מה שהיה עליו לעשות. \u0003לא נעל בפניה כראוי, ויצאה והזיקה\u0004 — \u0003חייב,\u0004 שרשלנותו היא שגרמה.","נעל כראוי ו\u0003נפרצה\u0004 דלת הדיר \u0003בלילה, או שפרצוה לסטים, ויצאה והזיקה\u0004 בשן או ברגל — \u0003פטור\u0004 בעל הצאן. אם \u0003הוציאוה לסטים\u0004 בעצמם מן הדיר, ואחר כך הלכה הבהמה והזיקה — הרי \u0003לסטים חייבין\u0004 על הנזק שגרמה.","\u0003הניחה\u0004 את הבהמה \u0003בחמה\u0004 וגרם לה צער בכך, \u0003או שמסרה ל\u0004שמירתו של \u0003חרש שוטה וקטן,\u0004 שאינם בני דעת לשומרה כראוי, \u0003ויצאה והזיקה\u0004 — \u0003חייב,\u0004 משום שגם כאן רשלנותו היא שגרמה לנזק.","\u0003מסרה לרועה\u0004 לשמור — \u0003נכנס הרועה תחתיו,\u0004 שעל הרועה מוטלת מעתה אחריות הנזקים.","\u0003נפלה\u0004 הבהמה באונס \u0003לגינה ונהנית\u0004 שם מפירות הגינה — \u0003משלמת,\u0004 כלומר, בעליה משלמים רק על \u0003מה שנהנית,\u0004 ולא על כל הנזקים שגרמה. ואולם אם \u0003ירדה\u0004 הבהמה \u0003כדרכה\u0004 לגינה \u0003והזיקה\u0004 בגינה — \u0003משלמת מה שהזיקה\u0004 גם אם היא עצמה לא נהנתה מכך. ומסבירים: \u0003כיצד משלמת מה שהזיקה,\u0004 כלומר, כיצד מעריכים את הנזקים? \u0003שמין\u0004 (מעריכים) שטח של \u0003בית סאה\u0004 שניזוק \u0003באותה שדה כמה היתה יפה\u0004 (שווה) אותו שטח לפני שהזיקה הבהמה \u0003וכמה היא יפה\u0004 עכשיו. שאין מעריכים את הנזקים לעצמם, כמה היו שווים הפירות שאכלה לעצמם, ואף לא את ירידת ערך הקרקע המסויימת עליה היו הפירות, שהוא שיעור נזק גדול יותר למזיק, אלא מעריכים את הפחת של אותה ערוגה ביחס לשטח גדול יותר.","\u0003ר' שמעון אומר:\u0004 דבר זה אמור כשאכלה פירות או תבואה שאינם גמורים, אבל אם \u0003אכלה פירות גמורים\u0004 — \u0003משלמת פירות גמורים\u0004 כפי הנזק. \u0003אם\u0004 אכלה \u0003סאה\u0004 — משלמת עבור \u0003סאה, אם\u0004 אכלה \u0003סאתים\u0004 — משלמת עבור \u0003סאתים.\u0004","שנינו בתחילת המשנה שנעל בפניה כראוי. ובהגדרת נעילה כראוי \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו\u0004 נעילה \u0003כראוי, ואיזהו שלא כראוי?\u0004 נעל \u0003דלת\u0004 באופן \u0003שיכולה לעמוד ברוח מצויה\u0004 בלא ליפול — \u0003זהו\u0004 נקרא \u0003כראוי.\u0004 נעל דלת באופן \u0003שאינה יכולה לעמוד ברוח מצויה\u0004 — \u0003זהו שלא כראוי.\u0004","על בסיס הבנה זו של המשנה, שנעילת דלת שעומדת ברוח מצויה נחשבת שמירה כראוי, \u0003אמר ר' מני בר פטיש: מאן\u0004 \u0005[מי הוא]\u0006 ה\u0003תנא\u0004 של משנתנו הסבור לענין בעל חיים \u0003מועד דסגי ליה\u0004 \u0005[שדי לו]\u0006 \u0003בשמירה פחותה\u0004 (כלשהי), שהרי לענין שן ורגל, בהן עוסקת משנתנו, כל בהמה מועדת — שיטת \u0003ר' יהודה היא, דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 שור ש\u0003קשרו בעליו במוסירה\u0004 (רצועה) \u0003ונעל לפניו כראוי, ויצא\u0004 השור \u0003והזיק, אחד תם ואחד מועד\u0004 — \u0003חייב,\u0004 שלא די בשמירה זו, אלו \u0003דברי ר' מאיר.\u0004","\u0003ר' יהודה אומר: תם\u0004 — \u0003חייב\u0004 אף ששמר כראוי, שגזירת הכתוב שחייב על מחצית נזקיו. \u0003מועד\u0004 — \u0003פטור, שנאמר\u0004 במועד: \u0003\"ולא ישמרנו בעליו\"\u0004 (שמות כא, לו), \u0003ושמור הוא זה. ר' אליעזר אומר: אין לו שמירה\u0004 כלל \u0003אלא סכין,\u0004 כלומר כל עוד לא שחטו אינו נחשב לשמור כראוי. משמע שרק ר' יהודה סבור ששמירה כלשהי (\"כראוי\") מועילה כדי לפטור את בעל הבהמה המועדת.","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו היא כשיטת \u0003ר' מאיר\u0004 שמחייב בשור מועד בשמירה כזו, \u0003שאני\u0004 \u0005[שונים]\u0006 דיני \u0003שן ורגל\u0004 אף שהם מועדים, ממועד של קרן, ש\u0003התורה מיעטה בשמירתן\u0004 ולא חייבה לשומרם שמירה מעולה. ש\u0003אמר ר' אלעזר\u0004 (האמורא), \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 כי \u0003במתניתא תנא\u0004 \u0005[בברייתא שנוייה]\u0006 הלכה זו: \u0003ארבעה דברים התורה מיעטה בשמירתן,\u0004 שלא חייבה עליהם שמירה מעולה, \u0003ואלו הן: בור ואש, שן ורגל.\u0004","\u0003בור\u0004 מניין — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"\u0004ו\u0003כי יפתח איש בור או כי יכרה איש בר ולא יכסנו\"\u0004 (שמות כא, לג), למדנו מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003כסהו\u0004 — \u0003פטור,\u0004 ודי בכך, ואין צריך למלא ולסתום את הבור לגמרי.","\u0003אש\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בה: \u0003\"שלם ישלם המבער את הבערה\"\u0004 (שמות כב, ה), וכוונתו: \u0003עד דעביד\u0004 \u0005[שעושה]\u0006 \u0003כעין\u0004 (כמו) \u0003\"מבעיר\",\u0004 שאינו חייב כשיוצאת אש מרשותו ומזיקה אלא כשהתרשל בשמירת האש.","\u0003שן\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בה: \u0003\"ובער בשדה אחר\"\u0004 (שמות, כב ד), וכוונתו: שאינו חייב אלא \u0003עד דעביד\u0004 \u0005[שעושה]\u0006 \u0003כעין \"ובער\",\u0004 שהוא עצמו גורם ברשלנותו לכך.","וכן ב\u0003רגל\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בה \u0003\"ושלח\"\u0004 (שמות כב, ד), וכוונתו: \u0003עד דעביד\u0004 \u0005[שעושה]\u0006 \u0003כעין\u0004 \u0003\"ושלח\".\u0004","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"ושלח\"\u0004 — \u0003זה הרגל, וכן הוא אומר \"משלחי רגל השור והחמור\"\u0004 (ישעיהו לב, כ). \u0003\"ובער\"\u0004 — \u0003זה השן, וכן הוא אומר: \"כאשר יבער הגלל עד תמו\"\u0004 (מלכים א יד, י).","ומכאן נדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003דעביד\u0004 \u0005[שעושה\u0006 מעשה\u0005]\u0006 \u0003כעין \"ושלח\" \"ובער\",\u0004 שהוא נוהג ברשלנות יתירה מתחייב בנזקים, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא עביד\u0004 \u0005[עושה]\u0006 כן, אף אם שמר שמירה פחותה — \u0003לא\u0004 מתחייב.","\u0003אמר רבה: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 באופן זה, \u0003דקתני\u0004 \u0005[ששנה]\u0006 במשנה דווקא \u0003\"צאן\".\u0004 ויש מקום לשאול: \u0003מכדי\u0004 \u0005[הואיל]\u0006 ו\u0003בשור קא עסקינן ואתי\u0004 \u0005[עוסקים אנו ובאים]\u0006 בכל המשניות הקודמות, \u0003ניתני\u0004 \u0005[שישנה]\u0006 אף במשנתנו \u0003שור, מאי שנא דקתני\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 משנתנו זו \u0005ששנה]\u0006 בה דווקא \u0003\"צאן\". לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003התורה מיעטה בשמירתן\u0004 של אלו דווקא, שן ורגל, המצויות בצאן, ולא של שור שנגח? ונמצא שמשנתנו מדוייקת כשיטתו של ר' מאיר, הסבור שדווקא בשן ורגל די בשמירה פחותה אבל בשור מועד אין די בשמירה פחותה.","ומשיבים: \u0003לאו\u0004 \u0005[לא],\u0006 טעם הדבר שמדובר במשנה, העוסקת בשמירה פחותה, דווקא בצאן, הוא \u0003משום\u0004 ש\u0003כאן\u0004 בצאן \u0003קרן לא כתיבא\u0004 \u0005[נאמרה]\u0006 \u0003בה,\u0004 אלא רק \u0003שן ורגל הוא דכתיב ביה\u0004 \u0005[שנאמרו בו],\u0006 ולכן כשעוסק במשנתנו בנזקי שן ורגל מזכיר דווקא צאן (ואף שגם בשור מועד די בשמירה פחותה, כר' יהודה). \u0003וקא משמע לן\u0004 \u0005[והשמיע לנו]\u0006 אגב כך ש\u0003שן ורגל\u0004 ש\u0003מועדין\u0004 מתחילתם \u0003הוא, שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003תניא\u0004 \u0005[שנוייה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יהושע: ארבעה דברים, העושה אותן דפטור מדיני אדם,\u0004 שאין בית דין יכול לחייב אותו על כך, \u0003וחייב בדיני שמים,\u0004 שיש עליו אחריות מוסרית על מה שעשה, וראוי לו שישלם. \u0003ואלו הן: הפורץ גדר בפני בהמת חבירו\u0004 ויצאה הבהמה וברחה, \u0003והכופף קמתו של חבירו בפני הדליקה, והשוכר עדי שקר להעיד,\u0004 \u0003והיודע עדות לחבירו ואינו מעיד לו.\u0004","ומעתה מסבירים את הברייתא הזו על כל הלכותיה, אחת לאחת: \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003הפורץ גדר בפני בהמת חבירו.\u0004 ודנים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בכותל בריא\u0004 (חזק) שלא היה נופל מעצמו והוא פרצו — \u0003בדיני אדם נמי ניחייב\u0004 \u0005[גם כן יתחייב]\u0006 לפחות על מה שהזיק ושבר את הכותל! \u0003אלא\u0004 מדובר כאן"],["\u0003בכותל רעוע\u0004 שבין כה וכה היה עומד ליפול וליהרס, ולכן בהריסת הכותל לא הפסידו דבר. וממשיכים לדון ברשימת הדברים שפטור עליהם בדיני אדם וחייב עליהם בדיני שמים.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003הכופף קמתו של חבירו בפני הדליקה\u0004 — פטור מדיני אדם וחייב בדיני שמים. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד היה הדבר בדיוק]?\u0006 \u0003אילימא דמטיא ליה\u0004 \u0005[אם תאמר\u0006 במקרה \u0005ש\u0006האש מגיעה אליה, אל הקמה\u0005]\u0006 \u0003ברוח מצויה\u0004 על ידי כפיפה זו, אם כן \u0003בדיני אדם נמי נחייב\u0004 \u0005[גם כן יתחייב]!\u0006 \u0003אלא\u0004 יש לומר \u0003דמטיא\u0004 \u0005[שמגיעה]\u0006 האש אל הקמה רק \u0003ברוח שאינה מצויה,\u0004 ולכן פטור מדיני אדם, אבל חייב בדיני שמים, שהרי סוף סוף הוא שגרם לה שתישרף.","\u0003ורב אשי אמר: טמון אתמר\u0004 \u0005[נאמר],\u0006 כלומר, אין מדובר כאן בכופף קמתו של חבירו לקרבה לדליקה, אלא בכופף קמתו של חבירו תחת דבר כלשהו ומטמין אותה, \u0003משום דשויה\u0004 \u0005[שעשה אותה]\u0006 על ידי כך \u0003טמון באש,\u0004 והלכה היא שבנזקי אש אין מחייבים על הטמון. ובא להשמיענו שאף שלא עשה לו נזק ישיר, מכל מקום כיון שטמן את הקמה גרם לו הפסד ממוני, כיון שעתה לא יוכל לגבות את נזקו ממי שהצית את האש, ויש לו אחריות כלפי שמים על כך.","ועוד \u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא: \u0003השוכר עדי שקר\u0004 פטור מדיני אדם וחייב בדיני שמים. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד היה הדבר בדיוק]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ששכר אותם \u0003לנפשיה\u0004 \u0005[ל\u0006צורך \u0005עצמו]\u0006 להוציא ממון מחבירו — \u0003ממונא בעי שלומי\u0004 \u0005[כסף צריך לשלם],\u0006 \u0003ובדיני אדם נמי ניחייב\u0004 \u0005[גם כן יתחייב],\u0006 שהרי הוציא כסף בעדותם של עדי שקר! \u0003אלא\u0004 מדובר ששכר \u0003לחבריה\u0004 \u0005[ל\u0006טובת חבירו] שבדיני אדם אין הניזק יכול לתבוע לא את בעל הדין — שלא שכרם, ולא את השוכר — שלא נהנה מכך בעצמו. ואולם בדיני שמים — חייב.","ועוד הלכה שנו בברייתא: \u0003והיודע עדות לחבירו ואינו מעיד לו\u0004 — חייב בדיני שמים לשלם לו מה שיכול היה להעיד לטובתו. ומבררים: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים\u0006 כאן]? \u0003אילימא בבי תרי\u0004 \u0005[אם תאמר בשניים,\u0006 בשני עדים\u0005]\u0006 שעל פי עדותם אפשר לחייבו ממון בבית דין — \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שחייב בדיני שמים, שהרי \u0003דאורייתא\u0004 \u0005[\u0006חיוב שמן התורה] \u0003הוא,\u0004 שהרי נאמר בעדות שכזו \u0003\"אם לוא יגיד ונשא עונו\"\u0004 (ויקרא ה, ב). ומה מחדש התנא בדבריו?","\u0003אלא\u0004 מדובר כאן \u0003בחד\u0004 \u0005[ב\u0006עד \u0005אחד]\u0006 שאין בעדותו כדי לחייב ממון, ולא בו דיברה תורה. ומכל מקום הואיל ויכול היה לחייב את זה שכנגדו שבועה, ואם לא היה הלה נשבע היה משלם — חייב בדיני שמים על שלא העיד.","ושואלים: \u0003ותו\u0004 \u0005[ועוד]\u0006 דברים שפטור בהם מדיני אדם וחייב בהם בדיני שמים \u0003ליכא\u0004 \u0005[אין]?\u0006 \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 עוד הלכות השנויות בברייתות (ו\u0003סימן\u0004 לכל ההלכות הללו: \u0003העושה בסם ושליח חבירו נשבר)\u0004 ששנינו: \u0003העושה מלאכה במי חטאת,\u0004 שהם מים המשמשים לטהרת טמא מת, שאם עשה בהם מלאכה פסל אותם. \u0003ו\u0004כן המשתמש \u0003בפרת חטאת,\u0004 בפרה אדומה שאסור שיעלה עליה עול, ואם השתמש בה — הפסיד לבעליה את הכסף הרב שהיה מקבל עבור פרה נדירה כזו — \u0003פטור מדיני אדם\u0004 כיון שההיזק שגרם איננו נזק הניכר לעין, \u0003וחייב בדיני שמים.\u0004","\u0003והאיכא\u0004 \u0005[והרי יש]\u0006 עוד הלכה כזו, ששנינו: \u0003הנותן סם המות בפני בהמת חבירו\u0004 ואכלה ומתה, כיון שעשתה זאת מעצמה ואין דרכה לאכול סם — \u0003פטור מדיני אדם וחייב בדיני שמים.\u0004","\u0003והאיכא\u0004 \u0005[והרי יש]\u0006 עוד מה ששנינו: \u0003השולח את הבערה\u0004 (אש) \u0003ביד חרש שוטה וקטן\u0004 וגרמו לנזק — \u0003פטור מדיני אדם וחייב בדיני שמים.\u0004","\u0003והאיכא\u0004 \u0005[והרי יש]\u0006 עוד מה ששנינו: \u0003המבעית\u0004 (מפחיד) \u0003את חבירו\u0004 בלא לנגוע בגופו וגרם לו פחד זה לנזק — \u0003פטור מדיני אדם וחייב בדיני שמים.\u0004","\u0003והאיכא\u0004 \u0005[והרי יש]\u0006 עוד מה ששנינו: \u0003נשברה כדו ברשות הרבים ולא סילקה,\u0004 או \u0003נפלה גמלו ולא העמידה, ר' מאיר מחייב\u0004 את בעל הכד והגמל בנזק שנגרם לאחרים על ידם, \u0003וחכמים אומרים: פטור בדיני אדם וחייב בדיני שמים.\u0004 הרי שיש עוד מקרים רבים של חיוב כזה!","ומשיבים: \u0003אין, מיהא איכא טובא\u0004 \u0005[כן, אכן יש הרבה]\u0006 מקרים אחרים, \u0003ו\u0004אולם \u0003הני אצטריכא ליה\u0004 \u0005[ואלה שמנה\u0006 ר' יהושע \u0005היה צריך אותם]\u0006 להודיענו, משום שיש בהם חידוש, כי \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שבאלה \u0003בדיני שמים נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ליחייב\u0004 \u0005[יתחייב],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שיש בכך על כל פנים חיוב בדיני שמים.","ומסבירים את הדברים: \u0003הפורץ גדר בפני בהמת חבירו, מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון\u0004 שממילא הגדר \u0003למסתריה קאי\u0004 \u0005[לסותרה\u0006 היא \u0005עומדת]\u0006 אם כן \u0003מה\u0004 כבר \u0003עביד\u0004 \u0005[עשה]?\u0006 ולכן \u0003בדיני שמים נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ליחייב\u0004 \u0005[יתחייב],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שחייב בדיני שמים.","וכן \u0003הכופף קמתו של חבירו נמי\u0004 \u0005[גם כן]\u0006 חידוש יש בדבר, שכן, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003לימא\u0004 \u0005[שיאמר]\u0006 הכופף: \u0003מי הוה ידענא דאתיא\u0004 \u0005[האם הייתי יודע שתבוא]\u0006 \u0003רוח שאינה מצויה\u0004 ותגרום לדליקה? \u0003ובדיני שמים\u0004 אם כן \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ליחייב\u0004 \u0005[יתחייב]\u0006 על כך, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שחייב.","\u0003ולרב אשי\u0004 ש\u0003אמר נמי\u0004 \u0005[גם כן]\u0006 \u0003טמון איתמר\u0004 \u0005[נאמר],\u0006 שמדובר במי שטמן את החפץ שנשרף, ופטר את המזיק מתשלום, יש צורך להשמיע הלכה זו, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שכך יאמר הטומן: \u0003אנא כסויי כסיתיה ניהלך\u0004 \u0005[אני\u0006 רק כיסיתי אותו את החפץ שנשרף בשבילך] ורציתי להציל את החפץ מפני האש, \u0003ובדיני שמים נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ליחייב\u0004 \u0005[יתחייב],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שחייב.","\u0003והשוכר עדי שקר נמי\u0004 \u0005[גם כן]\u0006 חידוש יש בדבר, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003לימא\u0004 \u0005[יאמר]\u0006 אותו אדם: מה אשם אני? הלא כלל הוא: \u0003דברי הרב ודברי התלמיד, דברי מי שומעין?\u0004 ואם אמנם אני הסתתי את העדים הללו למעשה שאינו הגון, הרי סוף סוף העדים הם שעברו עבירה, שהיו צריכים לשמוע בקולו של הקדוש ברוך הוא ולא בקולי, \u0003ובדיני שמים נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ליחייב\u0004 \u0005[יתחייב],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שחייב בדיני שמים.","\u0003ו\u0004עד אחד \u0003היודע עדות לחבירו ואינו מעיד לו נמי\u0004 \u0005[גם כן]\u0006 חידוש יש בדבר, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 יכול העד לטעון: \u0003מי יימר דכי הוה אתינא מסהדינא ליה הוה\u0004 \u0005[מי יאמר שאם הייתי בא\u0006 ומעיד לו היה] הנתבע \u0003מודה, דלמא הוה משתבע לשקרא\u0004 \u0005[שמא היה נשבע לשקר]\u0006 ונפטר, שהרי עד אחד יכול רק לחייב את זה שהוא מעיד כנגדו לשבועה, ונמצא שלא גרם לו כל הפסד בכך שלא העיד, \u0003ובדיני שמים נמי\u0004 \u0005[גם כן\u0006 \u0003לא ליחייב\u0004 \u0005[יתחייב],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שחייב בדיני שמים.","שנינו במשנה: אם \u0003נפרצה\u0004 הגדר \u0003בלילה, או שפרצוה לסטים\u0004 ויצאה והזיקה — פטור. \u0003אמר רבה:\u0004 מה ששנינו שאם נפרצה בלילה פטור — יש להוסיף לכך תנאי: \u0003והוא שחתרה\u0004 הבהמה בעצמה מתחת לכותל ועל ידי חתירתה הפילה את הכותל, שזהו אונס גמור ולכן פטור הבעלים על נזקיה.","ושואלים: \u0003אבל\u0004 כאשר \u0003לא חתרה, מאי\u0004 \u0005[מה]\u0006 יהא הדין — שהוא \u0003חייב?\u0004 אם כן נברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003בכותל בריא\u0004 (חזק), \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא חתרה אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב? מאי הוה ליה למעבד\u0004 \u0005[מה היה לו לעשות]?\u0006 והרי לא היה הדבר כלל באשמתו! \u0003אלא\u0004 מדובר כאן \u0003בכותל רעוע,\u0004 אם כן גם \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003חתרה\u0004 הבהמה מתחת לכותל והפילתו \u0003אמאי\u0004 \u0005[מדוע]\u0006 שיהא \u0003פטור?\u0004 הרי זה מקרה של \u0003תחלתו בפשיעה\u0004 (רשלנות), שהכניס את בהמתו למקום שכותלו רעוע, \u0003ו\u0004רק \u0003סופו\u0004 \u0003באונס הוא ,\u0004 שהרי לבסוף חתרה!","\u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 שכל דבר ש\u0003תחילתו בפשיעה\u0004 \u0003וסופו באונס\u0004 — \u0003פטור\u0004, כיון שהגורם הסופי לא היה באשמתו. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת מי שאומר]: כי \u0003תחילתו בפשיעה וסופו באונס\u0004 — חייב, כיון שגם לולא האונס היתה רשלנותו גורמת לנזק, אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 כאן במשנתנו לפי שיטה זו?","\u0003אלא, מתניתין\u0004 \u0005[משנתנו]\u0006 יש להעמידה \u0003בכותל בריא, ואפילו לא חתרה\u0004 הבהמה גם כן פטור. \u0003וכי איתמר\u0004 \u0005[וכאשר נאמרו]\u0006 דברי \u0003רבה\u0004 — לא על קטע זה מן המשנה, אלא \u0003אסיפא איתמר\u0004 \u0005[על סוף\u0006 המשנה \u0005נאמרו]\u0006 שנאמר שם: \u0003הניחה בחמה, או שמסרה לחרש שוטה וקטן, ויצתה והזיקה\u0004 — \u0003חייב.\u0004 ועל כך \u0003אמר רבה: ואפילו חתרה.\u0004","ומסבירים: \u0003לא מבעיא היכא\u0004 \u0005[נצרכה\u0006 לומר במקום] ש\u0003לא חתרה\u0004 הבהמה ויצאה בדרך אחרת, שחייב — \u0003דכולה\u0004 \u0005[שהכל]\u0006 \u0003בפשיעה הוא,\u0004 שכיון שהניחה בחמה ומצטערת היא שם, ברור הוא שתנסה הבהמה לצאת משם בכל דרך. \u0003אלא אפילו חתרה נמי\u0004 \u0005[גם כן]\u0006 — גם כן חייב. וחידוש יש בדבר, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הויא לה\u0004 \u0005[הרי זה]\u0006 מקרה ש\u0003תחילתו בפשיעה וסופו באונס,\u0004 שהרי החתירה — אונס היא, על כן \u0003קא משמע לן דכולה\u0004 \u0005[השמיע לנו שהכל]\u0006 \u0003פשיעה היא,\u0004","\u0003 מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 הניזק לבעל הצאן: \u0003מידע ידעת\u0004 \u0005[יכול אתה לדעת]\u0006 ש\u0003כיון דשבקתה\u0004 \u0005[שהנחת אותה]\u0006 \u0003בחמה, כל טצדקא דאית\u0004 \u0005[תחבולה שיש]\u0006 \u0003לה למיעבד עבדא ונפקא\u0004 \u0005[לעשות תעשה ותצא]\u0006 ולכן אשמתך היא שיצאה.","שנינו במשנה: \u0003הוציאוה לסטים\u0004 — \u0003לסטים חייבין.\u0004"],["ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכך הוא הדין שהלסטים חייבים, שהרי \u0003כיון דאפקוה קיימא לה ברשותייהו\u0004 \u0005[ש\u0006משכוה ו\u0005הוציאוה\u0006 הרי \u0005היא\u0006 \u0005עומדת\u0006 מעתה \u0005ברשותם]\u0006 \u0003לכל מילי\u0004 \u0005[דבר]\u0006 כאילו היא שלהם, ובכלל זה גם אחריות לנזקים שהזיקה!","ומתרצים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דקמו\u0004 \u0005[שעמדו]\u0006 \u0003לה באפה\u0004 \u0005[בפניה]\u0006 ועל ידי כך הוציאוה מהדיר וכיוונו אותה לתבואה של אדם אחר והזיקה, אבל לא משכוה בידיים ממש. \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר רבה אמר רב מתנה אמר רב: המעמיד בהמת חברו על קמת חבירו\u0004 ואכלתה — \u0003חייב.\u0004 ותהו על דבר זה: \u0003מעמיד פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שחייב! והשיבו: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דקם לה באפה\u0004 \u0005[שעמד בפניה]\u0006 וגרם לה שתעלה על קמת חבירו בלי למושכה ממש, ואף על פי כן חייב.","ומסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: הכישה\u0004 (היכה אותה) \u0003אמרת לן\u0004 \u0005[לנו]\u0006 כאשר הסברת לנו את דברי רב מתנה, \u0003ולסטים נמי\u0004 \u0005[גם כן]\u0006 מדובר ש\u0003הכישוה\u0004 במקל, אף שלא משכוה בידיים.","שנינו במשנה שאם \u0003מסרה לרועה\u0004 — \u0003נכנס הרועה תחתיו. אמרי\u0004 \u0005[אומרים]\u0006 ודנים בשאלה: \u0003תחתיו דמאן\u0004 \u0005[של מי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי הרועה נכנס \u0003תחתיו\u0004 של \u0003בעל\u0004 ה\u0003בהמה\u0004 — הלא \u0003תנינא חדא זמנא\u0004 \u0005[שנינו\u0006 זאת כבר \u0005פעם אחת]:\u0006 \u0003מסרו לשומר חנם ולשואל, לנושא שכר ולשוכר\u0004 — \u0003כולן נכנסו\u0004 באחריות \u0003תחת הבעלים.\u0004 ואין חידוש במה שאמרו שאחריות מוטלת על הרועה שנמסרה לו! \u0003אלא\u0004 הכוונה היא \u0003תחתיו\u0004 של ה\u0003שומר,\u0004 שהשומר אינו חייב כיון שמסרה לרועה.","\u0003ו\u0004תוהים: מכלל הדברים נשמע כי ה\u0003שומר קמא אפטר ליה\u0004 \u0005[הראשון נפטר לו]\u0006 על ידי כך \u0003לגמרי,\u0004 ושוב אין עליו אחריות כלל. \u0003לימא תיהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 על דברי \u0003רבא,\u0004 ש\u0003אמר רבא: שומר שמסר לשומר\u0004 — \u0003חייב\u0004 השומר הראשון?","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003רבא\u0004 בתשובה לכך: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"מסרו לרועה\"\u0004 שנאמר במשנה — \u0003לברזיליה\u0004 \u0005[לעוזרו],\u0006 \u0003דאורחיה דרועה למימסר לברזיליה\u0004 \u0005[שדרכו של הרועה למסור לעוזרו]\u0006 את מה שנמסר לו לשמירה, ולכן, כל הנותן בהמה לרועה — נותן הוא לו בידיעה שהרועה עשוי למוסרה לעוזריו השונים.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 דבר זה בלשון אחרת: \u0003מדקתני\u0004 \u0005[ממה ששנה]\u0006 במשנה בלשון \u0003\"מסרה לרועה\", ולא קתני\u0004 \u0005[שנה]\u0006 סתם \u0003\"מסרה לאחר\", שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"מסרה לרועה\"\u0004 — \u0003מסר רועה לברזיליה\u0004 \u0005[לעוזרו],\u0006 וטעם הדבר שנכנס עוזרו תחתיו — \u0003דאורחיה דרועה למימסר לברזיליה\u0004 \u0005[שדרכו של הרועה למסור לעוזרו]\u0006 \u0003אבל לאחר\u0004 — \u0003לא\u0004 נפטר בכך הרועה.","ואם כן, \u0003לימא\u0004 \u0005[האם לומר]\u0006 ש\u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לרבא,\u0004 ש\u0003אמר רבא: שומר שמסר לשומר חייב?\u0004 \u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיה: \u0003לא,\u0004 אין לדייק מלשון המשנה שהכוונה דווקא כשמסר לעוזרו, כי \u0003דלמא אורחא דמילתא קתני\u0004 \u0005[שמא בדרך הדברים\u0006 הרגילה \u0005שנה]\u0006 שכרגיל מוסר הרועה לעוזרו, \u0003ו\u0004אולם \u0003הוא הדין לאחר,\u0004 ואין להביא מכאן הוכחה לשיטת רבא.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה עקרונית זו: \u0003שומר אבידה,\u0004 מי שמצא אבידה, ועד שהוא מחזירה הרי הוא שומר אותה אצלו, מה היא מידת האחריות שלו כלפי האבידה? \u0003רבה אמר: כשומר חנם דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006 \u0003רב יוסף אמר: כשומר שכר דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006","ומסבירים את שיטותיהם: \u0003רבה אמר\u0004 ש\u0003כשומר חנם דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 ומדוע — \u0003מאי\u0004 \u0005[מה]\u0006 \u0003הנאה קא מטי ליה\u0004 \u0005[מגיעה לו]\u0006 על ידי שמירה זו? ואם כן הרי הוא כשאר שומרי חנם. ואילו \u0003רב יוסף אמר\u0004 ש\u0003כשומר שכר דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 ומדוע — \u0003בההיא\u0004 \u0005[באותה]\u0006 \u0003הנאה\u0004 שהוא \u0003לא בעיא\u0004 \u0005[צריך]\u0006 עתה, כאשר הוא עוסק בשמירת האבידה \u0003למיתבי ליה ריפתא לעניא\u0004 \u0005[לתת לו פת לעני]\u0006 בצדקה, שהרי העוסק במצוה פטור מן המצוה, \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003כשומר שכר,\u0004 שנמצא שהוא מרוויח דברמה על ידי השמירה על האבידה.","זה הוא אופן פירוש אחד, ואולם \u0003איכא דמפרשי הכי\u0004 \u0005[יש שמפרשים\u0006 דבר זה \u0005כך],\u0006 \u0003רב יוסף אמר: כשומר שכר דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 וטעם הדבר: \u0003כיון דרחמנא שעבדיה\u0004 \u0005[שהתורה שיעבדה אותו]\u0006 לשמור על האבידה \u0003בעל כורחיה\u0004 \u0005[כורחו]\u0006 ואין הדבר תלוי בדעתו, \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003כשומר שכר דמי\u0004 \u0005[נחשב]\u0006 שבוודאי הטילה עליו התורה חובת שמירה מעולה.","\u0003(סימן\u0004 להלכות ולקושיות הבאות: \u0003החזירה לעולם השב חייא אמרת נשבר שכר).\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב יוסף לרבה\u0004 ממה ששנינו בברייתא זו:"],["\u0003החזירה\u0004 המוצא את האבידה \u0003למקום\u0004 כזה \u0003ש\u0004בו \u0003יראנה\u0004 בעליה — \u0003אינו חייב\u0004 עוד \u0003לטפל\u0004 (להתעסק) \u0003בה.\u0004 אם \u0003נגנבה או אבדה\u0004 המציאה — \u0003חייב\u0004 המוצא \u0003באחריותה.\u0004","ונברר את האמור בברייתא: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"נגנבה או אבדה\"? לאו\u0004 \u0005[האם אין]\u0006 הכוונה \u0003נגנבה מביתו ואבדה מביתו\u0004 לפני שהחזירה? וכיון שאמרו שחייב באחריותה של גניבה ואבידה — משמע שדינו כשומר שכר שחייב בגניבה ואבידה, ולא כשומר חינם שפטור!","ודחה רבה: \u0003לא,\u0004 הכוונה היא שנגנבה או שאבדה \u0003ממקום שהחזירה,\u0004 ובמקרה זה אף שומר חינם חייב כיון שהתרשל בשמירה, שלא החזירה כראוי.","והקשה רב יוסף על כך: \u0003והא קתני\u0004 \u0005[והרי שנה]\u0006 שם: \u0003אינו חייב ליטפל בה,\u0004 משמע שאין עליו עוד אחריות עליה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003הכא\u0004 \u0005[כאן]\u0006 בסוף הברייתא, ששנינו שחייב באחריותה, \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 \u0003כגון שהחזירה בצהרים,\u0004 שעה שבה אין בעל האבידה מצוי בביתו, ואין זו נחשבת השבה של ממש, ומשום כך אם נגנבה או אבדה האבידה — חייב באחריותה אף שהוא שומר חינם.","\u0003ותרתי קתני\u0004 \u0005[ושתי\u0006 הלכות שונות \u0005שונה]\u0006 שם, \u0003והכי קתני\u0004 \u0005[וכך\u0006 הוא \u0005שונה],\u0006 כלומר, כך יש להבין את הברייתא: \u0003החזירה\u0004 ב\u0003שחרית\u0004 שהוא זמן שבו מצויים אנשים בביתם \u0003למקום שיראנה\u0004 בעל האבידה \u0003ו\u0004כיון \u0003דשכיח\u0004 \u0005[שמצוי]\u0006 הוא \u0003דעייל ונפיק וחזי לה\u0004 \u0005[שנכנס ויוצא ורואה אותה]\u0006 את האבידה — המוצא \u0003אינו חייב ליטפל בה\u0004 עוד, ואף אינו חייב באחריותה אם נגנבה או אבדה. והלכה נוספת: אם \u0003החזירה בצהרים למקום שיראנה, דלא שכיח דעייל ונפיק, דלא חזי לה\u0004 \u0005[שאינו מצוי ש\u0006הוא \u0005נכנס ויוצא\u0006 באותה שעה, \u0005שאינו רואה אותה]\u0006 \u0003ונגנבה או אבדה\u0004 — \u0003חייב באחריותה.\u0004 ואם כן אין להוכיח מכאן.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 עוד רב יוסף לרבה ממה ששנינו בהמשך אותה ברייתא: \u0003לעולם הוא,\u0004 המוצא אבידה \u0003חייב\u0004 באחריותה אם נגנבה או אבדה \u0003עד שיחזירנה לרשותו\u0004 של בעל האבידה. \u0003מאי\u0004 \u0005[מה]\u0006 פירוש ההדגשה \u0003\"לעולם\", לאו\u0004 \u0005[האם אין]\u0006 הכוונה \u0003אפילו\u0004 נגנבה \u0003מביתו\u0004 של המוצא? ו\u0003שמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי המוצא אבידה \u0003כשומר שכר דמי\u0004 \u0005[\u0006הוא \u0005נחשב]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה לרב יוסף: \u0003מודינא\u0004 \u0005[מודה אני]\u0006 \u0003לך ב\u0004שומר אבידה של \u0003בעלי חיים\u0004 שאבדו שחייב בגניבה ואבידה, ש\u0003כיון דנקטי להו ניגרא ברייתא\u0004 \u0005[ש\u0006כבר \u0005לקחו לעצמם צעדים זרים]\u0006 שהם יוצאים ממסלול הדרכים הרגיל שלהם, שהרי ראינו כבר שברחו למקום אחר, \u0003בעי נטירותא יתירתא\u0004 \u0005[צריכים שמירה יתירה]\u0006 כשומר שכר. אבל חפצים אחרים שאינם הולכים מעצמם, ואבדו — אין המוצא אותם חייב לשומרם יותר משאר שומר חינם.","ומן הצד השני \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבה לרב יוסף\u0004 ממה ששנינו: נאמר בענין השבת אבידה \"השב תשיבם\" (דברים כב, א) ודרשו: \u0003\"השב\"\u0004 — \u0003אין לי אלא\u0004 שמשיב את הדבר \u0003בביתו\u0004 של בעל האבידה, אם השיב \u0003לגינתו ולחורבתו מנין\u0004 שגם כן קיים מצוה זו, ואינו אחראי עוד למציאה? \u0003תלמוד לומר: \"תשיבם\",\u0004 והכפלה זו באה לומר שקיים את המצוה \u0003מכל מקום,\u0004 בכל אופן\u0003.\u0004","ומעתה נברר את הדברים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"לגינתו ולחורבתו\"\u0004 השנויים כאן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהחזירם \u0003לגינתו המשתמרת\u0004 שגינתו סגורה כראוי ונשמרים בה דברים, \u0003ו\u0004כן \u0003לחורבתו המשתמרת\u0004 — אין בכך חידוש שקיים בכך המצוה, ופטור מאחריותו עליה, כי \u0003היינו\u0004 \u0005[הרי זה]\u0006 כמו \u0003ביתו,\u0004 שהרי המקום נשמר וברשותו הוא! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שהכוונה היא שהחזיר \u0003לגינתו שאינה משתמרת ולחורבתו שאינה משתמרת,\u0004 ואף על פי כן אינו אחראי עוד על המציאה. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003כשומר חנם דמי\u0004 \u0005[נחשב]\u0006 המוצא ולא יותר, ודי לו בהשבה שכזו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003לעולם\u0004 תפרש כי הכניסם \u0003לגינתו המשתמרת ולחורבתו המשתמרת, ודקא קשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 \u0003לך:\u0004 \u0003היינו\u0004 \u0005[הרי זה]\u0006 כמו \u0003ביתו,\u0004 ומה החידוש בדבר? יש בכל זאת חידוש, כי \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 \u0003דלא בעינן\u0004 \u0005[שאין אנו צריכים]\u0006 במקרה כזה \u0003דעת בעלים,\u0004 שאין צריך להודיע לבעל האבידה שהחזיר לו אבידתו, ו\u0003כ\u0004דברי \u0003ר' אלעזר.\u0004","ש\u0003אמר ר' אלעזר: הכל,\u0004 כל החייבים בהשבת חפץ לבעליו (כגון שומר או גנב) \u0003צריכין דעת בעלים\u0004 להודיע להם שהחזירו להם את השייך להם, \u0003חוץ מהשבת אבידה, שהרי ריבתה בו תורה\u0004 במשיב אבידה \u0003השבות הרבה,\u0004 שנאמר בלשון ריבוי \"השב תשיבם\" ללמדנו שאם החזירה אף בלא דעת הבעלים — הרי זו השבה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: ואת לא תסברא\u0004 \u0005[ואתה אינך סבור]\u0006 ש\u0003שומר אבידה כשומר חנם דמי\u0004 \u0005[נחשב]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: הטוען טענת גנב באבידה,\u0004 אדם שמצא אבידה וטוען שנגנבה ממנו, ולבסוף נמצא שהוא לקחה לעצמו — \u0003משלם תשלומי כפל\u0004 כאילו הוא עצמו גנב. \u0003ו\u0004מעתה נשאל: \u0003אי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 שמוצא האבידה \u0003שומר שכר הוי\u0004 \u0005[הוא],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 במקרה זה הוא \u0003משלם תשלומי כפל?\u0004 הרי \u0003קרנא בעי שלומי\u0004 \u0005[\u0006את \u0005הקרן\u0006 בלבד \u0005צריך\u0006 הוא \u0005לשלם],\u0006 שהרי שומר שכר חייב ממילא בגניבה ואבידה, וכיון שבדבריו חייב עצמו לשלם את ערך החפץ — אין מקום להחשיבו כגנב!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שטוען\u0004 המוצא \u0003טענת לסטים מזויין\u0004 (שודד מזויין בנשק), שבא ונטל את המציאה מידו, ובליסטים מזויין פטור אפילו שומר שכר. וכיון שטען טענת שקר שעל ידה הוא נפטר לגמרי מחובתו, אם לבסוף נמצאה האבידה אצלו — חייב הוא לשלם כפל כטוען טענת גנב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003ליסטים מזויין\u0004 הלא \u0003גזלן הוא\u0004 ולא גנב, וכיצד אפשר לקרוא לזה \"טוען טענת גנב\"?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003שאני אומר\u0004 כי \u0003לסטים מזויין, כיון דמיטמר מאינשי\u0004 \u0005[שמתחבא מבני אדם]\u0006 ואינו גוזל בגלוי לעיני כל — \u0003גנב הוא\u0004 להחשיב טוען טענת לסטים מזויין כטוען טענת גנב","\u0003,\u0004 ולכן כיון ששומר שכר נפטר בטענה זו, שהרי עבורו אונס הוא זה, אם נתברר שהיה זה טענת שקר — משלם כפל, כדין שומר חינם הטוען טענת גנב בפקדון ונמצא אחר כך הדבר בידו. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי ממה ששנינו בברייתא:"],["\u0003לא, אם אמרת בשומר חנם שכן משלם תשלומי כפל, תאמר בשומר שכר שאינו משלם תשלומי כפל?\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי \u0003לסטים מזויין גנב הוא, נמצא\u0004 כי גם \u0003בשומר שכר\u0004 יש דין של \u0003משלם תשלומי כפל\u0004 — \u0003בטוען טענת לסטים מזויין!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003הכי קאמר\u0004 \u0005[כך\u0006 הוא \u0005אומר],\u0006 כך יש להבין את הברייתא: \u0003לא, אם אמרת בשומר חנם שכן משלם תשלומי כפל בכל טענותיו,\u0004 בכל מקרה שנמצא שטען טענת שקר שהחפץ נגנב ממנו, \u0003תאמר בשומר שכר שאינו משלם תשלומי כפל\u0004 בכל טענת גניבה שקרית \u0003אלא בטוען טענת לסטים מזויין.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי לרב יוסף ממה ששנינו בברייתא אחרת: נאמר בתורה, בדין שואל חפץ או בעל חיים מחבירו: \u0003\"ונשבר או מת...\u0004 שלם ישלם\u0003\"\u0004 (שמות כב, יג) ואמרו חכמים במדרש הלכה: \u0003אין לי אלא שבורה ומתה\u0004 שחייב עליה השואל, \u0003גניבה ואבידה מנין\u0004 שגם כן חייב עליהן? \u0003אמרת\u0004 (אומר אתה) \u0003קל וחומר: ומה שומר שכר שפטר בו שבורה ומתה\u0004 שאינו חייב באחריותה, בכל זאת \u0003חייב בגניבה ואבידה, שואל שחייב\u0004 אפילו \u0003בשבורה ומתה\u0004 — \u0003אינו דין שחייב בגניבה ואבידה?\u0004 ומסכמים שם: \u0003וזהו קל וחומר שאין עליו תשובה,\u0004 שבוודאי חייב השואל אף על גניבה ואבידה.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003לסטים מזויין גנב הוא, אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין עליו,\u0004 על קל וחומר זה, \u0003תשובה?\u0004 הלא \u0003איכא למפרך\u0004 \u0005[יש\u0006 מקום \u0005להקשות]:\u0006 \u0003מה לשומר שכר\u0004 שיש בו צד חומרה שאין בשואל, \u0003שכן משלם תשלומי כפל בטוען טענת לסטים מזויין,\u0004 ואילו שואל אינו משלם על כך כפל אלא רק קרן!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003קסבר האי תנא\u0004 \u0005[סבור תנא זה]\u0006 כי תשלום \u0003קרנא\u0004 \u0005[קרן]\u0006 שמשלם שואל על טענה זו \u0003בלא שבועה, עדיפא\u0004 \u0005[עדיף,\u0006 חמור יותר\u0005]\u0006 \u0003מ\u0004תשלום \u0003כפילא\u0004 \u0005[כפל]\u0006 שמשלם טוען טענת גנב, שאינו מתחייב בו אלא \u0003בשבועה.\u0004 ולפיכך אין בתשלום כפל כזה של שומר שכר כדי לפרוך את הקל וחומר לשואל.","ומעירים: \u0003לימא מסייע ליה\u0004 \u0005[האם לומר\u0006 שאפשר \u0005לסייע לו]\u0006 לרב יוסף, הסבור שלסטים מזויין גנב הוא, ממה ששנינו: \u0003השוכר פרה מחבירו ונגנבה, ואמר הלה\u0004 (השוכר): \u0003הריני משלם\u0004 עבורה \u0003ואיני נשבע\u0004 שנגנבה הפרה, שאיני רוצה להישבע, \u0003ואחר כך נמצא הגנב\u0004 — \u0003משלם\u0004 הגנב את \u0003תשלומי\u0004 ה\u0003כפל לשוכר\u0004 ולא לבעלים.","ומעירים: \u0003סברוה\u0004 \u0005[סברו]\u0006 הלומדים שרצו לסייע לרב יוסף, כי ברייתא זו \u0003כ\u0004שיטת \u0003ר' יהודה\u0004 היא, ש\u0003אמר: שוכר כנושא שכר דמי\u0004 \u0005[נחשב]\u0006 שחייב בגניבה ואבידה, \u0003ומדקתני\u0004 \u0005[ומ\u0006מה \u0005ששנה]:\u0006 \u0003ואמר \"הריני משלם ואיני נשבע\", מכלל\u0004 הדברים נשמע \u0003דאי בעי פטר ליה נפשיה\u0004 \u0005[שאם היה\u0006 השוכר \u0005רוצה, היה פוטר עצמו]\u0006 \u0003בשבועה\u0004 ולא היה צריך לשלם.","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד היה הדבר בדיוק]?\u0006 האם לא \u0003כגון דקא טעין\u0004 \u0005[שטוען]\u0006 \u0003טענת לסטים מזויין\u0004 שכשומר שכר אינו חייב באחריות על כך, \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003ואחר כך נמצא הגנב\u0004 — \u0003משלם תשלומי כפל לשוכר, שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003לסטים מזויין גנב הוא!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 ודוחים הוכחה זו: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי ברייתא זו היא \u0003כ\u0004דעת \u0003ר' יהודה\u0004 ש\u0003אמר: שוכר כנושא שכר דמי\u0004 \u0005[\u0006הוא \u0005נחשב]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 תנא זה \u0003כ\u0004שיטת \u0003ר' מאיר סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ש\u0003אמר:\u0004 \u0003שוכר כשומר חנם דמי\u0004 \u0005[נחשב],\u0006 ומשום כך הוא נפטר מאחריות גם בטענת גניבה רגילה.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 כמו שהיה \u0003מחליף רבה בר אבוה ותני\u0004 \u0005[ושונה]\u0006 את הדברים בחילוף הדעות: \u0003שוכר כיצד משלם? ר' מאיר אומר: כשומר שכר, ר' יהודה אומר: כשומר חנם,\u0004 ונמצא שאף אם ברייתא זו היא כדעת ר' יהודה, אין ממנה סיוע לרב יוסף.","\u0003ר' זירא אמר:\u0004 אפילו אם אין הופכים את השיטות, אפשר לפרש את הברייתא שלא כדברי רב יוסף, ולומר: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003בטוען\u0004 השוכר \u0003טענת לסטים מזויין\u0004 ומשום כך יכול היה להיפטר בשבועה — \u0003ונמצא\u0004 שהיה זה \u0003לסטים שאינו מזויין\u0004 אלא גנב, ולכן משלם הגנב תשלומי כפל לשוכר.","שנינו במשנה: \u0003נפלה\u0004 הבהמה \u0003לגינה ונהנית\u0004 — \u0003משלמת,\u0004 כלומר, בעליה משלמים רק על \u0003מה שנהנית. אמר רב:\u0004 כאן מדובר \u0003בנחבטה,\u0004 שנפלה על הירקות ועל ידי כך נחבטה פחות, ונהנתה מזה שלא ניזוקה, ועל כך משלמים הבעלים.","ומעירים: מדברי רב יש לדייק: \u0003אבל\u0004 אם \u0003אכלה\u0004 באותה גינה \u0003אפילו מה שנהנית אינה משלמת.\u0004 \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003רב\u0004 הולך פה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 בענין נזקים שנגרמו לבהמה כשאכלה פירות של אדם אחר, ש\u0003אמר רב\u0004 שיכול בעל הפירות לטעון: \u0003היה לה שלא תאכל.\u0004 ואף פה, בעל הבהמה יכול לומר: בהמה זו נפלה שלא באשמתי, ואם אכלה — אין זו אשמתי?","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתמיהה: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]\u0006 בין הדברים? \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר רב התם\u0004 \u0005[שם]\u0006 שיכול אדם לטעון \u0003\"היה לה שלא תאכל\"\u0004 — \u0003היכא דאיתזקא\u0004 \u0005[במקום שניזוקה]\u0006 \u0003היא\u0004 הבהמה בפירות חבירו, \u0003דמצי אמר ליה מריה דפירי\u0004 \u0005[שיכול לומר לו בעל הפירות]\u0006 לבעל הפרה: \u0003לא משלמנא\u0004 \u0005[אין אני משלם]\u0006 על מה שניזקה בהמתך באכילתה, כי \u0003היה לה שלא תאכל.\u0004 אבל \u0003לאזוקי\u0004 \u0005[\u0006כאשר \u0005מזיקה]\u0006 \u0003היא אחריני\u0004 \u0005[אחרים]\u0006\u0003, דפטירה לשלומי מי\u0004 \u0005[\u0006שתיפטר לשלם בטענה זו \u0005האם]\u0006 \u0003אמר\u0004 רב? אין הדבר מתקבל כלל.","\u0003אלא\u0004 יש לדחות דיוק זה בדברי רב, ולומר כי בלשון"],["\u0003לא מבעיא קאמר\u0004 \u0005[נצרכה אמר]\u0006 וכך יש להבין את דבריו: \u0003לא מבעיא\u0004 \u0005[נצרכה]\u0006 לומר שאם הבהמה נפלה לגינה ו\u0003אכלה\u0004 מפירות אותה גינה — ש\u0003משלמת מה שנהנית, אבל\u0004 אם \u0003נחבטה\u0004 באותם פירות, ומשום כך לא ניזוקה — \u0003אימא\u0004 \u0005[אמור]\u0006 שעל כך אין בעל הבהמה חייב לשלם, כי נמצא בעל הגינה הריהו כמי ש\u0003מבריח ארי מנכסי חבירו הוא\u0004 שאף שחבירו נהנה ממנו אינו חייב לשלם לו על כך, \u0003ו\u0004לכן \u0003מה שנהנית נמי\u0004 \u0005[גם כן]\u0006 \u0003לא משלם,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת משלם מה שנהנית.","ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור כך גם כן]\u0006 שיהא זה הדין, ולא יצטרך בעל הבהמה לשלם כלל עבור הנאה זו!","ומשיבים: \u0003מבריח ארי מנכסי חבירו\u0004 שאינו זכאי לתשלום — \u0003מדעתו הוא\u0004 שעושה כן, \u0003האי\u0004 \u0005[זהו]\u0006 בעל הגינה — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מדעתו\u0004 עשה, שלא רצה בכך. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר: \u0003מבריח ארי מנכסי חבירו\u0004 — \u0003לית ליה פסידא\u0004 \u0005[אין לו הפסד]\u0006 בכך, \u0003האי\u0004 \u0005[זהו]\u0006 בעל הגינה — \u0003אית ליה פסידא\u0004 \u0005[יש לו הפסד].\u0006","ועוד בבירור דין המשנה בבהמה שנפלה לגינה, שאינה משלמת מה שהזיקה, שואלים: \u0003היכי\u0004 \u0005[כיצד]\u0006 \u0003נפל?\u0004 באיזו דרך נפילה הדין כך? \u0003רב כהנא אמר: שהוחלקה במימי רגליה, רבא אמר: שדחפתה חברתה,\u0004 בהמה אחרת של אותם בעלים, והפילתה לשם.","ומסבירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שמדובר כאן \u0003שדחפתה חברתה\u0004 פטור מלשלם מה שהזיקה — \u0003כל שכן\u0004 שכך הוא הדין במקרה \u0003שהוחלקה במימי רגליה\u0004 שהוא אונס גדול יותר. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שמדובר כאן \u0003שהוחלקה במימי רגליה,\u0004 סבור: \u0003אבל דחפתה חברתה\u0004 — \u0003פשעה\u0004 ואין זה אונס, \u0003ומשלמת מה שהזיקה, דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בעל הגינה לבעל הבהמות: \u0003איבעי לך עבורי חדא חדא\u0004 \u0005[היה לך להעביר\u0006 את בהמותיך \u0005אחת אחת]\u0006 שלא תדחוף בהמה אחת את חבירתה.","\u0003אמר רב כהנא: לא שנו\u0004 שמשלמת רק מה שנהנית \u0003אלא\u0004 כשאכלה \u0003באותה ערוגה\u0004 עצמה שנפלה לתוכה, \u0003אבל\u0004 אם הלכה \u0003מערוגה\u0004 זו \u0003לערוגה\u0004 אחרת ואכלה משם — \u0003משלמת\u0004 כל \u0003מה שהזיקה. ור' יוחנן אמר: אפילו\u0004 הלכה \u0003מערוגה לערוגה\u0004 ואכלה, \u0003ואפילו\u0004 שהיתה בגינה זו \u0003כל היום כולו\u0004 ואכלה שם — משלמת רק מה שנהנית ולא מה שהזיקה, \u0003עד שתצא\u0004 מן הגינה \u0003ותחזור לדעת\u0004 (בידיעת הבעלים).","ובפירוש דברי ר' יוחנן \u0003אמר רב פפא: לא תימא\u0004 \u0005[תאמר]\u0006 \u0003עד שתצא לדעת ותחזור לדעת, אלא כיון שיצתה\u0004 (יצאה) מן הגינה \u0003לדעת\u0004 הבעלים, \u0003אף על פי שחזרה שלא לדעת,\u0004 שלא ידעו שחזרה לשם, בכל זאת חייב לשלם כל מה שהזיקה. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בעל הפירות לבעל הבהמה: \u0003כיון דילפא\u0004 \u0005[שלמדה]\u0006 שיש פה גינה שבה אפשר לאכול, \u0003כל אימת דמשתמטא\u0004 \u0005[פעם ש\u0006היא \u0005משתמטת]\u0006 ממקומה — \u0003להתם רהטא\u0004 \u0005[לשם\u0006 היא \u0005רצה].\u0006","שנינו במשנה: \u0003ירדה\u0004 הבהמה \u0003כדרכה\u0004 לגינה \u0003והזיקה\u0004 שם — \u0003משלמת\u0004 כל \u0003מה שהזיקה.\u0004 \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה\u0004 שאלה זו: \u0003ירדה\u0004 הבהמה \u0003כדרכה, והזיקה\u0004 את פירות הגינה \u0003במי לידה,\u0004 שילדה שם ולד, ונגרם נזק לפירות על ידי מי הלידה, \u0003מהו?\u0004 האם צריך בעל הבהמה לשלם גם עבור נזק זה?","ומעירים: \u0003אליבא דמאן דאמר\u0004 \u0005[לשיטתו של מי שאומר]\u0006 כל ש\u0003תחלתו בפשיעה\u0004 (ברשלנות) \u0003וסופו באונס\u0004 — \u0003חייב\u0004 על הכל, \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה זו, שוודאי חייב. שאף כאן הרי זה נזק שתחילתו בפשיעה, שבהמתו נכנסה לחצר חבירו, וסופו באונס. \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 שאלה זו, הרי זה \u0003אליבא דמאן דאמר\u0004 \u0005[לשיטתו של מי שאומר]\u0006 שאם \u0003תחלתו בפשיעה וסופו באונס\u0004 — \u0003פטור. מאי\u0004 \u0005[מה]\u0006 הדין כאן?","וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 \u0003כיון\u0004 ש\u0003תחלתו\u0004 היתה \u0003בפשיעה וסופו באונס\u0004 — \u0003פטור, או דלמא\u0004 \u0005[שמא]\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003כולה בפשיעה הוא,\u0004 ש\u0003כיון דקא חזי דקריבה לה למילד, איבעי ליה לנטורה\u0004 \u0005[ש\u0006הוא \u0005רואה ש\u0006היא \u0005מתקרבת ללדת, היה לו לשומרה]\u0006"],["\u0003ולאסתמורי בגוה\u0004 \u0005[ולהישמר בה]\u0006 ואם לא עשה זאת — הרי זו אחריותו? לשאלה זו לא נמצאה תשובה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","במשנה מסבירים: \u0003כיצד משלמת מה שהזיקה?\u0004 — שמין בית סאה באותה שדה כמה היתה יפה וכמה היא יפה. כלומר, מחשבים את הנזק שנגרם לשדה כולו, ולא לקרקע המסויימת שהוזקה לעצמה. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו]\u0006 שעושים את הערכת הנזק בדרך זו?","\u0003אמר רב מתנה:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ובער בשדה אחר\"\u0004 (שמות כב, ד), \u0003מלמד ששמין\u0004 (מעריכים) את הנזק \u0003על גב שדה אחר,\u0004 כלומר, ביחס לשדה הניזק כולו, דהיינו שטח נוסף, גדול יותר מאשר אותו חלק השדה שניזוק.","ותוהים: \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"ובער בשדה אחר\" מבעי ליה\u0004 \u0005[צריך לו]\u0006 ללמוד ממנו הלכה אחרת, שאין חייבים הבעלים אלא רק אם היתה זו שדה של איש אחר, \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003רשות הרבים,\u0004 שאם אכלה בהמתו שם אין בעליה חייב!","ומשיבים: \u0003אם כן\u0004 שרק לזה בלבד היתה הכוונה, \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"ובער בשדה חבירו\",\u0004 \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 שתכתוב \u0003\"\u0004וביער \u0003שדה אחר\", מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"בשדה אחר\"\u0004 — ללמד \u0003ששמין על גב שדה אחר.\u0004","ושואלים: אם כן \u0003ואימא כוליה להכי\u0004 \u0005[ואמור ש\u0006מקרא זה \u0005כולו לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 ללמדנו דבר זה, ואם כן לימוד זה של \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 נזקי שן ב\u0003רשות הרבים\u0004 שפטור \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006","ומשיבים: \u0003אם כן,\u0004 שאין הכתוב עוסק במקום נזק אלא רק בדרך התשלומים, \u0003לכתביה רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 דבר זה רק \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003תשלומין,\u0004 ובדרך זו: \u0003\"מיטב שדהו ומיטב כרמו ישלם בשדה אחר\", למה לי\u0004 (משום מה) \u0003דכתביה רחמנא גבי\u0004 \u0005[כתבתו התורה אצל]\u0006 \u0003\"ובער\"? שמע מינה תרתי\u0004 \u0005[למד מכאן שני\u0006 לימודים\u0005]:\u0006 הן לגבי מקום הנזק, והן לגבי דרך הערכת הנזק.","ושואלים: \u0003היכי שיימינן\u0004 \u0005[כיצד אנו מעריכים]\u0006 את שווי החלקה שניזוקה לצורך תשלום הנזק? \u0003אמר ר' יוסי בר חנינא:\u0004 מעריכים כמה שווה בית \u0003סאה ב\u0004תוך \u0003ששים סאין\u0004 ולפי זה קובעים את הנזק. \u0003ר' ינאי אמר:\u0004 מעריכים כל \u0003תרקב\u0004 (חצי סאה) \u0003ב\u0004תוך \u0003ששים תרקבים\u0004 (שהם שלושים סאה), \u0003חזקיה אמר:\u0004 מעריכים כמה שווה כל \u0003קלח ב\u0004תוך \u0003ששים קלחים,\u0004 כלומר, כל שטח שניזוק, מחשבים את הפחת ביחס לשטח גדול פי ששים ממנו.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003אכלה\u0004 הבהמה \u0003קב או קביים\u0004 (שני קבים), \u0003אין אומרים תשלם דמיהן\u0004 כפי הכמות שהזיקה, \u0003אלא רואין אותה כאילו היא,\u0004 החלקה שנאכלה, \u0003ערוגה קטנה, ומשערים אותה\u0004 כמה היא שווה. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה שמשערים את ערכה של הערוגה כאילו היתה נמכרת \u0003בפני עצמה?\u0004 והרי זה שלא כדברי כל אלה החכמים.","ודוחים: \u0003לא,\u0004 הכוונה היא שמשערים אותה \u0003בששים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין שמין\u0004 בהערכת הנזק \u0003קב, מפני שמשביחו,\u0004 שגורם לרווח מוגדל בדמי התשלומים, \u0003ולא\u0004 מעריכים בתוך \u0003בית כור\u0004 (שהוא מקום זריעה של שלושים סאה), \u0003מפני שפוגמו,\u0004 שגורם להפסד מוגדל בדמי התשלומים.","ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר]?\u0006 \u0003אמר רב פפא: הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אין שמין קב בששים קבים\u0004 — \u0003מפני שמשביח\u0004 (מרוויח) על ידי כך \u0003מזיק,\u0004 שששים קבים הם כמות גדולה מדי לאדם פרטי וקטנה מדי לסיטונאי, ולפיכך מדה כגון זו נמכרת תמיד בשוק במחיר זול יותר, ונמצא המזיק משלם פחות. \u0003ולא\u0004 שמים \u0003כור בששים כורין מפני שפוגם\u0004 הוא את ה\u0003מזיק,\u0004 משום שכמות גדולה כזו נמכרת רק לאדם שיש לו ענין מיוחד בכמות כזו, והוא משלם, לפי צורכו, יותר מן המחיר הרגיל.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב הונא בר מנוח:\u0004 לפירוש זה, \u0003האי\u0004 \u0005[\u0006ביטוי \u0005זה]\u0006 \u0003\"ולא בית כור\"\u0004 אינו מתאים, אלא \u0003\"ולא כור\" מבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר, כפי שאמר \"קב\" ולא \"בית קב\"! ואין דיוק הלשון עולה יפה לשיטה זו.","\u0003אלא אמר רב הונא בר מנוח משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא, הכי קתני\u0004 \u0005[כך שנה]:\u0006 \u0003אין שמין קב בפני עצמו\u0004 — \u0003מפני שמשביח\u0004 על ידי כך ה\u0003ניזק, ולא\u0004 שמים \u0003קב ב\u0004תוך \u0003בית כור\u0004 — \u0003מפני שפוגם ניזק,\u0004 שפגם בתוך שטח גדול כזה כמעט שאינו נחשב, \u0003אלא\u0004 שמים \u0003בששים.\u0004","מסופר: \u0003ההוא גברא דקץ קשבא מחבריה\u0004 \u0005[אדם אחד קצץ דקל של חבירו],\u0006 \u0003אתא לקמיה דריש גלותא\u0004 \u0005[בא לפני ראש הגולה]\u0006 לדין, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ראש הגולה למזיק: \u0003לדידי חזי לי\u0004 \u0005[אני עצמי ראיתי אותו]\u0006 מקום נטיעת הדקל \u0003ותלתא תאלתא בקינא הוו קיימי\u0004 \u0005[ושלושה דקלים בקן,\u0006 יוצאים משורש אחד, \u0005היו עומדים\u0006 שם\u0005]\u0006 \u0003והוו שוו\u0004 \u0005[והיו שווים]\u0006 ביחד \u0003מאה זוזי\u0004 \u0005[זוזים],\u0006 וכיון שקצצת אחד מהם — \u0003זיל הב ליה תלתין ותלתא ותילתא\u0004 \u0005[לך תן לו שלושים ושלושה ושליש\u0006 זוזים\u0005]\u0006 שהם שליש משווי הכל. \u0003אמר\u0004 המזיק: \u0003גבי ריש גלותא דדאין דינא דפרסאה\u0004 \u0005[אצל ראש הגולה הדן דיני הפרסיים]\u0006 \u0003למה לי\u0004 להתדיין? \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב נחמן\u0004 באותו דין, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 מעריכים את הנזק \u0003ב\u0004תוך \u0003ששים.\u0004 שפסק כך על פי האמור בסוגייתנו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לרב נחמן: \u0003אם אמרו\u0004 חכמים שמעריכים בששים \u0003בנזקי ממונו\u0004 כגון כשבהמתו הזיקה, \u0003יאמרו\u0004 שמעריכים הערכה כזו גם \u0003בנזקי גופו,\u0004 כאשר הוא עצמו מזיק?","כנגד זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבא: בנזקי גופו מאי דעתיך\u0004 \u0005[מה דעתך]\u0006 מדוע סבור אתה שיש להחמיר — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אדם \u0003המבכיר\u0004 (משחית) \u0003כרמו של חבירו\u0004 בעודו \u0003סמדר\u0004 (בטרם הגיעו הענבים לבישולם) — \u0003רואין אותו\u0004 את הכרם \u0003כמה היתה יפה\u0004 (שווה) \u0003קודם לכן\u0004 לפני שהשחיתו \u0003וכמה היא יפה לאחר מכאן, ואילו בששים לא קתני\u0004 \u0005[שנה]\u0006 ועל כך אתה סומך להחמיר בנזקי גופו.","ואולם, \u0003אטו גבי\u0004 \u0005[האם אצל]\u0006 נזקי \u0003בהמתו נמי מי\u0004 \u0005[גם כן האם]\u0006 \u0003לא תניא כי האי גוונא\u0004 \u0005[שנויה\u0006 ברייתא \u0005כגון זו]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003קטמה\u0004 (נשכה, אכלה) הבהמה \u0003נטיעה\u0004 שעדיין לא הגיעה לתת פירות, \u0003ר' יוסי אומר: גוזרי גזירות\u0004 (הדיינים) \u0003שבירושלים אומרים\u0004 וקובעים סכומי נזקים קצובים לכך: \u0003נטיעה בת שנתה\u0004 — משלם עבורה \u0003שתי כסף,\u0004 נטיעה \u0003בת שתי שנים\u0004 — \u0003ארבעה כסף.\u0004 אם \u0003אכלה חזיז\u0004 (תבואה בעודה ירוקה בטרם הגיע הדגן לבישולו) — \u0003ר' יוסי הגלילי אומר: נידון במשוייר שבו,\u0004 שממתינים עד שתגיע הבשלת שאר התבואה בשדה זה, ומעריכים לפי מה שנשאר, כמה היתה שווה עכשיו התבואה שנאכלה קודם לכן. \u0003וחכמים אומרים: רואין אותה\u0004 את חלקת השדה שניזוקה \u0003כמה היתה יפה\u0004 קודם, לפני הנזק, \u0003וכמה היא יפה\u0004 כעת, לאחר שהבהמה אכלה."],["\u0003אכלה\u0004 הבהמה את הענבים בעודם \u0003סמדר\u0004 (מיד בתחילת גידולם) — \u0003ר' יהושע אומר: רואין אותן\u0004 את הענבים שניזוקו \u0003כאילו הן ענבים\u0004 ה\u0003עומדות ליבצר,\u0004 ולפי שיעור זה מעריכים את הנזק, \u0003ו\u0004אילו \u0003חכמים אומרים: רואין\u0004 את החלקה \u0003כמה היתה יפה\u0004 (שווה) קודם לכן \u0003וכמה היא יפה\u0004 לאחר הנזק, ואת ההפרש ישלם, ואין מעריכים את הפירות לעצמם. \u0003ר' שמעון בן יהודה אומר משום\u0004 (בשם) \u0003ר' שמעון: במה דברים אמורים\u0004 שמעריכים את החלקה שניזוקה — \u0003בזמן שאכלה לולבי גפנים\u0004 (ענפים צעירים של גפנים) או \u0003יחורי\u0004 (שתילי) \u0003תאנים, אבל\u0004 כאשר \u0003אכלה פגים\u0004 של תאנים שעדיין לא הבשילו, \u0003או בוסר\u0004 של ענבים — \u0003רואין אותן כאילו\u0004 היו \u0003ענבים עומדות ליבצר.\u0004","\u0003קתני מיהת\u0004 \u0005[שנה מכל מקום],\u0006 \u0003וחכמים אומרים: רואין אותן כמה היתה יפה וכמה היא יפה, ולא קתני\u0004 \u0005[שנה]\u0006 שמעריכים זאת \u0003בששים.\u0004","\u0003אלא מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר]\u0006 — שהכוונה בלשון זו היא שמעריכים \u0003בששים, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בברייתא העוסקת באדם הגורם נזק בעצמו, יש להבין את הלשון \"רואים כמה היתה יפה\" וכו', שמעריכים את הנזק \u0003בששים.\u0004","אגב שהובאה ברייתא זו דנים במה שנאמר בה. \u0003אמר אביי: ר' יוסי הגלילי ור' ישמעאל אמרו דבר אחד,\u0004 כלומר, שניהם הולכים בשיטה אחת לגבי אומדן הנזקים, שמעריכין לפי שארית הפירות שלא נאכלו באותו שדה, כמה הם שווים לאחר שהבשילו.","\u0003ר' יוסי הגלילי\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 בברייתא, שנידון במשוייר שבו.","\u0003ר' ישמעאל\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר \u0003\"מיטב שדהו ומיטב כרמו ישלם\"\u0004 (שמות כב, ד), וכוונתו: \u0003מיטב שדהו של ניזק ומיטב כרמו של ניזק,\u0004 אלו \u0003דברי ר' ישמעאל, ר' עקיבא אומר: לא בא הכתוב אלא לגבות לניזקין מן העידית,\u0004 שהמזיק משלם ממיטב שדהו וכרמו, שאם משלם לו בקרקעות נותן לו מן העידית שבקרקעותיו, \u0003וקל וחומר להקדש,\u0004 שאם הזיק להקדש משלם מן העידית.","\u0003ולא תימא\u0004 \u0005[תאמר,\u0006 תפרש\u0005]\u0006 את דברי ר' ישמעאל \u0003כ\u0004הסברו של \u0003רב אידי בר אבין,\u0004 ש\u0003אמר רב אידי בר אבין:\u0004 כאן מדובר \u0003כגון שאכלה\u0004 הבהמה \u0003ערוגה בין הערוגות, ולא ידעינן\u0004 \u0005[יודעים אנו]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ערוגה זו \u0003כחושה\u0004 \u0005[רזה\u0006 ופחותה\u0005]\u0006 \u0003הואי\u0004 \u0005[היתה],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003שמינה הואי\u0004 \u0005[היתה],\u0006 \u0003דאמר\u0004 \u0005[שאומר]\u0006 הכתוב: \u0003קום שלים\u0004 \u0005[עמוד\u0006 ו\u0005שלם]\u0006 \u0003שמינה במיטב דאיכא השתא\u0004 \u0005[שיש עכשיו],\u0006 ואין אומרים שערוגה זו שניזוקה לא היתה מטופחת כל כך. \u0003דהכי לא אמרינן\u0004 \u0005[שכך אין אנו אומרים],\u0006","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 לא ניתן לפרש כך? לפי הכלל הגדול: \u0003המוציא מחבירו עליו הראיה,\u0004 שצריך הניזק להוכיח שהערוגה שניזוקה היתה מן המיטב. \u0003אלא\u0004 כוונת ר' ישמעאל לפרש \"מיטב שדהו\" של ניזק — \u0003במיטב דלקמיה\u0004 \u0005[שלפניו],\u0006 \u0003ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 — \u0003כי היאך דסליק\u0004 \u0005[כמו זה ש\u0006הוא צומח ו\u0005עולה]\u0006 לאחר מכן, דהיינו המשוייר שבו, שלפי זה מעריכים את תשלום הנזק.","ועוד בברייתא: \u0003אמר מר\u0004 \u0005[החכם],\u0006 \u0003ר' שמעון בן יהודה אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון: במה דברים אמורים\u0004 שמעריכים את חלקת השדה שניזוקה, כמה היתה יפה וכמה היא יפה — \u0003שאכלה לולבי גפנים ויחורי תאנים.\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם אכלה \u0003סמדר\u0004 — \u0003רואין אותן כאילו\u0004 היו \u0003ענבים עומדות ליבצר.\u0004 ואולם, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של הברייתא\u0005]:\u0006 \u0003אכלה פגים או בוסר\u0004 שהוא שלב מאוחר יותר בהבשלה \u0003הוא\u0004 ש\u0003רואין אותן כאילו\u0004 היו \u0003ענבים עומדות ליבצר, הא\u0004 \u0005[הרי]\u0006 אם אכלה \u0003סמדר\u0004 — \u0003רואין אותן כמה היא יפה וכמה היתה יפה,\u0004 ואם כן יש סתירה מן הדיוקים של התחלת הדברים ושל סופם!","\u0003אמר רבינא: כרוך\u0004 את הדברים \u0003ותני\u0004 \u0005[ושנה]\u0006 אותם יחד וכך תשנה: \u0003במה דברים אמורים\u0004 שמעריכים כמה שווה השדה בזמן הנזק — \u0003בזמן שאכלה\u0004 הבהמה \u0003לולבי גפנים ויחורי תאנים, אבל אכלה סמדר פגין או בוסר, רואין אותן כאילו\u0004 היו אלה \u0003ענבים עומדות ליבצר,\u0004 שדין הסמדר כדין הפגים והבוסר.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, נמצא כי שיטת \u0003ר' שמעון בן יהודה היינו\u0004 \u0005[הוא]\u0006 כשיטת \u0003ר' יהושע\u0004 לענין סמדר, ואין כל הבדל בין השיטות!","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש\u0006 הבדל \u0005ביניהם]\u0006 לגבי \u0003כחש גופנא\u0004 \u0005[פחת\u0006 של \u0005הגפן\u0006 עצמה\u0005]\u0006 שהגפן שניזוקה היתה נחלשת על ידי הענבים הצומחות בה, ועתה שנאכלו הענבים לא נחלשה הגפן, שלשיטה אחת מתחשבים בפחת הזה (ומנכים אותו מתשלום הנזק), ולשיטה אחרת אין מחשיבים אותו, \u0003ולא מסיימי\u0004 \u0005[ואין\u0006 הם \u0005מוגדרים],\u0006 כלומר, נראה לנו כי בנושא זה חלקו ר' יהושע ור' שמעון בן יהודה, אלא שלא ברור לנו מה דעת כל אחד מהם בענין זה.","ואילו \u0003אביי אמר: מסיימי ומסיימי\u0004 \u0005[מוגדרים ומוגדרים\u0006 הם\u0005]\u0006 ויש אפשרות לברר מי האומר כשיטה זו ומי האומר כשיטה האחרת, שכן \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא דחייש לכחש גופנא\u0004 \u0005[החושש לפחת של הגפן\u0006 עצמה\u0005]\u0006 — \u0003ר' שמעון בן יהודה היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בענין אחר: \u0003ר' שמעון בן יהודה אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן מנסיא: אונס אינו משלם\u0004 לאנוסה (בתולה) \u0003את\u0004 תשלום \u0003הצער\u0004 שגרם לה במעשהו, \u0003מפני שסופה להצטער תחת בעלה,\u0004 שאם היתה נישאת היתה סובלת אותו צער עצמו, ואם כן אין לחשב צער זה בתשלומים שמשלם האונס. ואמרו לו חכמים: \u0003אינו דומה\u0004 צערה של ה\u0003נבעלת ברצון\u0004 (אשה נשואה) \u0003ל\u0004צערה של ה\u0003נבעלת באונס,\u0004 שנבעלת באונס יש לה צער גדול יותר. על כל פנים רואים שר' שמעון בן יהודה מנכה מן התשלומים של עכשיו כל פחת שהיה בא ממילא לאחר מכן, והוא הסבור כן לענין פחת הגפן.","\u0003אמר אביי: הני תנאי\u0004 \u0005[תנאים אלה]\u0006 שיבואר הלאה מי הם, \u0003ור' שמעון בן יהודה, אמרו דבר אחד\u0004 לענין זה. \u0003ר' שמעון בן יהודה\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 לגבי אונס ופחת הגפן. \u0003הני תנאי מאי היא\u0004 \u0005[תנאים אלה מה הוא]\u0006 —","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בדין אדם המזיק אשה הרה וגורם לה להפיל את עוברה, שאמרה תורה שחייב לשלם לבעלה את דמי הוולדות, \u0003ר' יוסי אומר:\u0004 תשלום זה הוא דמי הוולדות \u0003נכי\u0004 \u0005[פחות]\u0006 התשלום שהיו מוציאים עבור \u0003חיה\u0004 (מילדת), שכיון שהפילה שוב אין הבעל צריך לשלם למילדת, ומנכים דמים אלה. \u0003בן עזאי אומר: נכי\u0004 \u0005[פחות]\u0006 דמי \u0003מזונות,\u0004 שצריך היה הבעל להוסיף לאשתו בזמן הריונה. ואגב הבאת ברייתא זו מסבירים את טעם המחלוקת.","\u0003מאן דאמר נכי\u0004 \u0005[מי שאומר פחות]\u0006 דמי \u0003חיה, כל שכן\u0004 שהוא מסכים כי \u0003נכי\u0004 \u0005[פחות]\u0006 דמי ה\u0003מזונות, ומאן דאמר נכי\u0004 \u0005[ומי שאומר פחות]\u0006 דמי \u0003מזונות, אבל נכי\u0004 \u0005[פחות]\u0006 דמי \u0003חיה\u0004 — \u0003לא, דאמר ליה\u0004 \u0005[ש\u0006יכול הבעל \u0005לומר לו]\u0006 למזיק: \u0003אתתא דידי פקיחא\u0004 \u0005[אשתי שלי פיקחת\u0006 וזריזה\u0005]\u0006 \u0003היא ולא מבעיא\u0004 \u0005[צריכה]\u0006 \u0003חיה\u0004 כדי ללדת.","ושוב לעיקר הענין כיצד מעריכים, מסופר: \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע עבוד עובדא כוותיה\u0004 \u0005[עשו מעשה כשיטתו של]\u0006 \u0003רב נחמן\u0004 והעריכו דקל שניזוק \u0003בששים\u0004 אגב הקרקע.","והלכה זו נאמרה ב\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]:\u0006 \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע שמו\u0004 (העריכו) את הנזק שנגרם ל\u0003דקלא\u0004 \u0005[דקל]\u0006 \u0003אגב\u0004 הערכת \u0003קטינא דארעא\u0004 \u0005[חלקת האדמה]\u0006 שבה עמד הדקל, כמה היתה שווה עם הדקל וכמה בלעדיו.","ומסכמים: \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע בדקלא דארמאה\u0004 \u0005[בדקל ארמי]\u0006 שאיננו משובח, שנאמד אגב הקרקע, \u0003והלכתא כוותיה דריש גלותא\u0004 \u0005[והלכה כשיטתו של ראש הגולה]\u0006 \u0003בדקלא פרסאה\u0004 \u0005[בדקל פרסי]\u0006 שהוא משובח, ויש לו חשיבות לעצמו, ואין מעריכים אותו אגב הקרקע.","ובענין זה מסופר: \u0003אליעזר זעירא\u0004 \u0005[הקטן]\u0006"],["\u0003הוה סיים מסאני אוכמי\u0004 \u0005[היה נועל נעליים שחורות]\u0006 שלא כמנהג ישראל, \u0003וקאי בשוקא\u0004 \u0005[ועומד בשוק]\u0006 של \u0003נהרדעא, אשכחוהו דבי ריש גלותא\u0004 \u0005[מצאוהו\u0006 אנשי \u0005בית ראש הגולה]\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מאי שנא הני מסאני\u0004 \u0005[מדוע שונים\u0006 \u0005נעליים אלה]\u0006 שאתה נועל? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דקא מאבילנא\u0004 \u0005[שאני מתאבל]\u0006 על \u0003ירושלים\u0004 ומשום כך נועל אני נעליים שחורים, שכן דרך האבלים בלבושים שחורים. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 וכי \u0003את חשיבת לאיתאבולי\u0004 \u0005[אתה\u0006 אדם \u0005חשוב\u0006 מספיק כדי \u0005להתאבל]\u0006 בפרהסיה על \u0003ירושלים? סבור יוהרא הוה\u0004 \u0005[חשבו\u0006 ש\u0005גאוה\u0006 סתם \u0005היא],\u0006 וכיון שנוהג שלא כמנהג ישראל \u0003אתיוה וחבשוה\u0004 \u0005[הביאוהו\u0006 לבית הסוהר \u0005ואסרוהו\u0006 שם כעונש\u0005].\u0006","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003גברא רבה אנא\u0004 \u0005[אדם גדול אני],\u0006 כלומר, תלמיד חכם אני הראוי להתאבל על ירושלים בפרהסיה. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מנא ידעינן\u0004 \u0005[מניין אנו יודעים]\u0006 שכן הוא? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003או אתון בעו מינאי מילתא\u0004 \u0005[אתם תשאלו אותי דבר]\u0006 ואענה לכם, \u0003או אנא איבעי מינייכו מילתא\u0004 \u0005[אני אשאל אתם דבר].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003בעי את\u0004 \u0005[שאל אתה].\u0006","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003האי מאן דקץ כופרא\u0004 \u0005[מי שקוצץ תמרי בוסר]\u0006 של חבירו \u0003מאי\u0004 \u0005[מה]\u0006 \u0003משלם? אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003משלם דמי כופרא\u0004 \u0005[תמרי בוסר].\u0006 אמר להם: \u0003והא הוו תמרי\u0004 \u0005[והרי יהיו\u0006 בסופו של דבר \u0005תמרים\u0006 בשלים\u0005]\u0006 ונמצא שהפסיד אותם יותר! \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 אם כן \u0003משלם דמי תמרי\u0004 \u0005[תמרים].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003והא לאו תמרי שקל מיניה\u0004 \u0005[והרי לא תמרים לקח ממנו]\u0006 וכיצד נחייב אותו בנזק על דבר שלא עשה?","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 אם כן \u0003אימא לן את\u0004 \u0005[אמור לנו אתה].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 מעריכים את הנזק אגב הקרקע \u0003בששים\u0004 כיוצא בו. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מאן אמר כוותיך\u0004 \u0005[מי אומר כמותך]\u0006 שיוכיח שאתה צודק? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003שמואל חי ובית דינו קיים,\u0004 יכולים אתם לשאול אותו. \u0003שדרו קמיה\u0004 \u0005[שלחו לפני]\u0006 \u0003שמואל\u0004 את הבעיה ומה שפסק אליעזר זעירא, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003שפיר קאמר לכו\u0004 \u0005[יפה אמר לכם]\u0006 כי \u0003בששים\u0004 מעריכים, \u0003ו\u0004כיון ששמעו כך הבינו שאדם גדול הוא \u0003ושבקוהו\u0004 \u0005[והניחוהו].\u0006","שנינו במשנה ש\u0003ר' שמעון אומר: אכלה פירות גמורים\u0004 משלם מחיר של פירות גמורים לעצמם, ואין מחשבים את מחירם אגב הקרקע. ומבררים: \u0003מאי טעמא\u0004 \u0005[מה טעם,\u0006 מקור, הדבר\u0005]?\u0006 שכן \u0003הא דאמר רחמנא\u0004 \u0005[זה שאמרה התורה]\u0006 \u0003\"ובער בשדה אחר\"\u0004 (שמות כב, ד) וכתוב זה \u0003מלמד ששמין\u0004 (מעריכים) \u0003על גב השדה,\u0004 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא ב\u0003מידי\u0004 \u0005[\u0006ב\u0005דבר],\u0006 בפירות, ש\u0003צריך לשדה\u0004 כדי לגדול בו, ואילו \u0003הני\u0004 \u0005[אלה]\u0006 הפירות הגמורים \u0003כיון\u0004 ש\u0003לא צריכי\u0004 \u0005[צריכים]\u0006 \u0003לשדה\u0004 — \u0003בעינייהו בעי שלומי\u0004 \u0005[בעינם,\u0006 כמות שהם, \u0005צריך לשלם].\u0006","\u0003אמר רב הונא בר חייא אמר ר' ירמיה בר אבא: דן רב\u0004 הלכה למעשה בנושא אחד \u0003כר' מאיר\u0004 למרות שבדרך כלל פוסקים כדעת החולק עליו, \u0003ופסק הלכתא\u0004 \u0005[הלכה]\u0006 לתלמידים \u0003כר' שמעון\u0004 אף שדעתו היא דעת יחיד.","ומסבירים: \u0003דן רב\u0004 עצמו \u0003כר' מאיר, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 שדה שייחד הבעל לאחריות לגביית כתובתה של אשתו, ורצה אחר כך הבעל למוכרו. אם \u0003כתב\u0004 הבעל ומכר את השדה \u0003לראשון ולא חתמה לו\u0004 אשתו שהיא מאשרת את הדבר, והתבטלה המכירה, ואחר כך מכר וכתב \u0003לשני וחתמה לו\u0004 — הרי \u0003אבדה\u0004 בכך האשה את \u0003כתובתה,\u0004 שהרי המכירה חלה ושוב אין לה ממה לגבות, אלו \u0003דברי ר' מאיר, ר' יהודה אומר, יכולה היא שתאמר: נחת רוח עשיתי לבעלי\u0004 אבל לא התכוונתי לוותר באמת על זכותי, ועדיין השעבוד קיים, \u0003אתם\u0004 התובעים \u0003מה לכם עלי.\u0004","\u0003ופסק\u0004 רב \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כר' שמעון, כי הא דתנן\u0004 \u0005[כמו זו ששנינו]\u0006 במשנתנו, \u0003ר' שמעון אומר: אכלה פירות גמורין\u0004 — \u0003משלמת פירות גמורין, אם\u0004 אכלה \u0003סאה\u0004 — \u0003סאה, אם\u0004 אכלה \u0003סאתים\u0004 — משלמת \u0003סאתים.\u0004","\u0003המגדיש\u0004 (עושה גדיש) תבואתו \u0003בתוך שדה חבירו שלא ברשות\u0004 בעל השדה, \u0003ואכלתן\u0004 \u0003בהמתו של בעל השדה\u0004 את פירות התבואה — \u0003פטור\u0004 בעל השדה, \u0003ואם הוזקה בהן\u0004 על ידי אכילתה — \u0003בעל הגדיש חייב, ו\u0004אולם \u0003אם הגדיש ברשות\u0004 — הרי \u0003בעל השדה חייב\u0004 בנזק שאירע לתבואה.","ומבררים: \u0003לימא תנן\u0004 \u0005[האם נאמר\u0006 ש\u0005שנינו\u0006 משנה\u0005]\u0006 ש\u0003לא כ\u0004שיטת \u0003רבי, דאי\u0004 \u0005[שאם]\u0006 \u0003כ\u0004שיטת \u0003רבי, האמר\u0004 \u0005[הרי אמר]:\u0006 מי שנתן לחבירו רשות להכניס דברמה לחצירו, אינו חייב באחריותו \u0003עד שיקבל עליו בעל הבית לשמור,\u0004 וכאן הרי לא קיבל עליו לשמור! \u0003אמר רב פפא: הכא בנטר בי דרי עסקינן\u0004 \u0005[כאן בשומר הגרנות עוסקים אנו],\u0006 שאנשים מכניסים את תבואתם לרשותו על מנת שישמור עליה. ש\u0003כיון דאמר ליה\u0004 \u0005[שאומר לו]\u0006 השומר לבעל התבואה: \u0003\"עייל\u0004 \u0005[היכנס]\u0006 \u0003וגדוש\",\u0004 הרי זה כמי שאומר לו \u0003\"עייל ואנטר\u0004 \u0005[היכנס ואשמור]\u0006 \u0003לך\" הוא\u0004 זה.","\u0003השולח את הבערה\u0004 (אש) \u0003ביד חרש שוטה וקטן\u0004 שאינם בני דעת ואינם אחראים למעשיהם, אם נגרם על ידי כך נזק — \u0003פטור בדיני אדם\u0004 שהרי הוא עצמו לא עשה מעשה, \u0003וחייב בדיני שמים,\u0004 שהרי מבחינה מוסרית יש עליו אחריות. \u0003שלח\u0004 את האש \u0003ביד פקח\u0004 וגרם שריפה — השליח \u0003הפקח חייב,\u0004 שאין שליח לדבר עבירה.","ועוד לענין אחריות על בעירה: אם \u0003אחד הביא את האור\u0004 (אש) \u0003ו\u0004אחריו \u0003אחד הביא את העצים\u0004 ומתוך כך יצאה האש והזיקה — \u0003המביא את העצים חייב.\u0004 ולהיפך, \u0003אחד הביא את העצים ו\u0004אחריו \u0003אחד הביא את האור\u0004 — \u0003המביא את האור חייב,\u0004 שהאחרון הגורם לשריפה הוא שחייב.","\u0003בא אחר וליבה\u0004 את האש ומתוך כך יצאה האש והזיקה — \u0003המלבה חייב,\u0004 שהוא האחרון שגרם. \u0003ליבתה הרוח\u0004 את האש — \u0003כולן פטורין\u0004 שהרי הקודמים לא עשו בעצמם את הנזק.","\u0003אמר ריש לקיש משמיה\u0004 \u0005[משמו]\u0006 של \u0003חזקיה: לא שנו\u0004 שהמשלח את האש ביד חרש שוטה וקטן פטור \u0003אלא שמסר לו גחלת וליבה\u0004 אותה החרש עצמו, \u0003אבל\u0004 אם \u0003מסר לו שלהבת\u0004 — \u0003חייב, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003מעשיו\u0004 של המשלח הם \u0003גרמו לו\u0004 במישרין שתהא דליקה.","\u0003ור' יוחנן אמר: אפילו מסר לו שלהבת\u0004 — \u0003פטור, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003צבתא\u0004 \u0005[אחיזתו]\u0006 של ה\u0003חרש\u0004 \u0003גרמה לו,\u0004 שהרי סתם שלהבת אינה גורמת דליקה, \u0003ו\u0004המשלח את החרש \u0003לא מחייב\u0004 \u0005[חייב]\u0006 בנזקים שגרם \u0003עד שימסור לו גווזא\u0004 \u0005[ענפים]\u0006"],["\u0003סלתא\u0004 \u0005[עצים דקים],\u0006 \u0003שרגא\u0004 \u0005[\u0006ו\u0005נר],\u0006 \u0003דההוא\u0004 \u0005[שבזה]\u0006 \u0003ודאי\u0004 ה\u0003מעשה דידיה\u0004 \u0005[שלו\u0006 של המשלח\u0005]\u0006 הם ש\u0003גרמו\u0004 לשריפה.","שנינו במשנה שאם \u0003שלח\u0004 את הבערה \u0003ביד פקח\u0004 — \u0003הפקח חייב,\u0004 ואם בא אחר וליבה — המלבה חייב. \u0003אמר רב נחמן בר יצחק: מאן דתני\u0004 \u0005[מי ששונה]\u0006 בנוסח המשנה \u0003\"ליבה\" לא משתבש\u0004 \u0005[טועה],\u0006 \u0003ומאן דתני\u0004 \u0005[ומי ששונה]\u0006 \u0003\"ניבה\" לא משתבש\u0004 \u0005[טועה].\u0006 ומוכיח שלשתי המילים יש משמע של הפחת אש.","\u0003מאן דתני\u0004 \u0005[מי ששונה]\u0006 \u0003\"ליבה\" לא משתבש\u0004 \u0005[טועה],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בלבת אש\"\u0004 (שמות ג, ב), \u0003ומאן דתני\u0004 \u0005[ומי ששונה]\u0006 \u0003\"ניבה\" לא משתבש,\u0004 \u0005[טועה]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בורא ניב שפתים\"\u0004 (ישעיה נז, יט), כלומר, דבר היוצא מן השפתים, אויר, וכן הוא ליבוי האש, הנעשה על ידי הפחת אויר באש.","שנינו במשנה שאם \u0003לבתה הרוח\u0004 — \u0003כולן פטורין.\u0004 ומשמע — אף מי שליבה את האש עם הרוח. ובפירוט הדברים מביאים את מה ששנינו בברייתא, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ליבה\u0004 הוא \u0003ולבתה הרוח, אם יש בלבויו\u0004 בלבד \u0003כדי ללבותה\u0004 — \u0003חייב\u0004 בנזקי האש, שהרי הרוח היתה רק מסייעת וגם בלעדיה היה די בליבויו. \u0003ואם לאו\u0004 \u0005[לא]\u0006 שאין ליבויו מספיק — \u0003פטור.\u0004","ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 יהא פטור אם אין בליבויו כדי ללבותה? \u0003ליהוי\u0004 \u0005[שיהא]\u0006 זה \u0003כזורה\u0004 תבואה בשבת \u0003ורוח מסייעתו,\u0004 שחייב על כך משום מלאכה בשבת אף על פי שהרוח מסייעת לו ובלעדיה לא היה זורה התבואה!","\u0003אמר אביי: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שליבה\u0004 הוא \u0003מצד אחד, ולבתו הרוח מצד אחר\u0004 והלכה השריפה עם הרוח, שנמצא שלא ליבויו הוא שגרם לשריפה, ולכן הוא פטור. \u0003רבא אמר:\u0004 כאן מדובר \u0003כגון שליבה\u0004 הוא \u0003ברוח מצויה\u0004 ולא היה בליבוי זה כדי ללבות האש ולהבעיר, \u0003ולבתו הרוח ברוח שאינה מצויה\u0004 ופטור, שכן לא היה לו להעלות על דעתו שכך יהיה. \u0003ר' זירא אמר:\u0004 כאן מדובר \u0003כגון דצמרה צמורי\u0004 \u0005[ש\u0006רק \u0005נפח מעט על האש],\u0006 ואין זה ליבוי גמור.","\u0003רב אשי אמר:\u0004 \u0003כי אמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006 שחייב \u0003זורה ורוח מסייעתו\u0004 — \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003לענין שבת,\u0004 שבענין שבת כלל הוא ש\u0003מלאכת מחשבת אסרה תורה,\u0004 ואין הדבר תלוי בטיבה או בגודלה של המלאכה, כי אם בצד היצירה והמחשבה שלו. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בנזקים \u0003גרמא בעלמא\u0004 \u0005[גורם בלבד]\u0006 \u0003הוא, וגרמא בנזקין פטור\u0004 כל עוד לא עשה מעשה גמור.","\u0003השולח את הבערה, ואכלה\u0004 האש \u0003עצים או אבנים או עפר\u0004 שנתקלקלו על ידי השריפה — הרי זה \u0003חייב, שנאמר: \"כי תצא אש ומצאה קצים ונאכל גדיש או הקמה או השדה שלם ישלם המבער את הבערה\"\u0004 (שמות כב, ה), לומר שגם על השחתת השדה עצמו חייב המבעיר.","ובפירוש הפסוק שהובא במשנה \u0003אמר רבא: למה לי\u0004 (לאיזה ענין נצרך) \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003\"קוצים\" \"גדיש\" \"קמה\" ו\"שדה\",\u0004 שלכאורה הם דוגמאות מיותרות?","ומסביר: \u0003צריכי\u0004 \u0005[נצרכו]\u0006 כולם להיאמר, \u0003דאי כתב רחמנא\u0004 \u0005[שאילו כתבה התורה]\u0006 \u0003\"קוצים\"\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003קוצים הוא דחייב רחמנא\u0004 \u0005[שחייבה התורה],\u0006 \u0003משום דשכיח\u0004 \u0005[שמצויה]\u0006 \u0003אש גבייהו\u0004 \u0005[אצלם],\u0006 \u0003ושכיח דפשע\u0004 \u0005[ומצוי\u0006 הדבר \u0005ש\u0006האדם \u0005פושע]\u0006 וגורם ברשלנותו לדבר זה, \u0003אבל גדיש\u0004 ש\u0003לא שכיח\u0004 \u0005[מצויה]\u0006 \u0003אש גבייהו\u0004 \u0005[אצלם]\u0006 אצל ערימות התבואה, \u0003ולא שכיח דפשע\u0004 \u0005[מצוי\u0006 הדבר \u0005ש\u0006האדם \u0005פושע]\u0006 בכך — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יתחייב. \u0003ואי כתב רחמנא\u0004 \u0005[ואילו כתבה התורה]\u0006 \u0003\"גדיש\"\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 דווקא \u0003גדיש חייב רחמנא\u0004 \u0005[חייבה התורה],\u0006 \u0003משום\u0004 ש\u0003הפסד מרובה הוא, אבל\u0004 שריפת \u0003קוצים\u0004 ש\u0003הפסד מועט\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן השמיע לנו הכתוב שאפילו על נזקי קוצים חייב.","המלה \u0003\"קמה\" למה לי\u0004 — ללמד: \u0003מה קמה\u0004 שהיא \u0003בגלוי, אף כל\u0004 דבר ש\u0003בגלוי\u0004 חייב עליו המבעיר, ואילו על דברים שהיו טמונים ושרפתם האש — אין המבעיר חייב עליהם.","ושואלים: \u0003ול\u0004שיטת \u0003ר' יהודה\u0004 ש\u0003מחייב\u0004 גם על \u0003נזקי טמון באש,\u0004 המלה \u0003\"קמה\" למה לי?\u0004 ומשיבים: לדעתו באה המלה \"קמה\" \u0003לרבות כל בעלי קומה,\u0004 שאין הכתוב מחייב רק תבואה אלא כל דבר העומד, אף אילנות, ואפילו בעלי חיים. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שלמדו ממלה זו לדין טמון, \u0003לרבות כל בעלי קומה מנא להו\u0004 \u0005[מניין להם]?\u0006 ומשיבים: \u0003נפקא להו\u0004 \u0005[יוצא להם]\u0006 הדבר \u0003מ\u0004מה שנאמר \u0003\"או הקמה\",\u0004 ו\"או\" זה לשון ריבוי הוא.","ושואלים: \u0003ור' יהודה\u0004 כיצד מפרש הוא את המלה \u0003\"או\"?\u0004 ומסבירים: \u0003מיבעי ליה\u0004 \u0005[צריך\u0006 הוא \u0005אותו]\u0006 כדי \u0003לחלק,\u0004 שעל כל אחד מאלה המנויים בתורה הוא חייב, שאם לא כן היינו אומרים שרק אם שרפה האש את כל אלה ביחד חייב לשלם. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 דין זה \u0003לחלק מנא להו\u0004 \u0005[מניין להם]?\u0006 ומשיבים: \u0003נפקא להו\u0004 \u0005[יוצא,\u0006 נלמד \u0005להם]\u0006 דבר זה \u0003מ\u0004\"או\" אחר, שנאמר \u0003\"או השדה\".\u0004","ושואלים: \u0003ור' יהודה,\u0004 מה הוא לומד מ\"או השדה\"? ומשיבים: \u0003איידי דכתב רחמנא\u0004 \u0005[מתוך שכתבה התורה]\u0006 \u0003\"או הקמה\",\u0004 \u0003כתב\u0004 \u0005[כתבה]\u0006 גם כן \u0003\"או השדה\",\u0004 ויש בזה רק משום יפוי הלשון, ואין ללמוד דבר מסויים לגופו של ביטוי זה.","וממשיך רבא בביאור חלקי הפסוק: \u0003\"שדה\" למה לי\u0004 — \u0003לאתויי\u0004 \u0005[להביא\u0006 לרבות\u0005]\u0006 \u0003לחכה\u0004 האש את \u0003נירו\u0004 (השדה החרוש שלו) \u0003וסכסכה\u0004 (חרכה) את \u0003אבניו,\u0004 שגם על נזקים אלה חייב לשלם. ושואלים: \u0003ולכתוב רחמנא\u0004 \u0005[ושתכתוב התורה]\u0006 \u0003\"שדה\" ולא בעי הנך\u0004 \u0005[נצטרך\u0006 את \u0005אלה]!\u0006 שאם על נזקי שדה שאינו מתכלה בשריפה חייב, לא כל שכן על נזקים אחרים! ומשיבים: \u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להיאמר: \u0003דאי כתב רחמנא\u0004 \u0005[שאילו כתבה התורה]\u0006 \u0003\"שדה\"\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003מה שבשדה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שחייב על הכל.","אגב הדברים שאמרנו מביאים מדרש אגדה ש\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: אין פורענות באה לעולם אלא בזמן שהרשעים בעולם,\u0004 שבגללם היא באה, \u0003ו\u0004בכל זאת \u0003אינה מתחלת אלא מן הצדיקים תחלה, שנאמר: \"כי תצא אש ומצאה קצים\"\u0004 (שמות כב, ה), \u0003אימתי אש יוצאה\u0004 — \u0003בזמן שקוצים מצוין לה,\u0004 ואף הפורענות אינה באה אלא כשיש רשעים שהם כקוצים, \u0003ו\u0004אולם \u0003אינה מתחלת אלא מן הצדיקים תחלה, שנאמר \"ונאכל גדיש\",\u0004 ונדייק בלשון: \u0003\"ואכל גדיש\" לא נאמר, אלא \"ונאכל גדיש\",\u0004 לומר \u0003שנאכל גדיש כבר\u0004 שעוד לפני שנשרפו כל הקוצים כבר נשרף הגדיש, שהוא עיקר התבואה שבשדה.","וכיוצא בו \u0003תאני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף\u0004 ברייתא זו: \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 במכת בכורות: \u0003\"ואתם לא תצאו איש מפתח ביתו עד בקר\"\u0004 (שמות יב, כב) מדוע נאמר הדבר אף לישראל שלא נגזרה עליהם פורענות זו כלל? כי \u0003כיון שניתן רשות למשחית\u0004 להרוג \u0003אינו מבחין בין צדיקים לרשעים\u0004 ופוגע באלו ובאלו, \u0003ולא עוד, אלא שמתחיל מן הצדיקים תחלה, שנאמר: \"והכרתי ממך צדיק ורשע\"\u0004 (יחזקאל כא, ח) וצדיק נזכר בפסוק קודם לרשע.","\u0003בכי\u0004 \u0005[בכה]\u0006 \u0003רב יוסף: כולי האי נמי\u0004 \u0005[כל אלה גם כן]\u0006 הצדיקים \u0003לאין דומים\u0004 בזמן הפורענות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: טיבותא הוא לגבייהו\u0004 \u0005[\u0006דבר \u0005טוב הוא עבורם]\u0006 לצדיקים שמתים תחילה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי מפני הרעה נאסף הצדיק\"\u0004 (ישעיה נז, א), כדי שלא יסבול בסבל שבראיית רעת עמו.","ועוד בעניינים אלה: \u0003אמר רב יהודה אמר רב:\u0004"],["\u0003לעולם יכנס אדם\u0004 הנמצא בדרך לעיר \u0003ב\"כי טוב\",\u0004 כלומר, בעוד החמה זורחת ויש אור, (כאמור: \"וירא... את האור כי טוב\". בראשית א, ד), \u0003ו\u0004כן \u0003יצא\u0004 מן העיר לדרך \u0003ב\"כי טוב\", שנאמר\u0004 במכת בכורות במצרים: \u0003\"ואתם לא תצאו איש מפתח ביתו עד בקר\"\u0004 (שמות יב, כב), לומר שאין ראוי להיות בחוץ בלילה שהוא עת סכנה.","ועוד מביאים, אגב דברים אלה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מגיפת \u0003דבר בעיר\u0004 — \u0003כנס רגליך,\u0004 כלומר, מעט ביציאה מן הבית, \u0003שנאמר: \"ואתם לא תצאו איש מפתח ביתו עד בקר\"\u0004 (שמות יב, כב), \u0003ואומר\u0004 כיוצא בו: \u0003\"לך עמי בא בחדריך וסגר דלתך בעדך\u0004 חבי כמעט רגע עד יעבור זעם\u0003\"\u0004 (ישעיהו כו, כ), \u0003ואומר: \"מחוץ תשכל חרב ומחדרים אימה\"\u0004 (דברים לב, כה).","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 צורך להביא \u0003\"ואומר\"\u0004 פסוקים נוספים לראיה, כאשר לכאורה אפשר ללמוד הנהגה זו מפסוק ראשון בלבד? ומסבירים: גם כשהבאנו את הפסוק הראשון \"ואתם לא תצאו... עד בקר\", יש מקום לשאול: \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים שלא יצא דווקא \u0003בליליא\u0004 \u0005[בלילה]\u0006 כאשר המשחית בעיר, \u0003אבל ביממא\u0004 \u0005[ביום]\u0006 — \u0003לא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מה שנאמר בכתוב \u0003\"לך עמי בא בחדריך וסגור דלתך\".\u0004","ואף על פסוק זה יש מקום לשאול: \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003היכא דליכא\u0004 \u0005[במקום שאין]\u0006 \u0003אימה מגואי\u0004 \u0005[מבפנים],\u0006 ולכן ראוי להתחבא בבית. \u0003אבל היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003אימה מגואי\u0004 \u0005[מבפנים],\u0006 \u0003כי נפיק יתיב ביני אינשי בצוותא בעלמא טפי מעלי\u0004 \u0005[כאשר\u0006 האדם \u0005יוצא ויושב בין אנשים בחברה כללית\u0006 — \u0005טוב\u0006 הדבר \u0005יותר],\u0006 על כן \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מן הכתוב \u0003\"מחוץ תשכל חרב ומחדרים אימה\"\u0004 לומר: \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003מחדרים אימה,\u0004 מכל מקום \u0003מחוץ תשכל חרב,\u0004 ומוטב להישאר בבית.","ומסופר: \u0003רבא בעידן רתחא הוי סכר כוי\u0004 \u0005[בזמן דבר, היה סוגר\u0006 את \u0005חלונות\u0006 ביתו\u0005]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי עלה מות בחלונינו\"\u0004 (ירמיה ט, כ).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם יש \u0003רעב בעיר\u0004 — \u0003פזר רגליך,\u0004 כלומר, סע מן העיר, שלא תמצא פתרון לדבר במקומך, \u0003שנאמר: \"ויהי רעב בארץ וירד אברם מצרימה לגור שם\"\u0004 (בראשית יב, י), \u0003ואומר\u0004 כיוצא בו: \u0003\"אם אמרנו נבוא העיר והרעב בעיר ומתנו שם\"\u0004 (מלכים ב ז, ד).","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003\"ואומר\",\u0004 לשם מה מביא את הפסוק הנוסף? ומסבירים: אף שהבאנו את הכתוב מאברהם שירד בזמן הרעב למצרים, יש מקום לומר, \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שצריך לצאת מן המקום אמורים דווקא \u0003היכא דליכא\u0004 \u0005[במקום שאין]\u0006 \u0003ספק\u0004 סכנת \u0003נפשות\u0004 מחוץ למקום בו הוא נמצא. \u0003אבל היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003ספק\u0004 סכנת \u0003נפשות\u0004 מחוץ לעיר — \u0003לא\u0004 יצא, לכן \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מה שנאמר שם \u0003\"לכו ונפלה אל מחנה ארם אם יחינו נחיה\"\u0004 (מלכים ב ז, ד), ללמד שאף כשיש סכנת נפשות במקום אחר מוטב לברוח לשם מפני הרעב.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם יש \u0003דבר בעיר\u0004 — \u0003אל יהלך אדם באמצע הדרך, מפני שמלאך המות מהלך\u0004 אז \u0003באמצע הדרכים,\u0004 ש\u0003כיון דיהיבא ליה רשותא מסגי להדיא\u0004 \u0005[שניתנה לו רשות\u0006 למשול בעיר הרי הוא \u0005הולך למישרין]\u0006 ולא בצדדים. לעומת זאת אם \u0003שלום\u0004 ושקט \u0003בעיר\u0004 — \u0003אל יהלך בצדי דרכים,\u0004 ש\u0003כיון דלית ליה רשותא, מחבי חבויי ומסגי\u0004 \u0005[שכיון שאין לו\u0006 למלאך המוות \u0005רשות\u0006 לשלוט, הוא \u0005מתחבא והולך\u0006 בצד\u0005].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם יש \u0003דבר בעיר\u0004 — \u0003אל יכנס אדם יחיד לבית הכנסת, שמלאך המות מפקיד שם כליו,\u0004 ומשום כך הוא מקום מסוכן. ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 שלא יכנס לבית הכנסת אמורים \u0003היכא דלא קרו ביה דרדקי\u0004 \u0005[במקום שאין לומדים בו התינוקות מקרא]\u0006 \u0003ולא מצלו ביה\u0004 \u0005[מתפללים בו]\u0006 \u0003עשרה,\u0004 אבל אם היו בו דברים אלה — אין הוא מקום סכנה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם היו ה\u0003כלבים בוכים\u0004 בלי סיבה — סימן שהם מרגישים ש\u0003מלאך המות בא לעיר, כלבים משחקים\u0004 משמע ש\u0003אליהו הנביא בא לעיר.\u0004 ומעירים: \u0003והני מילי דלית בהו\u0004 \u0005[ודברים אלה\u0006 אמורים כ\u0005שאין ביניהם]\u0006 \u0003נקבה,\u0004 שבזמן שיש ביניהם נקיבה בגללה שוחקים הם.","מסופר: \u0003יתיב\u0004 \u0005[ישבו]\u0006 \u0003רב אמי ורב אסי קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יצחק נפחא\u0004 \u0005[הנפח]\u0006 \u0003מר אמר ליה\u0004 \u0005[חכם זה אמר לו]:\u0006 \u0003לימא מר שמעתתא\u0004 \u0005[יאמר אדוני\u0006 דבר \u0005הלכה],\u0006 \u0003ומר אמר ליה\u0004 \u0005[וחכם זה אמר לו]:\u0006 \u0003לימא מר אגדתא\u0004 \u0005[יאמר אדוני\u0006 דבר \u0005אגדה],\u0006 \u0003פתח\u0004 ורצה \u0003למימר אגדתא\u0004 \u0005[לומר אגדה]\u0006 \u0003ולא שביק מר\u0004 \u0005[הניח\u0006 לו \u0005חכם זה],\u0006 \u0003פתח למימר שמעתתא\u0004 \u0005[לומר הלכה]\u0006 \u0003ולא שביק מר\u0004 \u0005[הניח\u0006 לו \u0005חכם זה].\u0006","\u0003אמר להם: אמשול לכם משל, למה הדבר דומה?\u0004 — \u0003לאדם שיש לו שתי נשים, אחת ילדה\u0004 (צעירה) \u0003ואחת זקינה. ילדה מלקטת לו\u0004 שערות \u0003לבנות\u0004 מתוך שערו כדי שייראה צעיר, ואילו ה\u0003זקינה מלקטת לו שחורות\u0004 מתוך שערו כדי שלא ייראה צעיר ממנה, ועל ידי שתיהן \u0003נמצא קרח מכאן ומכאן,\u0004 וכך אתם גורמים שלא אומר דבר.","\u0003אמר להן: אי הכי\u0004 \u0005[אם כך]\u0006 שאין אחד מכם מוכן לוותר, \u0003אימא לכו מלתא דשויא לתרוייכו\u0004 \u0005[אומר לכם דבר השווה לשניכם],\u0006 שיש בו גם הלכה וגם אגדה, על הכתוב \u0003\"כי תצא אש ומצאה קצים\"\u0004 יש לשאול: \u0003\"תצא\"\u0004 משמעו לכאורה שתצא האש \u0003מעצמה\u0004 ולא שהבעירה אדם, ומצד שני נאמר בהמשך הפסוק \u0003\"שלם ישלם המבער את הבערה\",\u0004 ומשמע שדווקא אם אדם הבעיר את האש — עליו לשלם. ויש לפרשו כך, \u0003אמר הקדוש ברוך הוא:\u0004 הגם שהבעירה יצאה מהם בגלל חטאיהם, \u0003עלי לשלם את הבערה שהבערתי.\u0004","\u0003אני הציתי אש בציון, שנאמר:\u0004 \u0003\"\u0004כלה ה' את חמתו... \u0003ויצת אש בציון ותאכל יסדתיה\"\u0004 (איכה ד, יא), \u0003ואני עתיד לבנותה באש, שנאמר: \"ואני אהיה לה\u0004 נאום ה' \u0003חומת אש סביב ולכבוד אהיה בתוכה\"\u0004 (זכריה ב, ט).","\u0003שמעתתא\u0004 \u0005[\u0006דבר \u0005הלכה]\u0006 שיש ללמוד מפסוק זה — \u0003פתח הכתוב\u0004 כאן \u0003ב\u0004לשון השייכת ל\u0003נזקי ממונו\u0004 \"כי תצא אש\", כדרך שבהמתו של אדם ההולכת ומזיקה, \u0003וסיים בנזקי גופו\u0004 (\"המבעיר את הבערה\"), משמע שהנזק מיוחס אליו כמי שעשה בגופו, \u0003לומר לך:\u0004 חיוב שחייב אדם על \u0003אשו\u0004 הרי הוא \u0003משום חציו,\u0004 כלומר, המשלח את האש הרי הוא כיורה חצים, שהוא ככוחו, ולא כנזק של ממונו.","ועוד דבר אגדה הקשור קצת בעניינים אלה, נאמר: \u0003\"ויתאוה דוד ויאמר מי ישקני מים מבאר בית לחם אשר בשער. ויבקעו שלשת הגבורים במחנה פלשתים וישאבו מים מבאר בית לחם אשר בשער\"\u0004 (שמואל ב כג, טו –טז) ונראה לחכמים שלא יתכן לפרש כפשוטו שרצה דוד לשם תאוותו לשתות מים. אלא \"מים\" האמורים כאן רמז הם לתורה, שמתחבט היה בשאלה בהלכה ולא יכול היה למצוא את פתרונה,","ושאלו: \u0003מאי קא מיבעיא ליה\u0004 \u0005[מה\u0006 היתה אותה השאלה ש\u0005נשאלה לו]?\u0006 \u0003אמר רבא אמר רב נחמן:\u0004 השאלה בדבר חיובו של אדם על נזקים של דבר \u0003טמון באש קמיבעיא ליה\u0004 \u0005[נשאלה לו],\u0006 ולא ידע דוד המלך \u0003אי\u0004 \u0005[אם]\u0006 לפסוק \u0003כ\u0004אותה שיטה של \u0003ר' יהודה\u0004 שחייב על כך, \u0003אי כרבנן\u0004 \u0005[אם כ\u0006שיטת \u0005חכמים],\u0006 \u0003ופשטו ליה מאי דפשטו ליה\u0004 \u0005[ופתרו לו מה שפתרו לו],\u0006 שהביאו תשובה לכך מן החכמים שבבית לחם.","\u0003רב הונא אמר:\u0004 כך היה מעשה, \u0003גדישים\u0004 של \u0003שעורים\u0004 של \u0003ישראל הוו\u0004 \u0005[היו\u0006 שם\u0005]\u0006 \u0003דהוו מטמרי\u0004 \u0005[שהיו מתחבאים]\u0006 \u0003פלשתים בהו\u0004 \u0005[בהם],\u0006 והדרך להינצל מהם היתה בשריפת הגדישים הללו עליהם, \u0003וקא מיבעיא ליה\u0004 \u0005[ונשאלה לו\u0006 לדוד\u0005]\u0006 שאלה זו: \u0003מהו להציל עצמו בממון חבירו,\u0004 ולמעשה — האם מותר לו לשרוף את הגדישים הללו כדי להציל עצמו מסכנה.","\u0003שלחו ליה\u0004 \u0005[לו]\u0006 חכמים בתשובה על כך: אמנם ככלל \u0003אסור\u0004 לאדם \u0003להציל עצמו בממון חבירו, אבל אתה מלך אתה, ו\u0004כלל הוא ש\u0003מלך פורץ\u0004 גדרות של אנשים על מנת \u0003לעשות לו דרך\u0004 לצרכי מלכותו \u0003ואין מוחין בידו\u0004 ומשום כוח המלכות מותר לך.","\u0003ו\u0004אילו \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רבה בר מרי, אמרו:\u0004 מעשה שהיה כך היה, \u0003גדישים\u0004 של \u0003שעורין\u0004 של \u0003ישראל הוו\u0004 \u0005[היו]\u0006 \u0003וגדישין\u0004 של \u0003עדשים\u0004 של \u0003פלשתים\u0004 היו שם, שזמן הקציר היה אז, כנאמר שם \"ויבאו אל קציר אל דוד\" (שמואל ב, כג, יג), \u0003וקא מיבעיא להו\u0004 \u0005[ונשאלה להם]\u0006 שאלה זו: \u0003מהו\u0004 הדין, האם מותר \u0003ליטול גדישין של שעורין\u0004 של \u0003ישראל ליתן לפני בהמתו, על מנת לשלם\u0004 להם אחר כך מתוך ה\u0003גדישין של עדשים\u0004 השייכים ל\u0003פלשתים?\u0004","\u0003שלחו ליה\u0004 \u0005[לו]\u0006 תשובה כעין דברי הכתוב: \u0003\"חבל ישיב רשע גזלה ישלם\"\u0004 (יחזקאל לג, טו), לומר: \u0003אף על פי שגזילה\u0004 שגזל \u0003משלם\u0004 — \u0003רשע הוא,\u0004 ומכאן שאסור לאדם לגזול אף אם כוונתו לשלם לאחר מכן, \u0003אבל אתה מלך אתה, ומלך פורץ לעשות לו דרך ואין מוחין בידו.\u0004","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שהיתה השאלה האם רשאי \u0003לאחלופי\u0004 \u0005[להחליף]\u0006 גדיש בגדיש, \u0003היינו דכתיב חד קרא\u0004 \u0005[זהו שכתוב\u0006 ב\u0005פסוק אחד]:\u0006 \u0003\"ותהי שם חלקת השדה מלאה עדשים\"\u0004 (שמואל ב כג, יא), \u0003וכתיב חד קרא\u0004 \u0005[וכתוב פסוק אחר]:\u0006 \u0003\"ותהי חלקת השדה מלאה שעורים\"\u0004 (דברי הימים א יא, יג), ובדרך זו מיישבים את ההבדל בין הפסוקים, ששתי שדות היו, שדה השעורים של ישראל היתה, והשדה האחרת של העדשים של פלשתים היתה.","\u0003אלא למאן דאמר למקלי, מאי איבעיא להו להני תרי קראי\u0004 \u0005[ל\u0006דעת \u0005מי שאומר ש\u0006השאלה היתה אם \u0005לשרוף\u0006 אותם, לשם \u0005מה צריכים את שני הפסוקים\u0006 הסותרים \u0005הללו]?\u0006 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 בעל שיטה זו: \u0003דהוו נמי\u0004 \u0005[שהיו\u0006 שם \u0005גם]\u0006 \u0003גדישים\u0004 של \u0003עדשים\u0004 של \u0003ישראל דהוו מיטמרו בהו\u0004 \u0005[שהיו נחבאים בהם]\u0006 \u0003פלשתים,\u0004 כלומר, שני הדברים נכונים, שגם שעורים וגם עדשים היו שם.","ושואלים עוד: \u0003בשלמא למאן דאמר למקלי\u0004 \u0005[נניח ל\u0006שיטתו של \u0005מי שאומר ש\u0006היתה השאלה אם \u0005לשרוף]\u0006 \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"ויתיצב בתוך החלקה ויצילה\"\u0004 (שמואל ב כג, יב), שהתשובה היתה כי מעיקר הדין אסור לשרוף אותה על מנת להציל עצמו. \u0003אלא למאן דאמר לאחלופי\u0004 \u0005[ל\u0006דעת \u0005מי שאומר ש\u0006היתה השאלה אם \u0005להחליף],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"ויצילה\"?\u0004 הרי לא היה כאן נזק צפוי לשדה!","ומשיבים: ש\u0003לא שבק להו לאחלופי\u0004 \u0005[הניח להם להחליף אותה].\u0006","ועוד שואלים: \u0003בשלמא הני תרתי, היינו דכתיב תרי קראי\u0004 \u0005[נניח\u0006 לפי \u0005שתי\u0006 שיטות הסבר \u0005אלה זהו\u0006 הטעם \u0005שכתובים שני פסוקים],\u0006 או משום שמדובר בהחלפה של שעורים ועדשים, או משום שאכן נשאלו שתי שאלות שונות."],["\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003טמון באש קמיבעיא ליה\u0004 \u0005[נסתפק לו]\u0006 לדוד, \u0003מאי איבעי ליה קראי\u0004 \u0005[מה הוצרכו לו הכתובים]\u0006 הללו העוסקים בחלקת השדה? והרי אין באותו ענין שום דבר המרמז על טמון באש! ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה חכם זה \u0005לומר]\u0006 \u0003לך:\u0004 \u0003טמון וחדא מהנך קמיבעיא ליה\u0004 \u0005[ואחת מ\u0006השאלות \u0005האלה\u0006 שהוזכרו מקודם \u0005נשאלה לו],\u0006 והרי לפי כל אחת מהשאלות האחרות יש צורך באותם כתובים.","ומעירים: \u0003בשלמא למאן דאמר הני תרתי\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר שתי אלה],\u0006 שהשאלה היתה אם להחליף או לשרוף — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"ולא אבה (דוד) לשתותם\"\u0004 (שמואל ב כג, טז), וכך יש להבין: \u0003אמר\u0004 דוד, \u0003כיון דאיכא איסורא\u0004 \u0005[שיש איסור]\u0006 בדבר \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי\u0004 הדבר לעשות זאת, אף שכמלך רשאי אני לעשותו. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003טמון באש קא מבעיא ליה\u0004 \u0005[נסתפק לו],\u0006 \u0003מכדי גמרא\u0004 \u0005[הרי הלכה]\u0006 \u0003הוא\u0004 ש\u0003שלחו ליה\u0004 \u0005[לו],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 אם כן פירוש \u0003\"לא אבה דוד לשתותם\"?\u0004","ומשיבים: אמנם קיבל דוד את ההלכה אלא ש\u0003לא אמרינהו משמייהו\u0004 \u0005[אמר אותם משמם]\u0006 של אלה שהלכו ומסרוה, ש\u0003אמר: כך מקובלני מבית דינו של שמואל הרמתי\u0004 הנביא: \u0003כל המוסר עצמו למות על דברי תורה,\u0004 אף שדבר גדול עשה — \u0003אין אומרים דבר הלכה משמו,\u0004 שלא יבואו אחרים אף הם להסתכן בכך.","ועוד מבררים: נאמר שם \u0003\"ויסך אתם לה'\", בשלמא למאן דאמר הני תרתי\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר\u0006 כי \u0005שתי\u0006 הבעיות \u0005הללו]\u0006 אם רשאי להחליף או לשרוף הן שנשאלו, יש להסביר שנאמר כך \u0003משום דעבד\u0004 \u0005[שעשה]\u0006 \u0003לשם שמים\u0004 ולא השתמש בהיתר שעמד לרשותו. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהשאלה היתה ביחס ל\u0003טמון באש, מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003\"ויסך אתם לה'\"?\u0004 ומסבירים: \u0003דאמרינהו משמא דגמרא\u0004 \u0005[שאמרם\u0006 את הדברים הללו \u0005בשם המסורת]\u0006 בלא ליחסם לאדם מסויים.","\u0003עברה\u0004 האש שהבעיר \u0003גדר שהוא גבוה ארבע אמות,\u0004 והזיקה בשדה חבירו, \u0003או\u0004 עברה \u0003דרך הרבים\u0004 והזיקה בשדה חבירו, \u0003או\u0004 עברה \u0003נהר\u0004 והזיקה בעברו השני — \u0003פטור,\u0004 שהמבעיר אינו חייב על נזקים בלתי רגילים שכאלה.","על דין המשנה בגדר שואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עברה גדר שהוא גבוה ארבע אמות\u0004 — \u0003חייב,\u0004 היפך הדברים במשנה!","\u0003אמר רב פפא:\u0004 אין כאן מחלוקת בהלכה, אלא הבדל של דרך התבטאות שונה. ה\u0003תנא דידן\u0004 \u0005[שלנו],\u0006 במשנתנו, \u0003קא חשיב\u0004 \u0005[מונה]\u0006 את המדות \u0003מלמעלה למטה,\u0004 כיצד? אם עברה האש גדר של \u0003שש אמות\u0004 — \u0003פטור,\u0004 של \u0003חמש אמות\u0004 — \u0003פטור, עד ארבע אמות\u0004 — \u0003פטור.\u0004 ואילו ה\u0003תנא ברא\u0004 \u0005[החיצוני\u0006 של הברייתא\u0005]\u0006 \u0003מלמטה למעלה קא חשיב\u0004 \u0005[הוא מונה]\u0006 וכך מנה: \u0003שתי אמות\u0004 — \u0003חייב, שלש אמות\u0004 — \u0003חייב, עד ארבע אמות\u0004 — \u0003חייב,\u0004 ובארבע אמות עצמן — פטור, וכדברי המשנה. ואין כל הבדל להלכה בין המשנה והברייתא.","\u0003אמר רבא: ארבע אמות\u0004 גובה גדר \u0003שאמרו\u0004 ש\u0003פטור\u0004 — \u0003אפילו בשדה קוצים. אמר רב פפא: ו\u0004הכוונה היא: שגבוהה הגדר \u0003משפת קוצים ולמעלה ארבע אמות.\u0004","\u0003אמר רב: לא שנו\u0004 במשנתנו שפטור אם היתה דרך הרבים מפסיקה, \u0003אלא בקולחת,\u0004 באש המיתמרת כלפי מעלה, \u0003אבל בנכפפת,\u0004 כשהאש מתקדמת על פני הקרקע בכך שנאחזת מדבר לדבר — \u0003אפילו עד מאה אמה חייב\u0004 לפי שהאש שורפת כל דבר שהיא מוצאת. \u0003ושמואל אמר: מתניתין\u0004 \u0005[משנתנו]\u0006 עוסקת \u0003ב\u0004אש \u0003נכפפת, אבל ב\u0004אש \u0003קולחת\u0004 — \u0003אפילו\u0004 דרך שרוחבה \u0003כל שהוא\u0004 (משהו) שמפרידה — \u0003פטור.\u0004","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב:\u0004 \u0003במה דברים אמורים\u0004 — \u0003ב\u0004אש \u0003קולחת, אבל ב\u0004אש שהיתה \u0003נכפפת ועצים מצויין לה\u0004 לבעור — \u0003אפילו עד מאה מיל\u0004 — \u0003חייב. עברה\u0004 האש \u0003נהר או שלולית שהם רחבים שמונה אמות\u0004 — \u0003פטור\u0004 בכל אש, לפי שבזה אין הבדל.","שנינו במשנה: עברה \u0003דרך הרבים\u0004 — פטור. ושואלים: \u0003מאן\u0004 \u0005[מי הוא]\u0006 ה\u0003תנא\u0004 הסבור כך? \u0003אמר רבא: ר' אליעזר היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 להלן ש\u0003ר' אליעזר אומר: שש עשרה אמות כדרך רשות הרבים\u0004 — \u0003(פטור),\u0004 משמע שזהו שיעורה של דרך הרבים, ושטח פנוי ברוחב זה אין אש עוברת כרגיל.","עוד שנינו במשנה: \u0003או\u0004 עברה האש \u0003נהר\u0004 — פטור. \u0003רב אמר: נהר\u0004 זה כוונתו נהר \u0003ממש. ושמואל אמר:\u0004 גם אם עברה האש \u0003אריתא דדלאי\u0004 (תעלת השקאה) — פטור.","ומעירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר,\u0006 רב\u0005]\u0006 \u0003נהר ממש\u0004 כוונתו: \u0003אף על גב דליכא מיא\u0004 \u0005[אף על פי שאין מים]\u0006 בתוך הנהר, כיון שהוא שטח עמוק ורחב אין האש עוברת בו כרגיל. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003אריתא דדלאי\u0004 (תעלת השקאה) סבור: אף נהר, \u0003אי אית ביה מיא\u0004 \u0005[אם יש בו מים]\u0006 — \u0003אין\u0004 \u0005[כן\u0006 פטור\u0005],\u0006 \u0003אבל\u0004 אם \u0003לית ביה מיא\u0004 \u0005[אין בו מים]\u0006 — \u0003לא\u0004 פטור.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה אחרת\u0005]:\u0006 \u0003ואלו מפסיקין לפאה,\u0004 כלומר, שחציצות אלה גורמות ששדה לא ייחשב ליחידה אחת לענין פאה, אלא יש לתת פאה מכל חלק לעצמו, ואלו הם: \u0003הנחל, והשלולית, ודרך היחיד, ודרך הרבים.\u0004","ושאלו: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003שלולית? אמר רב יהודה אמר שמואל: מקום שמי גשמים שוללין\u0004 (נאספים) \u0003שם,\u0004 \u0003רב ביבי אמר\u0004 בשם \u0003ר' יוחנן:\u0004 הכוונה היא ל\u0003אמת\u0004 (תעלת) \u0003המים שמחלקת שלל לאגפיה\u0004 (לצדיה), שהמים יוצאים ומתפשטים לבורות שבצידה.","ומעירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר,\u0006 שמואל\u0005]\u0006 \u0003מקום שמי גשמים שוללין שם\u0004 שהוא הפסק, \u0003כל שכן אמת המים\u0004 שהיא גדולה יותר וקבועה שהיא נחשבת הפסק, \u0003ומאן דאמר\u0004 \u0005[ומי שאומר\u0006 ר' יוחנן\u0005]\u0006 \u0003אמת המים,\u0004 לדעתו — \u0003אבל מקום שמי גשמים שוללין שם\u0004 — \u0003לא מפסקי\u0004 \u0005[מפסיקים],\u0006 \u0003דהנהו\u0004 \u0005[שהם]\u0006"],["\u0003באגני דארעא מקרו\u0004 \u0005[שקעים של הארץ נקראים]\u0006 ואינם נחשבים כהפסק בין חלקה לחלקה.","\u0003המדליק\u0004 אש \u0003בתוך שלו, עד כמה,\u0004 כלומר, איזה מרחק \u0003תעבור הדליקה\u0004 ויהא חייב עליה אם הזיק לאחרים, וביותר ממרחק זה — יהיה פטור? \u0003ר' אלעזר בן עזריה אומר: רואין אותו\u0004 במקום שהדליק את האש \u0003כאילו הוא\u0004 נמצא \u0003באמצע בית כור\u0004 ואם יש כדי מחצית בית כור ויותר משם עד למקום בו הזיקה לאחרים אינו חייב, שלא היה לו להביא בחשבון שתתפשט האש עד כדי כך. \u0003ר' אליעזר אומר:\u0004 חייב עד מרחק \u0003שש עשרה אמות, כדרך רשות הרבים. ר' עקיבא אומר:\u0004 עד \u0003חמשים אמה. ר' שמעון אומר:\u0004 נאמר \u0003\"שלם ישלם המבער את הבערה\"\u0004 (שמות כב, ה) ללמדנו: \u0003הכל לפי הדליקה.\u0004","מתחילה הבינו שר' שמעון סבור שאין נותנים שיעור כלל למרחק בין האש ומקום הנזק, וחייב על כל דליקה. ושואלים: \u0003ולית ליה\u0004 \u0005[ו\u0006כי \u0005אין לו]\u0006 \u0003לר' שמעון,\u0004 האם אינו מקבל את הדעה שיש \u0003שיעורא\u0004 \u0005[שיעור]\u0006 מירבי של מרחק לחייב \u0003בדליקה,\u0004 ולפטור אותו במקרה של שיעור גדול יותר, והוא מחייב בכל דליקה שהיא?","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003לא יעמיד אדם תנור בתוך הבית אלא אם כן יש על גבו גובה ארבע אמות\u0004 עד התקרה, שאם לא כן יש לחשוש שתאחז האש בתקרה וייגרם נזק לאחרים, וכן אם \u0003היה מעמידו בעלייה\u0004 (קומה עליונה) אין להניחו שם \u0003עד שיהא תחתיו,\u0004 תחת התנור, מקום \u0003מעזיבה\u0004 (טיט וטיח שעל גבי תקרת הקומה התחתונה) בעובי \u0003שלשה טפחים, ובכירה\u0004 (שהיא קטנה מתנור, וגם האש שבה קטנה מאש התנור) דיו בעובי \u0003טפח. ואם הזיק\u0004 — \u0003משלם מה שהזיק.\u0004","\u0003ר' שמעון אומר: לא נאמרו שיעורין הללו\u0004 של חכמים \u0003אלא שאם הזיק\u0004 כאשר נהג כדין — \u0003פטור מלשלם,\u0004 מפני שעשה את השמירה הדרושה. הרי שלדעת ר' שמעון יש שיעור מרחק לחיוב דליקה, ואינו חייב על כל דליקה!","\u0003אמר רב נחמן אמר רבה בר אבוה,\u0004 כך צריך להבין את דברי ר' שמעון שבמשנתנו: \u0003הכל לפי גובה הדליקה\u0004 שעשה מתחילה, שאם היתה דליקה קטנה בחצירו — אינו חייב עליה אם הלכה למרחק גדול, ואם היתה הדליקה גדולה — חייב עליה אף במרחק גדול.","\u0003אמר רב יוסף אמר רב יהודה אמר שמואל: הלכה כר' שמעון, וכן אמר רב נחמן אמר שמואל: הלכה כר' שמעון.\u0004","\u0003המדליק את הגדיש\u0004 של חטים או שעורים \u0003והיו\u0004 טמונים \u0003בו,\u0004 בתוך הגדיש, \u0003כלים\u0004 \u0003ודלקו,\u0004 נשרפו יחד עם הגדיש, \u0003ר' יהודה אומר: משלם\u0004 אף על \u0003מה שבתוכו, וחכמים אומרים: אינו משלם אלא\u0004 מחיר \u0003גדיש של חטין או של שעורין\u0004 כפי שהיה, ואינו אחראי על הטמון.","ועוד מקרה: \u0003היה גדי כפות\u0004 (קשור) \u0003לו\u0004 סמוך לגדיש, \u0003ועבד\u0004 שאינו כפות \u0003סמוך לו ונשרף עמו\u0004 — \u0003חייב\u0004 לשלם. היה \u0003עבד כפות לו\u0004 לצד הגדיש \u0003וגדי סמוך לו ונשרף עמו\u0004 — \u0003פטור\u0004 מתשלומים, כי חל עליו עונש מיתה על שגרם להמית את העבד, וכשעשה אדם מעשה שמתחייב עליו בשני עונשים — חיובו בעונש החמור יותר פוטרו מהעונש הקל יותר.","ובאשר לדין הראשון במשנה, אף שחכמים חולקים על ר' יהודה ופוטרים מלשלם על כלים שהיו טמונים בתוך גדיש בשדה, \u0003ומודים חכמים לר' יהודה במדליק את הבירה\u0004 (בית, ארמון), \u0003שהוא משלם\u0004 על \u0003כל מה ש\u0004היה \u0003בתוכה\u0004 ונשרף, \u0003שכן דרך בני אדם להניח בבתים,\u0004 ולכן המדליק חייב על כל מה שהיה שם.","\u0003אמר רב כהנא: מחלוקת\u0004 זו בין חכמים ור' יהודה בכלים הטמונים בגדיש — הריהי דווקא \u0003במדליק\u0004 אש \u0003בתוך שלו והלכה\u0004 האש \u0003ואכלה בתוך של חבירו,\u0004 ש\u0003ר' יהודה מחייב אנזקי\u0004 \u0005[על נזקי]\u0006 \u0003טמון באש, ורבנן פטרי\u0004 \u0005[וחכמים פוטרים],\u0006 \u0003אבל במדליק בתוך של חבירו\u0004 — \u0003דברי הכל,\u0004 ואף לדעת חכמים, \u0003משלם כל מה שבתוכו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אי הכי\u0004 \u0005[אם כך]\u0006 הוא הדבר שזו דעת חכמים, \u0003אדתני סיפא\u0004 \u0005[עד ש\u0006הוא \u0005שונה\u0006 ב\u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003מודים חכמים לר' יהודה במדליק את הבירה שמשלם כל מה שבתוכה, שכן דרך בני אדם להניח בבתים\u0004 — \u0003לפלוג וליתני בדידה\u0004 \u0005[שיחלק וישנה ב\u0006תוך הלכה זו \u0005עצמה]\u0006 במדליק גדיש, ויאמר כך: \u0003במה דברים אמורים\u0004 — \u0003במדליק\u0004 את האש \u0003בתוך שלו והלכה ואכלה בתוך של חבירו, אבל מדליק בתוך של חבירו\u0004 — \u0003דברי הכל משלם כל מה שהיה בתוכו!\u0004 וכיון שלא חילקו כך — מן הסתם לא כך סבורים חכמים.","\u0003אלא אמר רבא: בתרתי פליגי\u0004 \u0005[בשני\u0006 דברים \u0005חלוקים\u0006 הם\u0005],\u0006 \u0003פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006 \u0003במדליק בתוך שלו והלכה ואכלה בתוך של חבירו,\u0004 ש\u0003ר' יהודה מחייב\u0004 על \u0003טמון\u0004 \u0003באש, ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 כי \u0003לא מחייב\u0004 \u0005[חייב]\u0006 כלל. \u0003ופליגי נמי\u0004 \u0005[וחלוקים\u0006 הם \u0005גם]\u0006 \u0003במדליק בשל חבירו,\u0004 ש\u0003ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003משלם כל מה שבתוכו, ואפילו\u0004 היה גם \u0003ארנקי\u0004 (ארנק של כסף) טמון בתוך הגדיש, \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003כלים שדרכן להטמין בגדיש, כגון מוריגין\u0004 (כלי הדיש) \u0003וכלי בקר\u0004 (רתמות ושאר כלים) \u0003הוא\u0004 ש\u0003משלם,\u0004 ואילו \u0003כלים שאין דרכן להטמין בגדיש\u0004 — \u0003לא משלם.\u0004","ובאותה הלכה מוסיפים עוד, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המדליק את הגדיש והיו בו כלים ודלקו, ר' יהודה אומר: משלם כל מה שהיה בתוכו, וחכמים אומרים: אינו משלם אלא גדיש של חטין או גדיש של שעורין\u0004 ופטור על הכלים, כדין טמון. \u0003ו\u0004אולם \u0003רואין\u0004 את \u0003מקום\u0004 ה\u0003כלים\u0004 עצמם \u0003כאילו הוא מלא תבואה\u0004 ומשלם עבור גדיש שלם של תבואה, ואינו מנכה ממנו את דמי מקום הכלים, שבו לא היתה תבואה."]]};
